const c=4,n="khoa-hoc",h="Khoa học lớp 4",t="internal",i=[{id:"chat",title:"Chất",lessons:[{id:"kh4-tinh-chat-nuoc",title:"Bài 1: Tính chất của nước",weeks:[1,1],learn:[{title:"Nước trong suốt",text:"Nước sạch trong suốt, không màu, không mùi, không vị.",example:"💧 🥛"},{title:"Nước chảy",text:"Nước không có hình dạng nhất định. Nước chảy từ cao xuống thấp và lan ra mọi phía.",example:"⛰️ 💧 ⬇️"},{title:"Nước thấm và hòa tan",text:"Nước thấm qua một số vật như vải, giấy, đất. Nước hòa tan được một số chất như muối, đường.",example:"🧂 + 💧"}],practice:[{questions:[{id:"kh4-tinh-chat-nuoc-01",type:"mc",q:"Nước sạch có màu gì?",emoji:"🥛",options:["Màu trắng sữa","Màu xanh lá","Không màu","Màu vàng"],answer:2,explain:"Nước sạch không có màu, ta nhìn rõ vật đặt sau cốc nước."},{id:"kh4-tinh-chat-nuoc-02",type:"tf",q:"Nước sạch không có mùi.",answer:!0,explain:"Nước sạch không mùi; nước có mùi lạ thường là nước đã bị bẩn."},{id:"kh4-tinh-chat-nuoc-03",type:"tf",q:"Nước có hình dạng nhất định giống như hòn đá.",answer:!1,explain:"Nước không có hình dạng nhất định, nước có hình dạng của vật chứa nó."},{id:"kh4-tinh-chat-nuoc-04",type:"mc",q:"Đổ một ít nước lên mặt bàn phẳng, nước sẽ thế nào?",options:["Đứng yên thành một khối","Lan ra mọi phía","Bay ngược lên cao","Biến thành nước đá"],answer:1,explain:"Trên mặt phẳng, nước lan ra mọi phía."},{id:"kh4-tinh-chat-nuoc-05",type:"mc",q:"Nước chảy theo hướng nào?",options:["Từ chỗ cao xuống chỗ thấp","Từ chỗ thấp lên chỗ cao","Chỉ chảy sang bên trái","Nước không chảy được"],answer:0,explain:"Nước luôn chảy từ chỗ cao xuống chỗ thấp."},{id:"kh4-tinh-chat-nuoc-06",type:"fill",q:"Nước sạch không màu, không mùi và không … .",answer:["vị"],explain:"Nước sạch không màu, không mùi, không vị."},{id:"kh4-tinh-chat-nuoc-07",type:"multi",q:"Những chất nào hòa tan được trong nước?",options:["Cát","Dầu ăn","Đường","Muối ăn"],answers:[2,3],explain:"Muối và đường tan trong nước; cát và dầu ăn không tan."},{id:"kh4-tinh-chat-nuoc-08",type:"tf",q:"Nước thấm qua được khăn vải.",answer:!0,explain:"Khăn vải hút và cho nước thấm qua."}]},{questions:[{id:"kh4-tinh-chat-nuoc-09",type:"mc",q:"Vì sao mái nhà thường được làm dốc?",emoji:"🏠",options:["Để nước mưa đọng lại trên mái","Để nước mưa chảy xuống nhanh","Để mái nhà nặng hơn","Để nước mưa thấm vào mái"],answer:1,explain:"Nước chảy từ cao xuống thấp nên mái dốc giúp nước mưa thoát nhanh."},{id:"kh4-tinh-chat-nuoc-10",type:"mc",q:"Vì sao áo mưa được may bằng ni lông chứ không may bằng vải bông?",options:["Vì ni lông thấm nước rất nhanh","Vì ni lông tan trong nước","Vì vải bông không thấm nước","Vì nước không thấm qua ni lông"],answer:3,explain:"Nước không thấm qua ni lông nên người mặc áo mưa không bị ướt."},{id:"kh4-tinh-chat-nuoc-11",type:"match",q:"Nối hiện tượng với tính chất của nước.",pairs:[["Nước tràn ra khắp sàn","Lan ra mọi phía"],["Suối chảy từ núi xuống","Chảy từ cao xuống thấp"],["Khăn lau hút khô bàn","Thấm qua một số vật"],["Muối biến mất trong cốc nước","Hòa tan một số chất"]],explain:"Mỗi hiện tượng cho thấy một tính chất của nước."},{id:"kh4-tinh-chat-nuoc-12",type:"tf",q:"Rót nước từ chai sang bát thì nước có hình dạng của cái bát.",answer:!0,explain:"Nước không có hình dạng riêng, nước có hình dạng của vật chứa nó."},{id:"kh4-tinh-chat-nuoc-13",type:"multi",q:"Nước thấm qua được những vật nào?",options:["Túi ni lông","Tấm kính","Giấy vệ sinh","Đất xốp","Khăn bông"],answers:[2,3,4],explain:"Khăn bông, giấy vệ sinh, đất xốp thấm nước; ni lông và kính không cho nước thấm qua."},{id:"kh4-tinh-chat-nuoc-14",type:"mc",q:"Bỏ một thìa cát vào cốc nước rồi khuấy đều. Một lúc sau em thấy gì?",options:["Cát tan hết trong nước","Nước có vị ngọt","Cát biến thành hơi nước","Cát lắng xuống đáy cốc"],answer:3,explain:"Cát không tan trong nước nên lắng xuống đáy cốc."},{id:"kh4-tinh-chat-nuoc-15",type:"tf",q:"Dầu ăn tan hoàn toàn trong nước.",answer:!1,explain:"Dầu ăn không tan trong nước, dầu nổi thành lớp trên mặt nước."},{id:"kh4-tinh-chat-nuoc-16",type:"mc",q:"Nhờ tính chất nào của nước mà ta pha được nước đường?",options:["Nước chảy từ cao xuống thấp","Nước hòa tan được đường","Nước không có mùi","Nước thấm qua vải"],answer:1,explain:"Đường tan trong nước nên ta pha được nước đường."}]},{questions:[{id:"kh4-tinh-chat-nuoc-17",type:"order",q:"Sắp xếp các bước thí nghiệm kiểm tra nước có hòa tan muối không.",items:["Rót nước sạch vào cốc","Cho một thìa muối vào cốc","Dùng thìa khuấy đều","Quan sát xem còn thấy hạt muối không"],explain:"Rót nước, cho muối, khuấy rồi quan sát; không còn thấy hạt muối là muối đã tan."},{id:"kh4-tinh-chat-nuoc-18",type:"mc",q:"Lan đổ nước vào một cái khay đặt nghiêng. Nước sẽ dồn về đâu?",options:["Phía thấp của khay","Phía cao của khay","Giữ nguyên ở giữa khay","Bay lên khỏi khay"],answer:0,explain:"Nước chảy từ cao xuống thấp nên dồn về phía thấp của khay."},{id:"kh4-tinh-chat-nuoc-19",type:"mc",q:"Để nhận ra nước sạch, em dựa vào dấu hiệu nào?",options:["Nước có màu vàng nhạt, hơi đục","Nước có mùi lạ, hơi hôi","Nước có nhiều cặn lắng dưới đáy","Nước trong, không màu, không mùi lạ"],answer:3,explain:"Nước sạch trong suốt, không màu, không mùi."},{id:"kh4-tinh-chat-nuoc-20",type:"tf",q:"Đựng nước trong bình tròn hay hộp vuông thì nước vẫn có cùng một hình dạng.",answer:!1,explain:"Nước có hình dạng của vật chứa nên bình khác hình thì khối nước cũng khác hình."},{id:"kh4-tinh-chat-nuoc-21",type:"mc",q:"Nam làm đổ nước trên bàn. Dùng vật nào để lau khô nhanh nhất?",options:["Một tờ giấy bóng kính","Một miếng ni lông","Một tấm nhựa cứng","Khăn bông khô"],answer:3,explain:"Khăn bông thấm nước tốt nên lau khô nhanh."},{id:"kh4-tinh-chat-nuoc-22",type:"multi",q:"Hà khuấy từng chất vào các cốc nước. Ở cốc nào sẽ không còn nhìn thấy chất đã bỏ vào?",options:["Cốc bỏ đường","Cốc bỏ sỏi nhỏ","Cốc bỏ cát","Cốc bỏ muối"],answers:[0,3],explain:"Muối và đường tan trong nước; cát và sỏi không tan nên vẫn nhìn thấy."},{id:"kh4-tinh-chat-nuoc-23",type:"mc",q:"Rãnh thoát nước trong sân nên làm thế nào?",options:["Bằng phẳng hoàn toàn","Dốc ngược lên phía nhà","Cao hơn mặt sân","Hơi dốc dần về phía cống"],answer:3,explain:"Nước chảy từ cao xuống thấp nên rãnh dốc về cống giúp nước thoát nhanh."},{id:"kh4-tinh-chat-nuoc-24",type:"tf",q:"Có thể dùng vải để lọc bớt cát trong nước vì nước thấm qua vải còn cát bị giữ lại.",answer:!0,explain:"Nước thấm qua vải, hạt cát to hơn nên bị giữ lại trên vải."}]}],challenge:{questions:[{id:"kh4-tinh-chat-nuoc-25",type:"mc",q:"Bình rót nước vào một túi vải và một túi ni lông. Túi nào giữ được nước?",options:["Túi vải","Cả hai túi đều giữ được","Cả hai túi đều không giữ được","Túi ni lông"],answer:3,explain:"Nước thấm qua vải nhưng không thấm qua ni lông."},{id:"kh4-tinh-chat-nuoc-26",type:"mc",q:"Nhỏ vài giọt nước lên giấy thấm và lên tấm kính. Em thấy gì?",options:["Cả giấy thấm và tấm kính đều hút hết nước","Kính hút hết nước, còn giấy thấm thì không hút","Giấy thấm hút nước, còn trên kính nước đọng thành giọt","Nước biến mất ngay trên cả giấy thấm và kính"],answer:2,explain:"Nước thấm qua giấy thấm nhưng không thấm qua kính."},{id:"kh4-tinh-chat-nuoc-27",type:"order",q:"Sắp xếp các bước thí nghiệm chứng tỏ nước chảy từ cao xuống thấp.",items:["Đặt một tấm kính nghiêng trên khay","Rót nước lên phía cao của tấm kính","Quan sát hướng nước chảy","Rút ra kết luận"],explain:"Làm thí nghiệm, quan sát rồi mới rút ra kết luận."},{id:"kh4-tinh-chat-nuoc-28",type:"multi",q:"Những việc làm nào dựa vào tính chất nước chảy từ cao xuống thấp?",options:["Dùng khăn lau bàn","Làm rãnh thoát nước dốc về cống","Làm mái nhà dốc","Pha nước chanh với đường"],answers:[1,2],explain:"Mái dốc và rãnh dốc giúp nước chảy đi; pha nước chanh dựa vào sự hòa tan, lau bàn dựa vào sự thấm."},{id:"kh4-tinh-chat-nuoc-29",type:"multi",q:"Những việc làm nào dựa vào tính chất nước hòa tan một số chất?",options:["Pha nước đường","Pha nước muối để súc miệng","Làm mái nhà dốc","May áo mưa bằng ni lông"],answers:[0,1],explain:"Pha nước muối, nước đường là nhờ nước hòa tan muối và đường."},{id:"kh4-tinh-chat-nuoc-30",type:"tf",q:"Nước muối loãng và nước lọc đều trong suốt nên chỉ nhìn bằng mắt rất khó phân biệt.",answer:!0,explain:"Muối tan hết trong nước nên nước muối loãng vẫn trong suốt như nước lọc."}]},summary:["Nước sạch trong suốt, không màu, không mùi, không vị.","Nước không có hình dạng nhất định, chảy từ cao xuống thấp và lan ra mọi phía.","Nước thấm qua một số vật và hòa tan một số chất."]},{id:"kh4-chuyen-the-nuoc",title:"Bài 2: Sự chuyển thể của nước",weeks:[2,2],learn:[{title:"Ba thể của nước",text:"Nước có ba thể: thể rắn là nước đá, thể lỏng là nước, thể khí là hơi nước.",example:"🧊 💧 ☁️"},{title:"Bay hơi và ngưng tụ",text:"Nước lỏng biến thành hơi nước gọi là bay hơi. Hơi nước gặp lạnh biến thành nước lỏng gọi là ngưng tụ.",example:"💧 ➡️ ☁️ ➡️ 💧"},{title:"Đông đặc và nóng chảy",text:"Nước lỏng gặp lạnh biến thành nước đá gọi là đông đặc. Nước đá gặp nóng biến thành nước lỏng gọi là nóng chảy.",example:"💧 ➡️ 🧊 ➡️ 💧"}],practice:[{questions:[{id:"kh4-chuyen-the-nuoc-01",type:"match",q:"Nối mỗi thể của nước với ví dụ.",pairs:[["Thể rắn","Viên nước đá"],["Thể lỏng","Nước trong cốc"],["Thể khí","Hơi nước bốc lên từ nồi canh"]],explain:"Nước đá là thể rắn, nước trong cốc là thể lỏng, hơi nước là thể khí."},{id:"kh4-chuyen-the-nuoc-02",type:"tf",q:"Hơi nước là nước ở thể rắn.",answer:!1,explain:"Hơi nước là nước ở thể khí; nước đá mới là thể rắn."},{id:"kh4-chuyen-the-nuoc-03",type:"mc",q:"Nước lỏng biến thành hơi nước gọi là gì?",options:["Ngưng tụ","Đông đặc","Nóng chảy","Bay hơi"],answer:3,explain:"Nước lỏng chuyển thành hơi nước là sự bay hơi."},{id:"kh4-chuyen-the-nuoc-04",type:"mc",q:"Nước đá để ngoài trời nắng một lúc sẽ thế nào?",emoji:"🧊☀️",options:["Cứng hơn lúc đầu","To ra gấp đôi","Tan thành nước lỏng","Biến thành hạt cát"],answer:2,explain:"Gặp nóng, nước đá nóng chảy thành nước lỏng."},{id:"kh4-chuyen-the-nuoc-05",type:"fill",q:"Nước lỏng gặp lạnh biến thành nước đá gọi là sự đông … .",answer:["đặc"],explain:"Nước lỏng chuyển thành nước đá là sự đông đặc."},{id:"kh4-chuyen-the-nuoc-06",type:"tf",q:"Nước đá là nước ở thể lỏng.",answer:!1,explain:"Nước đá là nước ở thể rắn."},{id:"kh4-chuyen-the-nuoc-07",type:"mc",q:"Hơi nước gặp lạnh biến thành nước lỏng gọi là gì?",options:["Bay hơi","Nóng chảy","Ngưng tụ","Hòa tan"],answer:2,explain:"Hơi nước gặp lạnh chuyển thành nước lỏng là sự ngưng tụ."},{id:"kh4-chuyen-the-nuoc-08",type:"mc",q:"Nước có mấy thể?",options:["Ba thể","Một thể","Hai thể","Bốn thể"],answer:0,explain:"Nước có ba thể: rắn, lỏng và khí."}]},{questions:[{id:"kh4-chuyen-the-nuoc-09",type:"mc",q:"Vì sao quần áo phơi ngoài nắng thì khô?",emoji:"👕☀️",options:["Vì nước trong quần áo đông đặc","Vì nước trong quần áo bay hơi","Vì nước thấm ngược vào dây phơi","Vì nước biến thành nước đá"],answer:1,explain:"Nắng làm nước trong quần áo bay hơi nên quần áo khô."},{id:"kh4-chuyen-the-nuoc-10",type:"mc",q:"Úp một cái đĩa lên nồi nước đang sôi, mặt dưới đĩa có những giọt nước. Đó là hiện tượng gì?",options:["Nóng chảy","Đông đặc","Hòa tan","Ngưng tụ"],answer:3,explain:"Hơi nước gặp đĩa lạnh hơn nên ngưng tụ thành giọt nước."},{id:"kh4-chuyen-the-nuoc-11",type:"mc",q:"Cho khay nước vào ngăn đá tủ lạnh, vài giờ sau nước thế nào?",options:["Đông đặc thành nước đá","Bay hơi hết","Vẫn là nước lỏng như cũ","Biến thành hơi nước"],answer:0,explain:"Ngăn đá rất lạnh làm nước đông đặc thành nước đá."},{id:"kh4-chuyen-the-nuoc-12",type:"tf",q:"Cốc nước đá để ngoài không khí, mặt ngoài cốc có nước đọng là do nước trong cốc thấm ra.",emoji:"🥤",answer:!1,explain:"Hơi nước trong không khí gặp thành cốc lạnh nên ngưng tụ thành giọt nước bám ngoài cốc."},{id:"kh4-chuyen-the-nuoc-13",type:"match",q:"Nối hiện tượng với sự chuyển thể.",pairs:[["Kem để ngoài bị chảy","Nóng chảy"],["Sân ướt khô dần khi trời nắng","Bay hơi"],["Giọt nước bám trên nắp vung","Ngưng tụ"],["Làm đá viên trong tủ lạnh","Đông đặc"]],explain:"Mỗi hiện tượng là một sự chuyển thể của nước."},{id:"kh4-chuyen-the-nuoc-14",type:"tf",q:"Nước bay hơi chậm hơn khi trời nắng to và có gió.",answer:!1,explain:"Nắng và gió làm nước bay hơi nhanh hơn."},{id:"kh4-chuyen-the-nuoc-15",type:"multi",q:"Hiện tượng nào là sự bay hơi?",options:["Nước trong khay đóng thành đá","Kem que bị chảy","Mực nước trong nồi canh đang sôi giảm dần","Vũng nước trên sân cạn dần khi nắng lên"],answers:[2,3],explain:"Nước lỏng biến thành hơi nước ở hai hiện tượng đầu là sự bay hơi."},{id:"kh4-chuyen-the-nuoc-16",type:"mc",q:"Sự nóng chảy là nước chuyển từ thể nào sang thể nào?",options:["Từ thể lỏng sang thể rắn","Từ thể khí sang thể lỏng","Từ thể lỏng sang thể khí","Từ thể rắn sang thể lỏng"],answer:3,explain:"Nóng chảy là nước đá thể rắn chuyển thành nước lỏng."}]},{questions:[{id:"kh4-chuyen-the-nuoc-17",type:"order",q:"Sắp xếp các bước thí nghiệm quan sát sự ngưng tụ.",items:["Rót nước nóng vào cốc","Úp một chiếc đĩa lên miệng cốc","Đợi một lúc rồi nhấc đĩa ra","Quan sát mặt dưới đĩa"],explain:"Hơi nước bốc lên gặp đĩa mát hơn sẽ ngưng tụ thành giọt nước ở mặt dưới đĩa."},{id:"kh4-chuyen-the-nuoc-18",type:"mc",q:"Mẹ muốn phơi quần áo nhanh khô. Nên phơi ở đâu?",options:["Chỗ có nắng và thoáng gió","Trong góc phòng kín gió","Trong tủ quần áo đóng kín","Chỗ ẩm ướt, không có gió"],answer:0,explain:"Nắng và gió giúp nước bay hơi nhanh nên quần áo mau khô."},{id:"kh4-chuyen-the-nuoc-19",type:"mc",q:"Vì sao người ta làm muối bằng cách dẫn nước biển vào ruộng muối dưới trời nắng?",options:["Nước đông đặc thành muối","Muối ngưng tụ từ không khí","Nước bay hơi, muối còn lại","Nắng biến cát thành muối"],answer:2,explain:"Nắng làm nước biển bay hơi, muối không bay hơi nên đọng lại."},{id:"kh4-chuyen-the-nuoc-20",type:"tf",q:"Lau bảng bằng khăn ướt, một lúc sau bảng khô là do nước bay hơi.",answer:!0,explain:"Nước trên bảng bay hơi vào không khí nên bảng khô."},{id:"kh4-chuyen-the-nuoc-21",type:"mc",q:"Kính xe ô tô bị mờ hơi nước vào buổi sáng lạnh. Đó là do hiện tượng gì?",options:["Hơi nước ngưng tụ trên mặt kính lạnh","Mặt kính xe bị nóng chảy ra","Nước bên trong kính bị đông đặc","Tấm kính tự sinh ra nước"],answer:0,explain:"Hơi nước gặp mặt kính lạnh ngưng tụ thành những giọt nhỏ làm kính mờ."},{id:"kh4-chuyen-the-nuoc-22",type:"multi",q:"Muốn viên nước đá lâu tan, em nên làm gì?",options:["Đặt ngoài nắng","Để trong ngăn đá tủ lạnh","Đặt cạnh bếp đang đun","Để trong hộp xốp đậy kín"],answers:[1,3],explain:"Giữ nước đá ở chỗ lạnh hoặc trong hộp xốp kín thì đá lâu tan."},{id:"kh4-chuyen-the-nuoc-23",type:"order",q:"Sắp xếp sự chuyển thể khi lấy viên nước đá ra rồi đun nóng mãi.",items:["Nước ở thể rắn","Nước ở thể lỏng","Nước ở thể khí"],explain:"Nước đá nóng chảy thành nước lỏng, rồi nước lỏng bay hơi thành hơi nước."},{id:"kh4-chuyen-the-nuoc-24",type:"tf",q:"Đặt cốc nước ở chỗ râm thì nước trong cốc không bao giờ bay hơi.",answer:!1,explain:"Ở chỗ râm nước vẫn bay hơi, chỉ chậm hơn ở chỗ nắng."}]}],challenge:{questions:[{id:"kh4-chuyen-the-nuoc-25",type:"mc",q:"Hai đĩa nước như nhau, một đĩa để ngoài nắng, một đĩa để trong bóng râm. Sau một buổi, đĩa nào còn ít nước hơn?",options:["Đĩa để trong bóng râm","Hai đĩa còn bằng nhau","Đĩa để ngoài nắng","Không đĩa nào bị mất nước"],answer:2,explain:"Ở chỗ nắng nước bay hơi nhanh hơn nên đĩa đó còn ít nước hơn."},{id:"kh4-chuyen-the-nuoc-26",type:"mc",q:"Khi thở vào mặt gương lạnh, gương bị mờ. Vì sao?",options:["Mặt gương bị hơi thở làm nóng chảy","Hơi thở làm mặt gương bị bẩn","Hơi nước trong hơi thở ngưng tụ trên gương","Nước bên trong gương bay hơi ra"],answer:2,explain:"Hơi thở có hơi nước, gặp gương lạnh thì ngưng tụ thành giọt nhỏ."},{id:"kh4-chuyen-the-nuoc-27",type:"match",q:"Nối sự chuyển thể với điều kiện xảy ra.",pairs:[["Đông đặc","Nước lỏng gặp rất lạnh"],["Nóng chảy","Nước đá gặp nóng"],["Ngưng tụ","Hơi nước gặp lạnh"],["Bay hơi","Nước lỏng gặp nắng, gió"]],explain:"Gặp nóng hoặc lạnh, nước chuyển từ thể này sang thể khác."},{id:"kh4-chuyen-the-nuoc-28",type:"tf",q:"Khi nước chuyển thể, nước vẫn là nước, chỉ thay đổi trạng thái.",answer:!0,explain:"Nước đá, nước lỏng và hơi nước đều là nước ở các thể khác nhau."},{id:"kh4-chuyen-the-nuoc-29",type:"multi",q:"Những hiện tượng nào là sự ngưng tụ?",options:["Giọt sương đọng trên lá vào sáng sớm","Muối tan trong nước","Giọt nước bám trên nắp nồi","Bánh kem bị chảy"],answers:[0,2],explain:"Sương và giọt nước trên nắp nồi do hơi nước gặp lạnh ngưng tụ."},{id:"kh4-chuyen-the-nuoc-30",type:"mc",q:"Đun sôi một nồi nước khá lâu mà không đậy nắp, lượng nước trong nồi thế nào?",options:["Tăng dần","Giảm dần","Giữ nguyên","Biến thành nước đá"],answer:1,explain:"Nước sôi bay hơi mạnh nên lượng nước trong nồi giảm dần."}]},summary:["Nước có ba thể: rắn, lỏng, khí.","Gặp nóng hoặc lạnh, nước chuyển thể: bay hơi, ngưng tụ, đông đặc, nóng chảy.","Sự chuyển thể của nước có nhiều ứng dụng như phơi khô, làm muối, làm đá."]},{id:"kh4-vong-tuan-hoan",title:"Bài 3: Vòng tuần hoàn của nước",weeks:[3,3],learn:[{title:"Nước bay hơi",text:"Ánh nắng làm nước ở sông, hồ, biển bay hơi. Hơi nước bay lên cao.",example:"🌊 ☀️ ⬆️"},{title:"Mây và mưa",text:"Lên cao gặp lạnh, hơi nước ngưng tụ thành những hạt nước nhỏ tạo thành mây. Các hạt nước to dần rồi rơi xuống thành mưa.",example:"☁️ 🌧️"},{title:"Vòng tuần hoàn",text:"Nước mưa chảy ra sông, hồ, biển rồi lại bay hơi. Quá trình lặp đi lặp lại đó gọi là vòng tuần hoàn của nước trong tự nhiên.",example:"🌊 ➡️ ☁️ ➡️ 🌧️ ➡️ 🌊"}],practice:[{questions:[{id:"kh4-vong-tuan-hoan-01",type:"order",q:"Sắp xếp các giai đoạn của vòng tuần hoàn của nước.",items:["Nước ở sông, hồ, biển bay hơi","Hơi nước bay lên cao gặp lạnh","Hơi nước ngưng tụ thành mây","Mưa rơi xuống","Nước chảy về sông, hồ, biển"],explain:"Bay hơi, ngưng tụ thành mây, mưa rơi, nước chảy về sông biển rồi lại bay hơi."},{id:"kh4-vong-tuan-hoan-02",type:"mc",q:"Mây được tạo thành từ gì?",emoji:"☁️",options:["Những hạt cát","Khói từ bếp","Những hạt nước rất nhỏ","Bông gòn"],answer:2,explain:"Hơi nước ngưng tụ thành những hạt nước rất nhỏ, nhiều hạt tụ lại thành mây."},{id:"kh4-vong-tuan-hoan-03",type:"tf",q:"Hơi nước bay lên cao gặp lạnh sẽ ngưng tụ thành mây.",answer:!0,explain:"Trên cao lạnh nên hơi nước ngưng tụ thành các hạt nước nhỏ tạo thành mây."},{id:"kh4-vong-tuan-hoan-04",type:"mc",q:"Điều gì làm nước ở sông, hồ, biển bay hơi?",emoji:"☀️",options:["Ánh trăng","Ánh nắng Mặt Trời","Bóng tối","Đất đá"],answer:1,explain:"Ánh nắng làm nước nóng lên và bay hơi."},{id:"kh4-vong-tuan-hoan-05",type:"fill",q:"Các hạt nước trong mây to dần rồi rơi xuống thành … .",answer:["mưa"],explain:"Hạt nước trong mây to và nặng dần thì rơi xuống thành mưa."},{id:"kh4-vong-tuan-hoan-06",type:"tf",q:"Vòng tuần hoàn của nước chỉ xảy ra một lần rồi dừng lại.",answer:!1,explain:"Vòng tuần hoàn của nước diễn ra liên tục, lặp đi lặp lại."},{id:"kh4-vong-tuan-hoan-07",type:"multi",q:"Những hiện tượng nào có trong vòng tuần hoàn của nước?",options:["Nấu chín cơm","Hòa tan muối","Mưa rơi","Ngưng tụ","Bay hơi"],answers:[2,3,4],explain:"Vòng tuần hoàn gồm bay hơi, ngưng tụ thành mây và mưa rơi."},{id:"kh4-vong-tuan-hoan-08",type:"mc",q:"Nước mưa rơi xuống đất rồi chảy đi đâu?",options:["Bay thẳng lên tới Mặt Trời","Ra suối, sông, hồ rồi ra biển","Biến mất hoàn toàn mãi mãi","Biến thành đất đá ở trên núi"],answer:1,explain:"Nước mưa chảy thành suối, sông rồi đổ ra biển; một phần thấm xuống đất."}]},{questions:[{id:"kh4-vong-tuan-hoan-09",type:"mc",q:"Trong vòng tuần hoàn, nước từ mặt biển đi vào không khí nhờ hiện tượng nào?",options:["Đông đặc","Nóng chảy","Bay hơi","Hòa tan"],answer:2,explain:"Nước biển bay hơi thành hơi nước đi vào không khí."},{id:"kh4-vong-tuan-hoan-10",type:"mc",q:"Vì sao hơi nước bay lên cao lại tạo thành mây?",options:["Vì trên cao nóng nên hơi nước sôi","Vì gió biến hơi nước thành bụi","Vì hơi nước hòa tan vào đất","Vì trên cao lạnh nên hơi nước ngưng tụ"],answer:3,explain:"Gặp lạnh trên cao, hơi nước ngưng tụ thành những hạt nước nhỏ tạo thành mây."},{id:"kh4-vong-tuan-hoan-11",type:"match",q:"Nối mỗi giai đoạn với tên gọi.",pairs:[["Nước biển thành hơi nước","Bay hơi"],["Hơi nước thành hạt nước nhỏ trong mây","Ngưng tụ"],["Hạt nước to rơi xuống đất","Mưa"]],explain:"Ba giai đoạn chính là bay hơi, ngưng tụ và mưa."},{id:"kh4-vong-tuan-hoan-12",type:"tf",q:"Nước mưa hôm nay có thể từng là nước của biển, sông, hồ.",answer:!0,explain:"Nước bay hơi từ biển, sông, hồ rồi ngưng tụ thành mây và rơi xuống thành mưa."},{id:"kh4-vong-tuan-hoan-13",type:"tf",q:"Mây chính là hơi nước nên mắt ta không nhìn thấy mây.",answer:!1,explain:"Mây là những hạt nước nhỏ đã ngưng tụ nên ta nhìn thấy được; hơi nước thì không nhìn thấy."},{id:"kh4-vong-tuan-hoan-14",type:"mc",q:"Nhờ vòng tuần hoàn của nước mà điều gì xảy ra?",options:["Nước trên Trái Đất mất dần rồi hết","Biển ngày càng cạn khô","Sông suối ngừng chảy","Có mưa cung cấp nước cho sông, hồ và đất"],answer:3,explain:"Vòng tuần hoàn đưa nước trở lại mặt đất qua mưa."},{id:"kh4-vong-tuan-hoan-15",type:"mc",q:"Khi những hạt nước nhỏ trong mây nhập lại thành hạt to và nặng thì thế nào?",options:["Rơi xuống thành mưa","Bay cao hơn nữa","Biến thành khói","Đứng yên mãi trên trời"],answer:0,explain:"Hạt nước to và nặng không lơ lửng được nữa nên rơi xuống thành mưa."},{id:"kh4-vong-tuan-hoan-16",type:"multi",q:"Những câu nào nói đúng về mây?",options:["Mây gồm nhiều hạt nước nhỏ","Mây là khói từ nhà máy","Mây không liên quan gì đến mưa","Mây được tạo thành khi hơi nước ngưng tụ"],answers:[0,3],explain:"Mây do hơi nước ngưng tụ thành các hạt nước nhỏ, mây có thể cho mưa."}]},{questions:[{id:"kh4-vong-tuan-hoan-17",type:"order",q:"Sắp xếp thí nghiệm mô phỏng sự tạo thành mưa.",items:["Rót nước nóng vào cốc thủy tinh","Đặt lên miệng cốc một cái đĩa có vài viên đá","Hơi nước bốc lên gặp đáy đĩa lạnh","Giọt nước đọng dưới đĩa rồi nhỏ xuống"],explain:"Hơi nước gặp lạnh ngưng tụ thành giọt rồi rơi xuống, giống như mưa."},{id:"kh4-vong-tuan-hoan-18",type:"mc",q:"Bình đặt đĩa có đá lên cốc nước nóng, thấy giọt nước nhỏ xuống từ mặt dưới đĩa. Hiện tượng này giống điều gì trong tự nhiên?",options:["Gió thổi","Mưa rơi","Sấm chớp","Cầu vồng"],answer:1,explain:"Hơi nước gặp lạnh ngưng tụ thành giọt rồi rơi xuống giống như mưa."},{id:"kh4-vong-tuan-hoan-19",type:"mc",q:"Trong thí nghiệm trên, cái đĩa có đá lạnh giống với gì trong tự nhiên?",options:["Lớp không khí lạnh trên cao","Mặt biển rộng lớn","Ánh nắng Mặt Trời","Lòng đất sâu bên dưới"],answer:0,explain:"Đĩa lạnh làm hơi nước ngưng tụ giống như không khí lạnh trên cao."},{id:"kh4-vong-tuan-hoan-20",type:"tf",q:"Mây được tạo thành mà không cần nước bay hơi.",answer:!1,explain:"Phải có nước bay hơi thành hơi nước thì mới ngưng tụ thành mây."},{id:"kh4-vong-tuan-hoan-21",type:"mc",q:"Vào ngày nắng to, nước ở ao hồ bay hơi thế nào so với ngày râm mát?",options:["Ít hơn","Không bay hơi","Bằng nhau","Nhiều hơn"],answer:3,explain:"Trời càng nắng, nước bay hơi càng nhiều."},{id:"kh4-vong-tuan-hoan-22",type:"multi",q:"Vòng tuần hoàn của nước có ích gì cho sự sống?",options:["Làm đất đá tan ra","Làm đầy lại nước cho sông, hồ","Cung cấp nước mưa cho cây cối","Làm nước biển hết mặn"],answers:[1,2],explain:"Mưa tưới cho cây và bổ sung nước cho sông, hồ."},{id:"kh4-vong-tuan-hoan-23",type:"fill",q:"Nước bay hơi, ngưng tụ thành mây, rơi xuống thành mưa rồi lặp lại. Đó là vòng … của nước.",answer:["tuần hoàn"],explain:"Quá trình lặp lại liên tục đó là vòng tuần hoàn của nước."},{id:"kh4-vong-tuan-hoan-24",type:"tf",q:"Nước mưa rơi xuống chỉ chảy trên mặt đất, không thấm xuống đất.",answer:!1,explain:"Một phần nước mưa thấm xuống đất tạo thành nước ngầm."}]}],challenge:{questions:[{id:"kh4-vong-tuan-hoan-25",type:"mc",q:"Một vũng nước trên sân xi măng biến mất sau buổi trưa nắng. Nước đã đi đâu?",options:["Chui xuống tâm Trái Đất","Bay hơi vào không khí","Biến thành đá","Bị nắng đốt cháy"],answer:1,explain:"Nắng làm nước trong vũng bay hơi vào không khí."},{id:"kh4-vong-tuan-hoan-26",type:"order",q:"Sắp xếp chặng đường của một giọt nước từ biển rồi trở về biển.",items:["Giọt nước ở biển","Hơi nước bay lên","Hạt nước nhỏ trong mây","Giọt mưa rơi xuống núi","Nước chảy theo suối, sông","Giọt nước về lại biển"],explain:"Giọt nước bay hơi, ngưng tụ thành mây, rơi xuống thành mưa rồi chảy về biển."},{id:"kh4-vong-tuan-hoan-27",type:"match",q:"Nối mỗi nơi với dạng nước có ở đó.",pairs:[["Đám mây","Những hạt nước nhỏ"],["Không khí trên mặt biển","Hơi nước"],["Dòng sông","Nước lỏng đang chảy"]],explain:"Trong vòng tuần hoàn, nước có mặt ở nhiều nơi với các dạng khác nhau."},{id:"kh4-vong-tuan-hoan-28",type:"tf",q:"Nhờ vòng tuần hoàn, nước trên Trái Đất không mất đi mà chuyển từ nơi này sang nơi khác.",answer:!0,explain:"Nước bay hơi, tạo mây, rơi xuống rồi lại bay hơi, nên nước luôn được tuần hoàn."},{id:"kh4-vong-tuan-hoan-29",type:"multi",q:"Trong vòng tuần hoàn, những giai đoạn nào cần sự nóng lên hoặc lạnh đi?",options:["Hơi nước ngưng tụ khi gặp lạnh","Nước chảy từ núi xuống","Nước bay hơi nhờ nắng","Nước mưa thấm vào đất"],answers:[0,2],explain:"Bay hơi cần nóng, ngưng tụ cần lạnh; nước chảy và thấm không cần thay đổi nhiệt độ."},{id:"kh4-vong-tuan-hoan-30",type:"mc",q:"Vì sao nước mưa không mặn dù rất nhiều hơi nước bay lên từ biển?",options:["Vì gió đã thổi bay hết muối đi","Vì khi nước bay hơi, muối ở lại biển","Vì muối rơi xuống đất trước nước","Vì nước biển vốn không có muối"],answer:1,explain:"Chỉ có nước bay hơi, muối không bay hơi nên nước mưa không mặn."}]},summary:["Nước bay hơi, hơi nước ngưng tụ thành mây, mây cho mưa, nước chảy về sông biển.","Quá trình đó lặp đi lặp lại gọi là vòng tuần hoàn của nước.","Vòng tuần hoàn mang nước mưa đến cho cây cối, con người và động vật."]},{id:"kh4-vai-tro-nuoc",title:"Bài 4: Vai trò của nước và sử dụng nước tiết kiệm",weeks:[4,4],learn:[{title:"Nước với sự sống",text:"Con người, động vật và thực vật đều cần nước để sống. Thiếu nước, sinh vật sẽ chết.",example:"🧍 🐄 🌱 💧"},{title:"Nước trong đời sống",text:"Nước dùng để ăn uống, tắm giặt, vệ sinh; tưới cây, chăn nuôi; làm ra điện và đi lại bằng tàu thuyền.",example:"🚿 🌾 ⚡ ⛵"},{title:"Tiết kiệm nước",text:"Khóa vòi khi không dùng, sửa chỗ rò rỉ, tận dụng nước vo gạo, nước rửa rau để tưới cây.",example:"🚰 ✋"}],practice:[{questions:[{id:"kh4-vai-tro-nuoc-01",type:"tf",q:"Con người, động vật và thực vật đều cần nước để sống.",answer:!0,explain:"Mọi sinh vật đều cần nước; thiếu nước sinh vật sẽ chết."},{id:"kh4-vai-tro-nuoc-02",type:"multi",q:"Những việc nào cần dùng nước trong gia đình?",options:["Rửa rau","Nấu cơm","Đọc sách","Gấp chăn","Tắm giặt"],answers:[0,1,4],explain:"Nấu cơm, tắm giặt, rửa rau đều cần nước."},{id:"kh4-vai-tro-nuoc-03",type:"mc",q:"Người nông dân dùng nước để làm gì trên đồng ruộng?",emoji:"🌾",options:["Sơn nhà","Tưới cho cây trồng","Làm đường","Đốt rơm"],answer:1,explain:"Cây trồng cần nước nên người nông dân tưới nước cho ruộng."},{id:"kh4-vai-tro-nuoc-04",type:"mc",q:"Nước ở những con sông lớn giúp con người làm gì?",emoji:"⛵",options:["Bay lên bầu trời","Làm khô quần áo","Xây dựng đường bộ","Đi lại bằng tàu thuyền"],answer:3,explain:"Tàu thuyền đi lại trên sông để chở người và hàng hóa."},{id:"kh4-vai-tro-nuoc-05",type:"tf",q:"Cây không được tưới nước lâu ngày sẽ bị héo.",answer:!0,explain:"Thiếu nước, cây bị héo và có thể chết."},{id:"kh4-vai-tro-nuoc-06",type:"mc",q:"Việc làm nào giúp tiết kiệm nước?",options:["Khóa vòi nước khi đang chải răng","Để vòi chảy suốt lúc đánh răng","Rửa xe hằng ngày dù xe còn sạch","Tắm thật lâu dưới vòi"],answer:0,explain:"Khóa vòi khi không dùng giúp không lãng phí nước."},{id:"kh4-vai-tro-nuoc-07",type:"fill",q:"Để tiết kiệm nước, em … vòi nước khi không dùng.",answer:["khóa","tắt","đóng"],explain:"Khóa vòi khi không dùng để nước không chảy phí."},{id:"kh4-vai-tro-nuoc-08",type:"tf",q:"Nước chỉ cần cho con người, cây cối thì không cần nước.",answer:!1,explain:"Cây cối cũng cần nước để sống và lớn lên."}]},{questions:[{id:"kh4-vai-tro-nuoc-09",type:"match",q:"Nối nơi dùng nước với việc dùng nước.",pairs:[["Gia đình","Nấu ăn, tắm giặt"],["Đồng ruộng","Tưới cây"],["Trang trại","Cho vật nuôi uống"],["Nhà máy thủy điện","Làm ra điện"]],explain:"Nước được dùng trong sinh hoạt, trồng trọt, chăn nuôi và sản xuất điện."},{id:"kh4-vai-tro-nuoc-10",type:"mc",q:"Vì sao mỗi ngày cần uống đủ nước?",options:["Vì nước giúp ta no bụng thay cho cơm","Vì uống nước làm ta cao lên ngay lập tức","Vì uống nước thay được việc tắm rửa","Vì cơ thể cần nước để hoạt động bình thường"],answer:3,explain:"Nước tham gia vào mọi hoạt động của cơ thể nên cần uống đủ nước."},{id:"kh4-vai-tro-nuoc-11",type:"tf",q:"Nhà máy thủy điện dùng sức gió để làm ra điện.",emoji:"⚡",answer:!1,explain:"Nhà máy thủy điện dùng sức nước chảy để làm ra điện."},{id:"kh4-vai-tro-nuoc-12",type:"multi",q:"Những việc làm nào gây lãng phí nước?",options:["Dùng cốc khi đánh răng","Hứng nước mưa để tưới cây","Để vòi nước rò rỉ mà không sửa","Mở vòi chảy liên tục khi rửa bát"],answers:[2,3],explain:"Để nước chảy liên tục hoặc rò rỉ là lãng phí nước."},{id:"kh4-vai-tro-nuoc-13",type:"mc",q:"Nước vo gạo có thể dùng lại vào việc gì?",options:["Uống","Đánh răng","Pha sữa","Tưới cây"],answer:3,explain:"Nước vo gạo không dùng để uống nhưng có thể dùng tưới cây."},{id:"kh4-vai-tro-nuoc-14",type:"tf",q:"Nước sạch dùng mãi không hết nên không cần tiết kiệm.",answer:!1,explain:"Nước sạch không phải vô tận, nhiều nơi đang thiếu nước sạch, nên cần tiết kiệm."},{id:"kh4-vai-tro-nuoc-15",type:"mc",q:"Vì sao cá chết khi ao cạn khô?",emoji:"🐟",options:["Vì cá cần sống trong nước","Vì cá bị lạnh","Vì cá thích nắng","Vì cá không có đồ chơi"],answer:0,explain:"Cá sống trong nước, ao cạn thì cá không sống được."},{id:"kh4-vai-tro-nuoc-16",type:"mc",q:"Minh tắm bằng vòi hoa sen. Cách nào tiết kiệm nước?",options:["Mở vòi to suốt lúc tắm","Tắm thật lâu cho mát","Khóa vòi khi xoa xà phòng","Để vòi chảy khi đi lấy khăn"],answer:2,explain:"Khóa vòi lúc không cần nước sẽ bớt lãng phí."}]},{questions:[{id:"kh4-vai-tro-nuoc-17",type:"mc",q:"Ở trường, em thấy một vòi nước bị rò rỉ. Em nên làm gì?",options:["Mặc kệ vì không phải nhà mình","Mở vòi to hơn","Nhét giấy vào vòi rồi đi","Báo cho thầy cô hoặc bác bảo vệ"],answer:3,explain:"Báo người lớn để sửa vòi kịp thời, tránh lãng phí nước."},{id:"kh4-vai-tro-nuoc-18",type:"multi",q:"Nhà Lan muốn tận dụng nước. Cách nào hợp lí?",options:["Dùng nước vo gạo tưới cây","Hứng nước mưa để tưới vườn","Uống ngay nước mưa hứng từ mái nhà","Dùng lại nước rửa bát để nấu canh"],answers:[0,1],explain:"Nước đã dùng hoặc nước mưa có thể tưới cây, nhưng không dùng để ăn uống khi chưa xử lí."},{id:"kh4-vai-tro-nuoc-19",type:"mc",q:"Một mảnh vườn khô hạn nhiều ngày. Điều gì có thể xảy ra?",options:["Cây lớn nhanh hơn trước","Cây héo, chậm lớn hoặc chết","Cây ra nhiều quả hơn","Cây không thay đổi gì cả"],answer:1,explain:"Thiếu nước, cây không sống và phát triển bình thường được."},{id:"kh4-vai-tro-nuoc-20",type:"tf",q:"Rửa rau trong chậu rồi dùng nước đó tưới cây là cách tiết kiệm nước.",answer:!0,explain:"Rửa trong chậu tốn ít nước hơn, nước còn dùng lại để tưới cây."},{id:"kh4-vai-tro-nuoc-21",type:"order",q:"Sắp xếp các bước rửa tay tiết kiệm nước.",items:["Mở vòi làm ướt tay","Khóa vòi rồi xoa xà phòng","Mở vòi xả sạch xà phòng","Khóa vòi và lau khô tay"],explain:"Khóa vòi trong lúc xoa xà phòng giúp tiết kiệm nước."},{id:"kh4-vai-tro-nuoc-22",type:"mc",q:"Vì sao vào mùa khô, nhiều nơi thiếu nước sinh hoạt?",options:["Vì ít mưa nên sông, hồ, giếng cạn dần","Vì mọi người không thích dùng nước","Vì nước biến thành đá","Vì cây cối uống hết nước biển"],answer:0,explain:"Mùa khô ít mưa nên nguồn nước cạn dần."},{id:"kh4-vai-tro-nuoc-23",type:"match",q:"Nối việc làm với lợi ích.",pairs:[["Khóa vòi khi đánh răng","Bớt nước chảy phí"],["Sửa ống nước bị rò","Không để nước rỉ mất"],["Hứng nước mưa","Có thêm nước tưới cây"]],explain:"Mỗi việc nhỏ đều giúp tiết kiệm nước."},{id:"kh4-vai-tro-nuoc-24",type:"number",q:"Giả sử để vòi chảy khi đánh răng tốn 6 lít nước, còn dùng cốc chỉ tốn 1 lít. Mỗi lần dùng cốc tiết kiệm được bao nhiêu lít nước?",answer:5,unit:"lít",explain:"Số nước tiết kiệm được là 6 − 1 = 5 lít."}]}],challenge:{questions:[{id:"kh4-vai-tro-nuoc-25",type:"mc",q:"Nhà Dũng tạm thời có rất ít nước. Nên ưu tiên dùng nước vào việc gì?",options:["Ăn uống và nấu ăn","Rửa xe","Tưới cỏ trang trí","Tắm thật lâu"],answer:0,explain:"Nước uống và nấu ăn cần thiết nhất cho sức khỏe."},{id:"kh4-vai-tro-nuoc-26",type:"number",q:"Giả sử một vòi nước rò rỉ mất 2 lít mỗi giờ. Sau 5 giờ, vòi đó làm mất bao nhiêu lít nước?",answer:10,unit:"lít",explain:"Số nước bị mất là 2 × 5 = 10 lít."},{id:"kh4-vai-tro-nuoc-27",type:"multi",q:"Nước có vai trò gì với thực vật?",options:["Thay thế ánh sáng cho cây","Hòa tan chất khoáng để rễ cây hút được","Giúp cây không bị héo","Làm cây không cần không khí"],answers:[1,2],explain:"Cây hút nước cùng chất khoáng hòa tan; đủ nước cây tươi tốt."},{id:"kh4-vai-tro-nuoc-28",type:"tf",q:"Người có thể nhịn ăn lâu hơn nhịn uống nước.",answer:!0,explain:"Thiếu nước, cơ thể suy yếu rất nhanh, nhanh hơn nhiều so với thiếu thức ăn."},{id:"kh4-vai-tro-nuoc-29",type:"order",q:"Sắp xếp các bước tận dụng nước rửa rau để tưới cây.",items:["Rửa rau trong chậu","Để riêng chậu nước đã rửa","Mang nước ra gốc cây","Tưới đều quanh gốc"],explain:"Rửa rau trong chậu giúp giữ lại nước để tưới cây."},{id:"kh4-vai-tro-nuoc-30",type:"mc",q:"Khoa nói: “Nhà mình có giếng nên dùng bao nhiêu nước cũng được.” Em khuyên Khoa thế nào?",options:["Đúng rồi, nước giếng không bao giờ cạn hết","Nước giếng cũng có thể cạn, cần dùng tiết kiệm","Nên bơm thật nhiều nước giếng rồi đổ đi","Chỉ có nước máy mới cần dùng tiết kiệm"],answer:1,explain:"Mọi nguồn nước đều có hạn nên cần dùng tiết kiệm."}]},summary:["Nước cần cho sự sống của con người, động vật và thực vật.","Nước dùng trong sinh hoạt, trồng trọt, chăn nuôi, sản xuất và giao thông.","Em sử dụng nước tiết kiệm: khóa vòi, sửa chỗ rò rỉ, tận dụng nước."]},{id:"kh4-o-nhiem-nuoc",title:"Bài 5: Ô nhiễm, làm sạch và bảo vệ nguồn nước",weeks:[5,6],learn:[{title:"Nước bị ô nhiễm",text:"Nước bị ô nhiễm thường có màu lạ, có mùi hôi, có rác, chất bẩn hoặc vi khuẩn gây bệnh.",example:"🚱"},{title:"Nguyên nhân",text:"Rác thải, nước thải sinh hoạt, nước thải nhà máy chưa xử lí, phân bón và thuốc trừ sâu dùng quá nhiều làm nguồn nước bị ô nhiễm.",example:"🗑️ 🏭 ➡️ 🏞️"},{title:"Làm sạch nước",text:"Lọc nước giúp loại bỏ các chất không tan. Đun sôi nước giúp diệt vi khuẩn.",example:"🫙 🔥"},{title:"Bảo vệ nguồn nước",text:"Không vứt rác xuống ao hồ, sông suối; xử lí nước thải; giữ vệ sinh quanh giếng và bể nước.",example:"🏞️ 💚"}],practice:[{questions:[{id:"kh4-o-nhiem-nuoc-01",type:"multi",q:"Dấu hiệu nào cho thấy nước bị ô nhiễm?",options:["Không mùi","Có mùi hôi","Có màu đục","Có rác nổi","Trong suốt"],answers:[1,2,3],explain:"Nước ô nhiễm thường đục, có mùi hôi hoặc có rác."},{id:"kh4-o-nhiem-nuoc-02",type:"mc",q:"Việc làm nào làm ô nhiễm nguồn nước?",options:["Trồng cây ven sông","Vớt rác trên mặt hồ","Bỏ rác vào thùng","Vứt rác xuống sông"],answer:3,explain:"Rác vứt xuống sông làm nước sông bị bẩn."},{id:"kh4-o-nhiem-nuoc-03",type:"tf",q:"Dùng nước bị ô nhiễm có thể bị đau bụng, tiêu chảy.",answer:!0,explain:"Nước bẩn có vi khuẩn gây bệnh đường tiêu hóa."},{id:"kh4-o-nhiem-nuoc-04",type:"mc",q:"Cách nào diệt được vi khuẩn trong nước uống?",emoji:"🔥",options:["Để nước vào tủ lạnh","Khuấy nước thật đều","Đun sôi nước","Đổ nước ra chậu"],answer:2,explain:"Đun sôi giúp diệt vi khuẩn trong nước."},{id:"kh4-o-nhiem-nuoc-05",type:"fill",q:"Lọc nước giúp loại bỏ các chất không … trong nước.",answer:["tan"],explain:"Lọc giữ lại các chất không tan như cát, đất, cặn bẩn."},{id:"kh4-o-nhiem-nuoc-06",type:"tf",q:"Nước thải nhà máy chưa xử lí đổ ra sông làm nước sông bị ô nhiễm.",answer:!0,explain:"Nước thải chưa xử lí chứa nhiều chất độc hại."},{id:"kh4-o-nhiem-nuoc-07",type:"mc",q:"Việc làm nào bảo vệ nguồn nước?",options:["Không xả rác xuống ao, hồ","Đổ dầu thải xuống cống","Làm chuồng trại sát giếng","Giặt giũ ngay miệng giếng"],answer:0,explain:"Giữ ao hồ sạch rác là bảo vệ nguồn nước."},{id:"kh4-o-nhiem-nuoc-08",type:"tf",q:"Nước trong veo thì chắc chắn sạch, uống ngay không cần đun.",answer:!1,explain:"Nước trong vẫn có thể có vi khuẩn mà mắt không nhìn thấy, nên cần đun sôi."}]},{questions:[{id:"kh4-o-nhiem-nuoc-09",type:"match",q:"Nối cách làm sạch nước với tác dụng.",pairs:[["Lọc qua bông, cát, sỏi","Giữ lại chất không tan"],["Đun sôi","Diệt vi khuẩn"],["Để yên một thời gian","Cặn nặng chìm xuống đáy"]],explain:"Mỗi cách làm sạch nước có tác dụng riêng."},{id:"kh4-o-nhiem-nuoc-10",type:"mc",q:"Vì sao phải đun sôi nước rồi mới uống?",options:["Để nước có màu đẹp","Để nước ngọt hơn","Để nước nhiều hơn","Để diệt vi khuẩn gây bệnh"],answer:3,explain:"Nhiệt độ cao khi đun sôi diệt được vi khuẩn."},{id:"kh4-o-nhiem-nuoc-11",type:"mc",q:"Bình lọc nước đơn giản thường có những lớp vật liệu nào?",options:["Muối, đường, bột mì","Giấy màu, nhựa, sắt","Bông, cát, sỏi, than hoạt tính","Lá cây, đất sét, phân bón"],answer:2,explain:"Các lớp bông, cát, sỏi, than giữ lại chất bẩn khi nước chảy qua."},{id:"kh4-o-nhiem-nuoc-12",type:"tf",q:"Lọc nước bằng cát và sỏi giúp diệt hết vi khuẩn trong nước.",answer:!1,explain:"Lọc chỉ giữ lại chất không tan; muốn diệt vi khuẩn cần đun sôi."},{id:"kh4-o-nhiem-nuoc-13",type:"multi",q:"Nguồn nước nào dễ bị ô nhiễm?",options:["Bể nước có nắp đậy kín","Ao ở cạnh bãi rác","Kênh nhận nước thải chưa xử lí","Giếng có nắp và giữ sạch xung quanh"],answers:[1,2],explain:"Nguồn nước gần rác và nước thải dễ bị ô nhiễm."},{id:"kh4-o-nhiem-nuoc-14",type:"mc",q:"Vì sao không nên tắm ở ao hồ bị ô nhiễm?",options:["Vì nước ao hồ đó quá trong","Vì có thể mắc bệnh ngoài da, đau mắt","Vì nước ao hồ đó không có màu","Vì ao hồ đó không có con cá nào"],answer:1,explain:"Nước ô nhiễm có vi khuẩn, chất bẩn gây bệnh da và mắt."},{id:"kh4-o-nhiem-nuoc-15",type:"tf",q:"Thu gom rác và xử lí nước thải trước khi đổ ra sông là bảo vệ nguồn nước.",answer:!0,explain:"Xử lí nước thải giúp nước sông không bị ô nhiễm."},{id:"kh4-o-nhiem-nuoc-16",type:"mc",q:"Lọc nước đục qua bông hoặc vải sạch, nước chảy ra thế nào?",options:["Đục hơn lúc đầu","Mặn hơn lúc đầu","Trong hơn lúc đầu","Biến thành hơi nước"],answer:2,explain:"Bông, vải giữ lại bớt chất bẩn không tan nên nước trong hơn."}]},{questions:[{id:"kh4-o-nhiem-nuoc-17",type:"order",q:"Sắp xếp các bước làm sạch nước sông để có nước uống.",items:["Để nước lắng cho cặn chìm xuống","Lọc nước qua bình lọc","Đun sôi nước","Để nguội rồi uống"],explain:"Lắng và lọc làm nước trong, đun sôi để diệt vi khuẩn."},{id:"kh4-o-nhiem-nuoc-18",type:"mc",q:"Gần nhà Dũng có người đổ rác xuống mương. Dũng nên làm gì?",options:["Đổ thêm rác cho đầy mương","Báo cho người lớn để nhắc nhở","Coi như không nhìn thấy gì","Cãi nhau thật to với người đó"],answer:1,explain:"Báo người lớn để cùng nhắc nhở, bảo vệ nguồn nước."},{id:"kh4-o-nhiem-nuoc-19",type:"multi",q:"Nhà Ngọc có giếng nước. Những việc nào giúp giữ nước giếng sạch?",options:["Đậy nắp giếng","Không đổ nước bẩn quanh miệng giếng","Làm chuồng gà sát giếng","Vứt lá cây xuống giếng"],answers:[0,1],explain:"Đậy nắp và giữ sạch quanh giếng giúp chất bẩn không lọt vào."},{id:"kh4-o-nhiem-nuoc-20",type:"mc",q:"Sau khi lọc, nước đục đã trở nên trong. Muốn uống được, cần làm gì nữa?",options:["Uống ngay","Thêm muối","Để vào tủ lạnh là đủ","Đun sôi"],answer:3,explain:"Lọc chưa diệt được vi khuẩn nên phải đun sôi."},{id:"kh4-o-nhiem-nuoc-21",type:"tf",q:"Phun thuốc trừ sâu quá nhiều có thể làm ô nhiễm nước ở ruộng và kênh mương.",answer:!0,explain:"Thuốc trừ sâu thừa theo nước mưa chảy xuống kênh mương."},{id:"kh4-o-nhiem-nuoc-22",type:"mc",q:"Một con sông có nhiều cá chết, nước đen và hôi. Lí do hợp lí nhất là gì?",options:["Nước sông bị ô nhiễm nặng","Trời mưa to","Cá thích nước đen","Hai bên bờ có nhiều cây xanh"],answer:0,explain:"Nước đen, hôi và cá chết là dấu hiệu nước bị ô nhiễm nặng."},{id:"kh4-o-nhiem-nuoc-23",type:"match",q:"Nối việc làm với kết quả.",pairs:[["Vứt rác xuống hồ","Nước hồ bị ô nhiễm"],["Đun sôi nước","Diệt vi khuẩn"],["Đậy nắp bể nước","Bụi bẩn khó rơi vào"]],explain:"Việc làm tốt giữ nước sạch, việc làm xấu làm nước ô nhiễm."},{id:"kh4-o-nhiem-nuoc-24",type:"multi",q:"Vì sao cần bảo vệ nguồn nước?",options:["Để nước có màu đẹp hơn","Để có nước sạch dùng hằng ngày","Để con người và sinh vật khỏe mạnh","Để không phải dùng nước nữa"],answers:[1,2],explain:"Nước sạch rất cần cho sức khỏe và sự sống."}]}],challenge:{questions:[{id:"kh4-o-nhiem-nuoc-25",type:"mc",q:"Có hai cốc nước giếng: cốc A trong nhưng chưa đun, cốc B đã đun sôi để nguội. Nên uống cốc nào?",options:["Cốc A","Cả hai cốc đều được","Không cốc nào uống được","Cốc B"],answer:3,explain:"Nước đã đun sôi đã được diệt vi khuẩn nên an toàn hơn."},{id:"kh4-o-nhiem-nuoc-26",type:"order",q:"Sắp xếp các bước làm thí nghiệm lọc nước đục.",items:["Cắt đáy chai nhựa rồi úp ngược chai","Cho lần lượt bông, cát, sỏi vào chai","Rót nước đục vào chai","Hứng và quan sát nước chảy ra"],explain:"Chuẩn bị bình lọc trước, rồi mới rót nước và quan sát."},{id:"kh4-o-nhiem-nuoc-27",type:"tf",q:"Nước lọc qua cát, sỏi đã trong thì uống ngay được, không cần đun.",answer:!1,explain:"Nước lọc xong vẫn có thể còn vi khuẩn, cần đun sôi trước khi uống."},{id:"kh4-o-nhiem-nuoc-28",type:"multi",q:"Những việc làm nào giúp bảo vệ nguồn nước?",options:["Xả nước thải thẳng ra ao","Dùng phân bón vừa đủ cho ruộng","Không đổ dầu mỡ thừa xuống cống","Vứt túi ni lông xuống kênh"],answers:[1,2],explain:"Hạn chế chất thải đi vào nước là bảo vệ nguồn nước."},{id:"kh4-o-nhiem-nuoc-29",type:"mc",q:"Vì sao nước thải nhà máy phải được xử lí trước khi thải ra môi trường?",options:["Để không làm ô nhiễm sông, hồ","Để nước thải nhiều hơn","Để nhà máy chạy nhanh hơn","Để nước thải có màu đẹp"],answer:0,explain:"Nước thải chưa xử lí có chất độc làm ô nhiễm nguồn nước."},{id:"kh4-o-nhiem-nuoc-30",type:"mc",q:"Lớp than hoạt tính trong bình lọc nước có tác dụng gì?",options:["Làm cho nước mặn hơn","Làm cho nước nóng lên","Làm cho nước có màu đen","Giữ lại bớt chất bẩn và khử mùi"],answer:3,explain:"Than hoạt tính giữ lại một số chất bẩn và làm nước bớt mùi."}]},summary:["Nước bị ô nhiễm do rác, nước thải, phân bón, thuốc trừ sâu.","Lọc nước loại bỏ chất không tan, đun sôi diệt vi khuẩn.","Mỗi người cần giữ sạch nguồn nước quanh mình."]},{id:"kh4-khong-khi",title:"Bài 6: Thành phần và tính chất của không khí",weeks:[7,7],learn:[{title:"Không khí ở quanh ta",text:"Không khí có ở khắp nơi, cả trong những chỗ rỗng của đất, của miếng bọt biển, của chai rỗng.",example:"🫧"},{title:"Thành phần",text:"Không khí gồm chủ yếu là khí ni-tơ và khí ô-xi; ngoài ra có khí các-bô-níc, hơi nước, bụi. Khí ni-tơ có nhiều nhất.",example:"🌬️ 🌍"},{title:"Tính chất",text:"Không khí trong suốt, không màu, không mùi, không vị, không có hình dạng nhất định. Không khí có thể bị nén lại hoặc giãn ra.",example:"🎈 💉"}],practice:[{questions:[{id:"kh4-khong-khi-01",type:"tf",q:"Không khí có ở xung quanh mọi vật.",answer:!0,explain:"Không khí có ở khắp nơi quanh ta."},{id:"kh4-khong-khi-02",type:"mc",q:"Trong không khí, khí nào có nhiều nhất?",options:["Khí ô-xi","Khí các-bô-níc","Hơi nước","Khí ni-tơ"],answer:3,explain:"Khí ni-tơ chiếm phần nhiều nhất trong không khí, sau đó là khí ô-xi."},{id:"kh4-khong-khi-03",type:"multi",q:"Không khí có những tính chất nào?",options:["Có màu xanh","Trong suốt","Có mùi thơm","Không có hình dạng nhất định","Không màu"],answers:[1,3,4],explain:"Không khí trong suốt, không màu, không mùi, không có hình dạng nhất định."},{id:"kh4-khong-khi-04",type:"tf",q:"Không khí có hình dạng nhất định giống như cái hộp.",answer:!1,explain:"Không khí không có hình dạng nhất định, nó có hình dạng của vật chứa."},{id:"kh4-khong-khi-05",type:"fill",q:"Hai thành phần chính của không khí là khí ni-tơ và khí … .",answer:["ô-xi","ô xi","ôxi","oxi","oxy"],explain:"Không khí gồm chủ yếu là khí ni-tơ và khí ô-xi."},{id:"kh4-khong-khi-06",type:"mc",q:"Khi ấn bơm xe đạp, không khí trong bơm bị làm sao?",options:["Biến mất","Biến thành nước","Bị nén lại","Đổi màu"],answer:2,explain:"Không khí có thể bị nén lại nên ta bơm được hơi vào lốp xe."},{id:"kh4-khong-khi-07",type:"tf",q:"Trong không khí có hơi nước và bụi.",answer:!0,explain:"Ngoài các chất khí, không khí còn có hơi nước và bụi."},{id:"kh4-khong-khi-08",type:"mc",q:"Vì sao ta không nhìn thấy không khí?",options:["Vì không khí ở rất xa chúng ta","Vì không khí chỉ có vào ban đêm","Vì không khí trong suốt, không màu","Vì không khí luôn có màu đen"],answer:2,explain:"Không khí trong suốt, không màu nên mắt không nhìn thấy."}]},{questions:[{id:"kh4-khong-khi-09",type:"mc",q:"Nhúng miếng bọt biển khô vào nước, thấy bọt khí nổi lên. Điều đó chứng tỏ gì?",options:["Bọt biển tan trong nước","Nước đổi màu","Trong bọt biển có không khí","Bọt biển tự làm ra nước"],answer:2,explain:"Nước tràn vào chỗ rỗng, đẩy không khí trong bọt biển ra ngoài."},{id:"kh4-khong-khi-10",type:"mc",q:"Thổi căng một quả bóng bay. Không khí trong bóng có hình dạng gì?",emoji:"🎈",options:["Hình vuông","Hình dạng của quả bóng","Hình que dài","Hình ngôi sao"],answer:1,explain:"Không khí có hình dạng của vật chứa nó."},{id:"kh4-khong-khi-11",type:"match",q:"Nối hiện tượng với điều nó cho biết về không khí.",pairs:[["Ấn pít-tông bơm tiêm đã bịt kín đầu","Không khí bị nén lại"],["Thả tay, pít-tông bật lên","Không khí giãn ra"],["Thả cục đất khô vào nước thấy bọt khí","Không khí có trong chỗ rỗng của vật"]],explain:"Các thí nghiệm cho thấy tính chất của không khí."},{id:"kh4-khong-khi-12",type:"tf",q:"Trong không khí không có khí các-bô-níc.",answer:!1,explain:"Không khí có một ít khí các-bô-níc."},{id:"kh4-khong-khi-13",type:"multi",q:"Ở đâu có không khí?",options:["Chỗ rỗng trong đất","Lỗ nhỏ trong miếng bọt biển","Bên trong hòn bi sắt đặc","Bên trong chai rỗng"],answers:[0,1,3],explain:"Không khí có trong mọi chỗ rỗng; hòn bi sắt đặc không có chỗ rỗng."},{id:"kh4-khong-khi-14",type:"mc",q:"Úp ngược một cái cốc rỗng rồi ấn thẳng xuống chậu nước, nước không vào đầy cốc. Vì sao?",options:["Vì cốc bị thủng một lỗ","Vì nước không thể chảy","Vì cốc quá nặng","Vì trong cốc có không khí"],answer:3,explain:"Không khí trong cốc chiếm chỗ nên nước không vào đầy cốc."},{id:"kh4-khong-khi-15",type:"tf",q:"Ngửi thấy mùi thơm của hoa là vì bản thân không khí có mùi thơm.",emoji:"🌸",answer:!1,explain:"Không khí không mùi; mùi thơm là do chất từ hoa bay vào không khí."},{id:"kh4-khong-khi-16",type:"mc",q:"Nhờ không khí có thể bị nén lại, người ta làm được việc gì?",options:["Bơm căng lốp xe","Pha nước đường","Đun sôi nước","Phơi khô quần áo"],answer:0,explain:"Không khí bị nén vào trong lốp làm lốp căng."}]},{questions:[{id:"kh4-khong-khi-17",type:"order",q:"Sắp xếp thí nghiệm chứng tỏ trong đất có không khí.",items:["Lấy một cục đất khô","Thả cục đất vào cốc nước","Quan sát thấy bọt khí nổi lên","Kết luận trong đất có không khí"],explain:"Nước tràn vào chỗ rỗng của đất, đẩy không khí ra thành bọt khí."},{id:"kh4-khong-khi-18",type:"mc",q:"Quả bóng đá bị xẹp. Muốn bóng căng tròn lại, em làm gì?",emoji:"⚽",options:["Bơm thêm không khí vào bóng","Cho quả bóng vào tủ lạnh","Đổ thật đầy nước vào bóng","Sơn lại quả bóng"],answer:0,explain:"Bơm không khí vào thì bóng căng lên."},{id:"kh4-khong-khi-19",type:"tf",q:"Trong không khí có thể có vi khuẩn mà mắt thường không nhìn thấy.",answer:!0,explain:"Vi khuẩn rất nhỏ, có thể lơ lửng trong không khí."},{id:"kh4-khong-khi-20",type:"multi",q:"Những đồ vật nào dùng tính chất không khí bị nén lại và giãn ra?",options:["Cái kéo","Phao bơi bơm hơi","Bơm xe đạp","Lốp ô tô","Quyển vở"],answers:[1,2,3],explain:"Bơm, phao bơi, lốp xe đều chứa hoặc nén không khí."},{id:"kh4-khong-khi-21",type:"mc",q:"Nhìn tia nắng chiếu qua khe cửa, em thấy những hạt li ti lơ lửng. Đó là gì?",emoji:"🌤️",options:["Bụi trong không khí","Hơi nước","Khí ô-xi","Khí ni-tơ"],answer:0,explain:"Bụi là thành phần nhìn thấy được khi có tia nắng chiếu qua; các chất khí thì không nhìn thấy."},{id:"kh4-khong-khi-22",type:"mc",q:"Phúc ấn nghiêng một chai rỗng đã mở nắp xuống chậu nước. Em thấy gì?",options:["Chai tan dần trong nước","Bọt khí nổi lên từ miệng chai","Nước trong chậu đổi màu","Không có gì xảy ra cả"],answer:1,explain:"Nước tràn vào chai đẩy không khí ra ngoài thành bọt khí."},{id:"kh4-khong-khi-23",type:"tf",q:"Bịt kín đầu bơm tiêm rồi ấn pít-tông, pít-tông vẫn đi xuống được một đoạn.",answer:!0,explain:"Không khí trong bơm tiêm bị nén lại nên pít-tông đi xuống được."},{id:"kh4-khong-khi-24",type:"fill",q:"Không khí không có hình dạng nhất định mà có hình dạng của vật … nó.",answer:["chứa"],explain:"Không khí có hình dạng của vật chứa nó."}]}],challenge:{questions:[{id:"kh4-khong-khi-25",type:"mc",q:"Cốc nước đá để ngoài, thành cốc có giọt nước đọng. Điều đó chứng tỏ trong không khí có gì?",options:["Khí ni-tơ","Hơi nước","Bụi","Khói"],answer:1,explain:"Hơi nước trong không khí gặp thành cốc lạnh ngưng tụ thành giọt nước."},{id:"kh4-khong-khi-26",type:"multi",q:"Những câu nào đúng về không khí?",options:["Không khí có thể bị nén lại","Không khí có màu trắng","Không khí có trong chỗ rỗng của vật","Không khí chỉ có ở ngoài trời"],answers:[0,2],explain:"Không khí có ở khắp nơi, không màu và có thể bị nén."},{id:"kh4-khong-khi-27",type:"order",q:"Sắp xếp thí nghiệm chứng tỏ không khí bị nén lại và giãn ra.",items:["Kéo pít-tông bơm tiêm lên","Bịt kín đầu bơm tiêm","Ấn pít-tông xuống","Thả tay, pít-tông bật lên"],explain:"Ấn xuống thì không khí bị nén, thả tay thì không khí giãn ra."},{id:"kh4-khong-khi-28",type:"mc",q:"Lốp xe đạp bị thủng thì xe đi rất khó. Vì sao?",options:["Lốp hút thêm không khí","Lốp bị đổi màu","Không khí trong lốp biến thành nước","Không khí trong lốp thoát ra nên lốp xẹp"],answer:3,explain:"Không khí thoát ra qua lỗ thủng nên lốp không còn căng."},{id:"kh4-khong-khi-29",type:"tf",q:"Khí ô-xi chiếm phần nhiều nhất trong không khí.",answer:!1,explain:"Khí ni-tơ chiếm nhiều nhất, sau đó mới đến khí ô-xi."},{id:"kh4-khong-khi-30",type:"match",q:"Nối thí nghiệm với điều nó chứng tỏ.",pairs:[["Thả cục đất khô vào nước thấy bọt khí","Trong đất có không khí"],["Thổi căng quả bóng bay","Không khí có hình dạng của vật chứa"],["Cốc lạnh có giọt nước đọng bên ngoài","Trong không khí có hơi nước"]],explain:"Mỗi thí nghiệm chứng tỏ một điều về không khí."}]},summary:["Không khí có ở khắp nơi, cả trong chỗ rỗng của các vật.","Không khí gồm chủ yếu khí ni-tơ và khí ô-xi, ngoài ra có khí các-bô-níc, hơi nước, bụi.","Không khí trong suốt, không màu, không mùi, không có hình dạng nhất định, có thể bị nén lại và giãn ra."]},{id:"kh4-vai-tro-khong-khi",title:"Bài 7: Vai trò của không khí",weeks:[8,8],learn:[{title:"Không khí và sự cháy",text:"Khí ô-xi trong không khí giúp duy trì sự cháy. Khi hết ô-xi, ngọn lửa sẽ tắt.",example:"🕯️ 🫙"},{title:"Không khí và sự sống",text:"Con người, động vật và thực vật đều cần không khí. Khi thở, cơ thể lấy vào khí ô-xi và thải ra khí các-bô-níc.",example:"🧍 🐶 🌳"},{title:"Vận dụng",text:"Muốn dập lửa nhỏ, ta làm cho lửa không tiếp xúc với không khí. Bể cá cần được sục khí để cá có ô-xi.",example:"🐠 🫧"}],practice:[{questions:[{id:"kh4-vai-tro-khong-khi-01",type:"mc",q:"Khí nào trong không khí giúp duy trì sự cháy?",emoji:"🔥",options:["Khí ni-tơ","Khí các-bô-níc","Khí ô-xi","Hơi nước"],answer:2,explain:"Khí ô-xi cần cho sự cháy."},{id:"kh4-vai-tro-khong-khi-02",type:"tf",q:"Úp kín một cái cốc lên ngọn nến đang cháy, một lúc sau nến tắt.",emoji:"🕯️",answer:!0,explain:"Ô-xi trong cốc hết dần nên nến tắt."},{id:"kh4-vai-tro-khong-khi-03",type:"mc",q:"Khi hít vào, cơ thể ta cần lấy khí gì?",options:["Khí ô-xi","Khí các-bô-níc","Khói","Bụi"],answer:0,explain:"Cơ thể cần khí ô-xi để sống."},{id:"kh4-vai-tro-khong-khi-04",type:"mc",q:"Khi thở ra, cơ thể thải ra khí nào?",options:["Khí ô-xi tinh khiết","Khói bếp","Bụi đất","Khí các-bô-níc"],answer:3,explain:"Cơ thể lấy khí ô-xi và thải ra khí các-bô-níc."},{id:"kh4-vai-tro-khong-khi-05",type:"multi",q:"Những sinh vật nào cần không khí để sống?",options:["Chiếc ghế","Cây lúa","Hòn đá","Con người","Con mèo"],answers:[1,3,4],explain:"Mọi sinh vật đều cần không khí; hòn đá, cái ghế không phải sinh vật."},{id:"kh4-vai-tro-khong-khi-06",type:"tf",q:"Cá sống dưới nước nên không cần ô-xi.",emoji:"🐟",answer:!1,explain:"Cá lấy khí ô-xi hòa tan trong nước để thở."},{id:"kh4-vai-tro-khong-khi-07",type:"fill",q:"Khí … trong không khí cần cho sự thở và sự cháy.",answer:["ô-xi","ô xi","ôxi","oxi","oxy"],explain:"Khí ô-xi cần cho cả sự thở và sự cháy."},{id:"kh4-vai-tro-khong-khi-08",type:"mc",q:"Muốn dập tắt ngọn lửa nhỏ trong chảo dầu, người lớn thường làm gì?",options:["Tắt bếp và đậy kín vung lên chảo","Thổi thật mạnh vào ngọn lửa","Đổ một gáo nước vào chảo dầu","Quạt cho lửa cháy to lên"],answer:0,explain:"Đậy vung làm lửa không có không khí nên tắt; không đổ nước vào dầu đang cháy."}]},{questions:[{id:"kh4-vai-tro-khong-khi-09",type:"mc",q:"Úp một cốc to và một cốc nhỏ lên hai cây nến như nhau đang cháy. Nến nào cháy lâu hơn?",options:["Nến trong cốc to","Nến trong cốc nhỏ","Hai nến tắt cùng lúc","Cả hai nến cháy mãi"],answer:0,explain:"Cốc to chứa nhiều không khí hơn nên có nhiều ô-xi hơn."},{id:"kh4-vai-tro-khong-khi-10",type:"mc",q:"Vì sao nến trong cốc to cháy lâu hơn nến trong cốc nhỏ?",options:["Vì cốc to nặng hơn nên giữ lửa lâu hơn","Vì cốc to có màu đẹp hơn cốc nhỏ","Vì cốc to lạnh hơn nên nến cháy chậm","Vì cốc to có nhiều không khí, nhiều ô-xi hơn"],answer:3,explain:"Càng nhiều ô-xi thì nến càng cháy lâu."},{id:"kh4-vai-tro-khong-khi-11",type:"tf",q:"Muốn lửa trong bếp củi cháy to, cần che kín bếp lại.",answer:!1,explain:"Che kín bếp làm thiếu không khí, lửa sẽ yếu đi; bếp cần thông thoáng."},{id:"kh4-vai-tro-khong-khi-12",type:"mc",q:"Vì sao người ta lắp máy sục khí cho bể cá?",emoji:"🐠",options:["Để nước trong bể có màu xanh","Để cá ăn no hơn mỗi ngày","Để bể cá nặng hơn","Để cung cấp khí ô-xi cho cá"],answer:3,explain:"Máy sục khí đưa không khí vào nước, giúp cá có đủ ô-xi."},{id:"kh4-vai-tro-khong-khi-13",type:"multi",q:"Những cách nào làm lửa tắt vì không còn tiếp xúc với không khí?",options:["Thêm củi khô vào bếp","Phủ chăn ướt lên đám cháy nhỏ","Đậy vung lên chảo đang cháy","Quạt mạnh vào bếp"],answers:[1,2],explain:"Ngăn không khí tới chỗ cháy thì lửa sẽ tắt."},{id:"kh4-vai-tro-khong-khi-14",type:"tf",q:"Khi chạy nhanh, ta thở nhanh hơn vì cơ thể cần nhiều ô-xi hơn.",emoji:"🏃",answer:!0,explain:"Hoạt động mạnh, cơ thể cần nhiều ô-xi nên ta thở gấp."},{id:"kh4-vai-tro-khong-khi-15",type:"match",q:"Nối việc làm với vai trò của không khí.",pairs:[["Thổi bếp cho lửa cháy to","Duy trì sự cháy"],["Hít thở hằng ngày","Duy trì sự sống"],["Sục khí cho bể cá","Cung cấp ô-xi cho cá"]],explain:"Không khí cần cho sự cháy và sự sống."},{id:"kh4-vai-tro-khong-khi-16",type:"mc",q:"Người thợ lặn mang theo bình khí để làm gì?",options:["Để bơi nhanh hơn","Để nhìn rõ hơn","Để giữ ấm","Để thở dưới nước"],answer:3,explain:"Dưới nước không có không khí để thở nên thợ lặn mang bình khí."}]},{questions:[{id:"kh4-vai-tro-khong-khi-17",type:"order",q:"Sắp xếp thí nghiệm chứng tỏ không khí cần cho sự cháy.",items:["Gắn cây nến lên đĩa","Thắp cho nến cháy","Úp kín một cốc thủy tinh lên nến","Quan sát thấy nến tắt dần"],explain:"Úp cốc kín thì ô-xi hết dần và nến tắt."},{id:"kh4-vai-tro-khong-khi-18",type:"mc",q:"Phòng kín có nhiều người, không khí trở nên ngột ngạt. Nên làm gì?",options:["Kéo kín thêm rèm cửa","Đốt thêm than sưởi","Mở cửa cho thoáng khí","Đóng chặt cửa sổ"],answer:2,explain:"Mở cửa để không khí trong lành tràn vào."},{id:"kh4-vai-tro-khong-khi-19",type:"tf",q:"Không nên đốt than sưởi trong phòng ngủ đóng kín cửa.",answer:!0,explain:"Đốt than trong phòng kín làm thiếu ô-xi và sinh ra khí độc, rất nguy hiểm."},{id:"kh4-vai-tro-khong-khi-20",type:"mc",q:"Vì sao cần xới đất cho cây trồng?",options:["Để đất tơi xốp, rễ cây có không khí","Để đất cứng và chặt lại hơn","Để đất có màu đẹp hơn","Để cây không cần tưới nước nữa"],answer:0,explain:"Rễ cây cũng cần không khí; đất tơi xốp có nhiều không khí."},{id:"kh4-vai-tro-khong-khi-21",type:"mc",q:"Khi thấy chảo dầu bốc cháy, việc nào tuyệt đối không được làm?",options:["Đổ nước vào chảo","Tắt bếp","Gọi người lớn giúp","Tránh xa chảo"],answer:0,explain:"Đổ nước vào dầu đang cháy làm dầu bắn ra, lửa bùng to rất nguy hiểm."},{id:"kh4-vai-tro-khong-khi-22",type:"mc",q:"Thảo quạt vào bếp than, lửa cháy to hơn. Vì sao?",options:["Vì quạt làm than bị ướt","Vì quạt làm than lạnh đi","Vì gió quạt mang nước tới","Vì có thêm không khí chứa ô-xi"],answer:3,explain:"Quạt đưa thêm không khí, có thêm ô-xi nên lửa cháy to."},{id:"kh4-vai-tro-khong-khi-23",type:"tf",q:"Thực vật không cần không khí vì cây không có mũi.",emoji:"🌱",answer:!1,explain:"Cây trao đổi khí với không khí qua lá, rễ cây cũng cần không khí."},{id:"kh4-vai-tro-khong-khi-24",type:"number",q:"Giả sử Nam thở 18 lần mỗi phút khi ngồi nghỉ. Trong 3 phút, Nam thở bao nhiêu lần?",answer:54,unit:"lần",explain:"Số lần thở là 18 × 3 = 54 lần."}]}],challenge:{questions:[{id:"kh4-vai-tro-khong-khi-25",type:"mc",q:"Hai cây nến như nhau: nến A úp cốc kín, nến B úp cốc có khe hở sát đáy. Nến nào cháy lâu hơn?",options:["Nến A","Nến B","Hai nến tắt cùng lúc","Cả hai nến đều không cháy"],answer:1,explain:"Khe hở giúp không khí bên ngoài tràn vào, cung cấp thêm ô-xi cho nến B."},{id:"kh4-vai-tro-khong-khi-26",type:"multi",q:"Những điều nào cho thấy cơ thể cần không khí?",options:["Bịt mũi, ngậm miệng một lúc thấy khó chịu","Ăn no thì không cần thở","Khi chạy nhanh ta thở gấp","Khi ngủ ta không cần thở"],answers:[0,2],explain:"Thiếu không khí ta thấy khó chịu; ta luôn thở, kể cả khi ngủ."},{id:"kh4-vai-tro-khong-khi-27",type:"tf",q:"Khí các-bô-níc không duy trì sự cháy nên được dùng trong một số bình chữa cháy.",answer:!0,explain:"Khí các-bô-níc phủ lên đám cháy, ngăn ô-xi nên lửa tắt."},{id:"kh4-vai-tro-khong-khi-28",type:"mc",q:"Bể cá cảnh không có máy sục khí, cá hay ngoi lên mặt nước. Vì sao?",options:["Vì cá muốn phơi nắng","Vì cá muốn ngắm phòng","Vì nước thiếu ô-xi","Vì nước quá trong"],answer:2,explain:"Thiếu ô-xi trong nước, cá phải ngoi lên gần mặt nước để thở."},{id:"kh4-vai-tro-khong-khi-29",type:"match",q:"Nối mỗi khí với vai trò.",pairs:[["Khí ô-xi","Cần cho sự thở và sự cháy"],["Khí các-bô-níc","Cây dùng để chế tạo chất dinh dưỡng"],["Hơi nước","Ngưng tụ tạo thành mây"]],explain:"Mỗi thành phần của không khí có vai trò riêng."},{id:"kh4-vai-tro-khong-khi-30",type:"number",q:"Giả sử nến trong cốc nhỏ cháy được 10 giây. Cốc to chứa không khí gấp 3 lần nên nến cháy lâu gấp 3 lần. Nến trong cốc to cháy được bao nhiêu giây?",answer:30,unit:"giây",explain:"Thời gian nến cháy là 10 × 3 = 30 giây."}]},summary:["Khí ô-xi trong không khí cần cho sự cháy và sự thở.","Con người, động vật, thực vật đều cần không khí để sống.","Ngăn không khí tới chỗ cháy thì lửa sẽ tắt."]},{id:"kh4-gio-bao",title:"Bài 8: Gió, bão và phòng chống bão",weeks:[9,9],learn:[{title:"Không khí chuyển động",text:"Không khí chuyển động tạo thành gió. Không khí nóng bay lên, không khí lạnh hơn tràn vào thế chỗ.",example:"🌬️ 🍃"},{title:"Gió nhẹ, gió mạnh, bão",text:"Gió nhẹ làm lá cây lay động. Gió mạnh làm cành cây nghiêng ngả. Bão là gió rất mạnh, thường kèm mưa to.",example:"🍃 🌳 🌀"},{title:"Phòng chống bão",text:"Theo dõi tin dự báo bão, chằng chống nhà cửa, dự trữ đồ ăn, nước uống, đèn pin và ở trong nhà an toàn.",example:"📻 🏠 🔦"}],practice:[{questions:[{id:"kh4-gio-bao-01",type:"mc",q:"Gió là gì?",emoji:"🌬️",options:["Nước đang bay hơi","Ánh nắng chiếu xuống","Không khí chuyển động","Mây trôi trên trời"],answer:2,explain:"Không khí chuyển động tạo thành gió."},{id:"kh4-gio-bao-02",type:"tf",q:"Bão là gió rất mạnh, thường kèm theo mưa to.",emoji:"🌀",answer:!0,explain:"Bão có gió rất mạnh và thường có mưa lớn."},{id:"kh4-gio-bao-03",type:"mc",q:"Dấu hiệu nào cho biết đang có gió?",emoji:"🍃",options:["Mặt Trời mọc","Hòn đá nằm yên","Nước trong cốc đứng yên","Lá cây lay động"],answer:3,explain:"Gió làm lá cây lay động."},{id:"kh4-gio-bao-04",type:"multi",q:"Bão có thể gây ra tác hại nào?",options:["Ngập lụt","Làm hoa nở đẹp hơn","Đổ cây, tốc mái nhà"],answers:[0,2],explain:"Bão gió mạnh làm đổ cây, tốc mái, mưa to gây ngập lụt."},{id:"kh4-gio-bao-05",type:"tf",q:"Không khí nóng nặng hơn nên chìm xuống thấp.",answer:!1,explain:"Không khí nóng nhẹ hơn nên bay lên cao."},{id:"kh4-gio-bao-06",type:"mc",q:"Khi có bão, em nên ở đâu?",options:["Ra bờ sông xem nước","Ở trong nhà chắc chắn","Trèo lên cây cao","Đi chơi ngoài đồng"],answer:1,explain:"Ở trong nhà chắc chắn là an toàn nhất khi có bão."},{id:"kh4-gio-bao-07",type:"fill",q:"Không khí chuyển động tạo thành … .",answer:["gió"],explain:"Gió là không khí chuyển động."},{id:"kh4-gio-bao-08",type:"mc",q:"Đồ chơi nào quay được nhờ sức gió?",options:["Chong chóng","Quyển sách","Cái bát","Hòn sỏi"],answer:0,explain:"Gió thổi làm cánh chong chóng quay."}]},{questions:[{id:"kh4-gio-bao-09",type:"match",q:"Nối dấu hiệu với mức độ gió.",pairs:[["Lá cây khẽ lay động","Gió nhẹ"],["Cành cây to nghiêng ngả","Gió mạnh"],["Cây đổ, tốc mái nhà","Bão"]],explain:"Gió càng mạnh thì cây cối, nhà cửa càng bị ảnh hưởng nhiều."},{id:"kh4-gio-bao-10",type:"mc",q:"Vì sao có gió?",options:["Vì cây cối vẫy lá liên tục nên tạo ra gió","Vì những đám mây đẩy không khí đi khắp nơi","Vì không khí ở các nơi nóng, lạnh khác nhau nên chuyển động","Vì Mặt Trăng thổi không khí về phía Trái Đất"],answer:2,explain:"Chênh lệch nóng lạnh làm không khí chuyển động tạo thành gió."},{id:"kh4-gio-bao-11",type:"tf",q:"Ở nơi bị nắng chiếu, không khí nóng lên và bay lên cao, không khí lạnh hơn tràn đến tạo thành gió.",answer:!0,explain:"Đó là cách gió hình thành."},{id:"kh4-gio-bao-12",type:"multi",q:"Những việc nào cần làm khi nghe tin bão sắp đến?",options:["Theo dõi tin dự báo bão","Dự trữ nước uống và thức ăn","Ra biển đánh cá","Chằng chống nhà cửa"],answers:[0,1,3],explain:"Chuẩn bị trước giúp giảm thiệt hại; không ra biển khi có bão."},{id:"kh4-gio-bao-13",type:"mc",q:"Vì sao khi có bão, không nên đứng gần cột điện và cây to?",options:["Vì cây to làm cho gió thổi mạnh hơn","Vì cột điện hút hết nước mưa về phía mình","Vì đứng ở đó sẽ bị lạnh hơn","Vì cột điện, cây to có thể đổ gây nguy hiểm"],answer:3,explain:"Gió bão có thể quật đổ cây và cột điện."},{id:"kh4-gio-bao-14",type:"tf",q:"Thuyền buồm chỉ chạy được khi trời lặng gió.",emoji:"⛵",answer:!1,explain:"Thuyền buồm cần gió đẩy cánh buồm mới chạy được."},{id:"kh4-gio-bao-15",type:"mc",q:"Gió có ích gì cho con người?",options:["Làm đổ nhà cửa, cây cối","Gây ngập lụt nhà cửa","Làm gãy cành cây to","Làm quay tua-bin để phát điện"],answer:3,explain:"Gió làm quay tua-bin gió để phát điện."},{id:"kh4-gio-bao-16",type:"mc",q:"Trời có gió thì quần áo phơi nhanh khô hơn. Vì sao?",options:["Vì trong gió có rất nhiều nước","Vì gió giúp nước bay hơi nhanh hơn","Vì gió làm vải dày lên hơn","Vì gió nén quần áo lại"],answer:1,explain:"Gió mang hơi nước đi nên nước bay hơi nhanh hơn."}]},{questions:[{id:"kh4-gio-bao-17",type:"order",q:"Sắp xếp các việc gia đình làm khi có tin bão.",items:["Nghe tin dự báo bão","Chằng chống nhà cửa, dự trữ đồ cần thiết","Ở trong nhà khi bão đến","Kiểm tra nhà cửa sau khi bão tan"],explain:"Chuẩn bị trước, an toàn trong bão, khắc phục sau bão."},{id:"kh4-gio-bao-18",type:"mc",q:"Đặt nến đang cháy dưới một ống của hộp có hai ống. Đưa nén hương đang bốc khói tới miệng ống kia thì khói bị kéo vào ống đó. Vì sao?",options:["Không khí nóng bay lên ở ống có nến, không khí lạnh tràn vào ống kia","Khói hương thích bay tới gần ngọn nến","Chiếc hộp tự hút khói hương vào bên trong","Khói hương nặng như đá nên rơi vào ống"],answer:0,explain:"Thí nghiệm cho thấy không khí chuyển động từ chỗ lạnh tới chỗ nóng."},{id:"kh4-gio-bao-19",type:"mc",q:"Lớp học nóng bức, mở cả cửa sổ và cửa ra vào thì phòng mát hơn. Vì sao?",options:["Cửa mở làm không khí biến mất","Cửa mở làm Mặt Trời tắt","Cửa mở làm tường lạnh","Không khí lưu thông, tạo thành gió"],answer:3,explain:"Mở cửa giúp không khí chuyển động qua phòng."},{id:"kh4-gio-bao-20",type:"tf",q:"Khi có bão, nên mở toang cửa sổ để gió lùa vào nhà.",answer:!1,explain:"Khi có bão cần đóng chặt cửa để gió mạnh không làm hỏng nhà."},{id:"kh4-gio-bao-21",type:"multi",q:"Khi bão đang diễn ra, những việc làm nào an toàn?",options:["Tránh xa cửa kính","Ra sân nhặt quả rụng","Ở yên trong nhà","Đi tắm sông"],answers:[0,2],explain:"Ở trong nhà, tránh cửa kính để không bị thương."},{id:"kh4-gio-bao-22",type:"tf",q:"Sau khi bão tan, cần tránh xa dây điện bị đứt.",answer:!0,explain:"Dây điện đứt có thể gây điện giật."},{id:"kh4-gio-bao-23",type:"match",q:"Nối vật với cách dùng sức gió.",pairs:[["Thuyền buồm","Di chuyển trên mặt nước"],["Tua-bin gió","Phát điện"],["Cánh diều","Bay lên cao"]],explain:"Con người dùng sức gió vào nhiều việc."},{id:"kh4-gio-bao-24",type:"mc",q:"Minh mang diều ra cánh đồng nhưng diều không bay lên được. Vì sao có thể như vậy?",emoji:"🪁",options:["Trời quá nắng","Trời lặng gió","Dây diều quá dài","Diều có màu đỏ"],answer:1,explain:"Diều cần có gió mới bay lên được."}]}],challenge:{questions:[{id:"kh4-gio-bao-25",type:"mc",q:"Vì sao ban ngày ở vùng biển, gió thường thổi từ biển vào đất liền?",options:["Vì cá dưới biển tạo ra gió","Vì biển nóng hơn đất liền","Vì đất liền có nhiều nhà cửa","Đất liền nóng nhanh hơn, không khí trên đất liền bay lên, không khí mát từ biển tràn vào"],answer:3,explain:"Ban ngày đất nóng lên nhanh hơn nước nên không khí từ biển tràn vào."},{id:"kh4-gio-bao-26",type:"order",q:"Sắp xếp những gì xảy ra trong thí nghiệm hộp hai ống có nến.",items:["Nến làm không khí ở ống thứ nhất nóng lên","Không khí nóng bay lên qua ống thứ nhất","Không khí lạnh bên ngoài tràn vào ống thứ hai","Khói hương bị kéo vào ống thứ hai"],explain:"Không khí nóng bay lên, không khí lạnh tràn vào thế chỗ."},{id:"kh4-gio-bao-27",type:"multi",q:"Những câu nào đúng về bão?",options:["Bão chỉ có gió, không bao giờ có mưa","Bão giúp nhà cửa vững hơn","Cần theo dõi tin dự báo để phòng chống bão","Bão có gió rất mạnh"],answers:[2,3],explain:"Bão có gió rất mạnh, thường kèm mưa to, cần phòng chống."},{id:"kh4-gio-bao-28",type:"tf",q:"Gió vừa có lợi vừa có thể gây hại cho con người.",answer:!0,explain:"Gió giúp phát điện, phơi khô; gió bão gây đổ cây, tốc mái."},{id:"kh4-gio-bao-29",type:"mc",q:"Vì sao trước khi bão đến cần dự trữ nước uống và đèn pin?",options:["Vì bão có thể làm mất điện, mất nước","Vì bão làm nước uống ngọt hơn","Vì đèn pin làm cơn bão yếu đi","Vì bão chỉ đến vào ban đêm"],answer:0,explain:"Bão có thể làm hỏng đường điện, đường nước."},{id:"kh4-gio-bao-30",type:"mc",q:"Ngọn lửa cây nến đặt gần cửa sổ đang mở bị nghiêng về một phía. Điều đó cho biết gì?",options:["Nến sắp cháy hết","Nến bị ướt nước","Trời sắp tối","Có gió thổi qua"],answer:3,explain:"Gió làm ngọn lửa nghiêng theo hướng gió thổi."}]},summary:["Không khí chuyển động tạo thành gió.","Bão là gió rất mạnh, có thể gây nhiều thiệt hại.","Cần theo dõi tin bão, chằng chống nhà cửa và ở nơi an toàn."]},{id:"kh4-bao-ve-khong-khi",title:"Bài 9: Ô nhiễm không khí và bảo vệ bầu không khí",weeks:[10,10],learn:[{title:"Không khí sạch và không khí ô nhiễm",text:"Không khí sạch trong suốt, không có mùi lạ. Không khí ô nhiễm có nhiều khói, bụi, khí độc, mùi hôi.",example:"🌳 😊 · 🏭 😷"},{title:"Nguyên nhân",text:"Khói xe cộ, khói nhà máy, đốt rác, đốt rơm rạ, cháy rừng, bụi từ công trường làm không khí bị ô nhiễm.",example:"🚗 🏭 🔥"},{title:"Tác hại và bảo vệ",text:"Không khí ô nhiễm gây bệnh về hô hấp, mắt. Em trồng cây xanh, không đốt rác, đeo khẩu trang khi ra đường nhiều bụi.",example:"🌱 😷"}],practice:[{questions:[{id:"kh4-bao-ve-khong-khi-01",type:"multi",q:"Nguyên nhân nào làm không khí bị ô nhiễm?",options:["Khói xe máy, ô tô","Trồng cây xanh","Khói nhà máy","Đốt rác"],answers:[0,2,3],explain:"Khói xe, khói nhà máy, đốt rác làm không khí ô nhiễm."},{id:"kh4-bao-ve-khong-khi-02",type:"tf",q:"Trồng nhiều cây xanh giúp không khí trong lành hơn.",emoji:"🌳",answer:!0,explain:"Cây xanh giữ bụi và cho khí ô-xi."},{id:"kh4-bao-ve-khong-khi-03",type:"mc",q:"Hít thở không khí ô nhiễm lâu ngày dễ mắc bệnh gì?",options:["Bệnh về đường hô hấp","Bệnh sâu răng","Bệnh gãy xương","Bệnh nấm móng"],answer:0,explain:"Khói bụi đi vào mũi, họng, phổi gây bệnh hô hấp."},{id:"kh4-bao-ve-khong-khi-04",type:"mc",q:"Khi ra đường nhiều khói bụi, em nên làm gì?",emoji:"😷",options:["Hít thở thật sâu","Tháo khẩu trang ra","Đứng gần ống xả xe","Đeo khẩu trang"],answer:3,explain:"Khẩu trang giúp cản bớt khói bụi."},{id:"kh4-bao-ve-khong-khi-05",type:"tf",q:"Đốt rác ngay trong khu dân cư là việc làm tốt cho không khí.",answer:!1,explain:"Đốt rác tạo khói độc làm ô nhiễm không khí."},{id:"kh4-bao-ve-khong-khi-06",type:"fill",q:"Để bảo vệ không khí, chúng ta nên trồng nhiều cây … .",answer:["xanh"],explain:"Cây xanh giúp không khí trong lành."},{id:"kh4-bao-ve-khong-khi-07",type:"mc",q:"Không khí sạch có đặc điểm nào?",options:["Có nhiều khói đen","Trong suốt, không có mùi lạ","Có mùi hôi khó chịu","Có rất nhiều bụi"],answer:1,explain:"Không khí sạch trong suốt, không có mùi lạ."},{id:"kh4-bao-ve-khong-khi-08",type:"tf",q:"Cháy rừng làm không khí bị ô nhiễm.",answer:!0,explain:"Cháy rừng tạo ra rất nhiều khói bụi."}]},{questions:[{id:"kh4-bao-ve-khong-khi-09",type:"match",q:"Nối nơi gây ô nhiễm với chất gây ô nhiễm.",pairs:[["Ống xả xe cộ","Khói xe"],["Công trường xây dựng","Bụi đất cát"],["Bãi rác","Mùi hôi thối"]],explain:"Mỗi nơi thải ra một loại chất làm bẩn không khí."},{id:"kh4-bao-ve-khong-khi-10",type:"mc",q:"Vì sao không khí ở nơi đông xe cộ thường bị ô nhiễm hơn?",options:["Vì có nhiều cây xanh","Vì có nhiều khói xe","Vì có nhiều ao hồ","Vì trời luôn mưa"],answer:1,explain:"Xe cộ thải ra nhiều khói làm ô nhiễm không khí."},{id:"kh4-bao-ve-khong-khi-11",type:"multi",q:"Việc làm nào góp phần bảo vệ không khí?",options:["Đi bộ, đi xe đạp khi đi gần","Đốt rơm rạ ngoài đồng","Thu gom rác đúng nơi quy định","Để xe nổ máy khi đứng chờ lâu"],answers:[0,2],explain:"Bớt khói xe và không để rác bốc mùi giúp không khí sạch hơn."},{id:"kh4-bao-ve-khong-khi-12",type:"tf",q:"Cây xanh làm cho không khí có nhiều bụi hơn.",answer:!1,explain:"Lá cây giữ lại bớt bụi, giúp không khí sạch hơn."},{id:"kh4-bao-ve-khong-khi-13",type:"mc",q:"Công trường xây dựng cần làm gì để giảm bụi?",options:["Để đất cát bay tự do","Che chắn và tưới nước","Đốt bỏ vật liệu thừa","Chở đất không che phủ"],answer:1,explain:"Che chắn và tưới nước giúp bụi không bay lên."},{id:"kh4-bao-ve-khong-khi-14",type:"tf",q:"Không khí ô nhiễm chỉ có hại cho con người, không hại cho cây cối và động vật.",answer:!1,explain:"Không khí ô nhiễm có hại cho cả con người, động vật và thực vật."},{id:"kh4-bao-ve-khong-khi-15",type:"mc",q:"Vì sao không nên đốt rơm rạ sau khi gặt lúa?",options:["Vì rơm rạ không cháy được","Vì khói làm ô nhiễm không khí","Vì đốt rơm làm trời mưa","Vì rơm cháy ra nước"],answer:1,explain:"Khói đốt rơm rạ làm ô nhiễm không khí, ảnh hưởng sức khỏe."},{id:"kh4-bao-ve-khong-khi-16",type:"multi",q:"Dấu hiệu nào cho thấy không khí bị ô nhiễm?",options:["Không khí mát, không mùi lạ","Có mùi khét, mùi hôi","Trời trong xanh","Bầu trời mờ đục vì khói bụi"],answers:[1,3],explain:"Khói bụi làm trời mờ đục và có mùi lạ."}]},{questions:[{id:"kh4-bao-ve-khong-khi-17",type:"mc",q:"Gần nhà An có người hay đốt rác. An nên làm gì?",options:["Đốt thêm rác","Nhờ bố mẹ góp ý với người đó","Mặc kệ","Mở toang cửa cho khói vào"],answer:1,explain:"Nhờ người lớn góp ý nhẹ nhàng để cùng bảo vệ không khí."},{id:"kh4-bao-ve-khong-khi-18",type:"multi",q:"Lớp em muốn giữ không khí quanh trường trong lành. Nên làm những việc nào?",options:["Xả rác ra cổng trường","Đốt lá khô trong sân trường","Trồng và chăm sóc cây xanh","Quét dọn, bỏ rác đúng chỗ"],answers:[2,3],explain:"Trồng cây và giữ vệ sinh giúp không khí trong lành."},{id:"kh4-bao-ve-khong-khi-19",type:"tf",q:"Ngày không khí ô nhiễm nặng, nên đeo khẩu trang và hạn chế ra ngoài.",answer:!0,explain:"Như vậy giúp ta hít ít khói bụi hơn."},{id:"kh4-bao-ve-khong-khi-20",type:"mc",q:"Vì sao nên tắt máy xe khi phải dừng chờ lâu?",options:["Để chiếc xe trông đẹp hơn","Để con đường rộng ra hơn","Để giảm khói thải và tiết kiệm xăng","Để trời mát mẻ hơn"],answer:2,explain:"Tắt máy thì xe không thải khói và không tốn xăng."},{id:"kh4-bao-ve-khong-khi-21",type:"order",q:"Sắp xếp từ việc gây ô nhiễm đến tác hại.",items:["Nhiều người đốt rác","Khói bụi bay vào không khí","Không khí bị ô nhiễm","Người hít phải dễ bị ho, khó thở"],explain:"Đốt rác sinh khói bụi, làm ô nhiễm không khí, gây hại sức khỏe."},{id:"kh4-bao-ve-khong-khi-22",type:"mc",q:"Có hai con đường: một đường có hàng cây xanh, một đường không có cây. Đường nào thường ít bụi hơn?",options:["Đường có hàng cây xanh","Đường không có cây","Hai đường bụi như nhau","Không đường nào có bụi"],answer:0,explain:"Cây xanh giữ lại bớt bụi nên đường có cây ít bụi hơn."},{id:"kh4-bao-ve-khong-khi-23",type:"match",q:"Nối việc làm với tác dụng.",pairs:[["Trồng cây xanh","Giữ lại bụi, làm không khí trong lành"],["Đeo khẩu trang","Hạn chế hít phải bụi"],["Không đốt rác","Giảm khói độc"]],explain:"Mỗi việc làm đều góp phần bảo vệ không khí và sức khỏe."},{id:"kh4-bao-ve-khong-khi-24",type:"tf",q:"Đun bếp than trong nhà đóng kín cửa không ảnh hưởng tới không khí trong nhà.",answer:!1,explain:"Bếp than sinh khói và khí độc, làm không khí trong nhà ô nhiễm."}]}],challenge:{questions:[{id:"kh4-bao-ve-khong-khi-25",type:"multi",q:"Những việc nào vừa bảo vệ không khí vừa tiết kiệm?",options:["Để xe nổ máy cả buổi","Tắt máy xe khi chờ lâu","Đi xe đạp tới trường gần nhà","Đốt rác thay vì phân loại"],answers:[1,2],explain:"Tắt máy xe, đi xe đạp vừa giảm khói vừa tiết kiệm xăng."},{id:"kh4-bao-ve-khong-khi-26",type:"mc",q:"Khu phố có nhà máy thải khói đen. Giải pháp nào hiệu quả và lâu dài nhất?",options:["Người dân không bao giờ ra khỏi nhà","Nhà máy xử lí khói thải trước khi thải ra","Mở cửa cho khói bay vào nhà","Đốt thêm rác để khói bay đi"],answer:1,explain:"Xử lí khói thải tại nhà máy giải quyết từ nguyên nhân."},{id:"kh4-bao-ve-khong-khi-27",type:"tf",q:"Khói bụi ở nơi này có thể bị gió đưa sang nơi khác.",answer:!0,explain:"Gió mang khói bụi đi xa nên ô nhiễm có thể lan rộng."},{id:"kh4-bao-ve-khong-khi-28",type:"order",q:"Sắp xếp các việc trồng một cây xanh ở sân trường.",items:["Chọn chỗ đất trống có nắng","Đào hố và bón lót phân","Đặt cây con vào hố và lấp đất","Tưới nước và chăm sóc hằng ngày"],explain:"Chuẩn bị chỗ trồng, trồng cây rồi chăm sóc."},{id:"kh4-bao-ve-khong-khi-29",type:"mc",q:"Vì sao ngày không khí ô nhiễm nặng, người già và trẻ nhỏ nên hạn chế ra ngoài?",options:["Vì họ chạy chậm hơn","Vì họ không thích gió","Vì họ dễ mắc bệnh hô hấp hơn","Vì họ không có khẩu trang"],answer:2,explain:"Người già và trẻ nhỏ sức đề kháng yếu hơn nên dễ bị bệnh."},{id:"kh4-bao-ve-khong-khi-30",type:"match",q:"Nối hành động với kết quả.",pairs:[["Đốt rơm rạ","Khói bụi tăng"],["Trồng rừng","Không khí trong lành hơn"],["Che chắn xe chở đất","Ít bụi trên đường"]],explain:"Việc làm của con người ảnh hưởng trực tiếp tới không khí."}]},summary:["Không khí bị ô nhiễm do khói xe, khói nhà máy, đốt rác, bụi.","Không khí ô nhiễm gây bệnh hô hấp và hại sinh vật.","Em trồng cây, không đốt rác, đeo khẩu trang để bảo vệ không khí và sức khỏe."]}]},{id:"nang-luong",title:"Năng lượng",lessons:[{id:"kh4-anh-sang",title:"Bài 10: Ánh sáng và bóng tối",weeks:[11,11],learn:[{title:"Nguồn sáng",text:"Vật tự phát ra ánh sáng gọi là nguồn sáng, như Mặt Trời, ngọn nến đang cháy, bóng đèn đang sáng.",example:"☀️ 🕯️ 💡"},{title:"Ánh sáng truyền qua vật",text:"Kính trong cho ánh sáng truyền qua. Kính mờ, giấy bóng mờ cho ánh sáng truyền qua một phần. Gỗ, sắt, bìa cứng cản ánh sáng.",example:"🪟 🧱"},{title:"Bóng tối",text:"Ánh sáng truyền theo đường thẳng. Phía sau vật cản sáng có bóng tối. Bóng thay đổi khi vị trí nguồn sáng thay đổi.",example:"🔦 ➡️ 🧍 ➡️ 🌑"},{title:"Nhìn thấy vật",text:"Ta nhìn thấy vật khi có ánh sáng từ vật truyền tới mắt.",example:"💡 ➡️ 🍎 ➡️ 👁️"}],practice:[{questions:[{id:"kh4-anh-sang-01",type:"multi",q:"Những vật nào là nguồn sáng?",options:["Quyển sách","Mặt Trời","Bóng đèn đang sáng","Cái gương","Ngọn nến đang cháy"],answers:[1,2,4],explain:"Nguồn sáng tự phát ra ánh sáng; gương và sách không tự phát sáng."},{id:"kh4-anh-sang-02",type:"mc",q:"Vật nào cho ánh sáng truyền qua gần như hoàn toàn?",options:["Tấm gỗ","Tấm kính trong","Tấm bìa cứng","Viên gạch"],answer:1,explain:"Kính trong cho ánh sáng truyền qua nên ta nhìn rõ phía sau."},{id:"kh4-anh-sang-03",type:"mc",q:"Vật nào cản ánh sáng?",options:["Tấm gỗ","Tấm kính trong","Cốc nước trong","Túi ni lông trong"],answer:0,explain:"Gỗ không cho ánh sáng truyền qua."},{id:"kh4-anh-sang-04",type:"tf",q:"Ánh sáng truyền theo đường thẳng.",answer:!0,explain:"Ánh sáng đi theo đường thẳng, không tự đi vòng."},{id:"kh4-anh-sang-05",type:"fill",q:"Phía sau vật cản sáng có … tối.",answer:["bóng"],explain:"Vật cản ánh sáng tạo ra bóng tối phía sau."},{id:"kh4-anh-sang-06",type:"tf",q:"Bóng đèn đã tắt vẫn là nguồn sáng.",answer:!1,explain:"Bóng đèn tắt không phát ra ánh sáng nên lúc đó không phải nguồn sáng."},{id:"kh4-anh-sang-07",type:"mc",q:"Ta nhìn thấy quyển sách khi nào?",options:["Khi có ánh sáng từ quyển sách truyền tới mắt","Khi phòng tối hoàn toàn, không có đèn","Khi ta nhắm chặt hai mắt lại","Khi quyển sách ở sau một bức tường"],answer:0,explain:"Mắt nhìn thấy vật khi ánh sáng từ vật truyền tới mắt."},{id:"kh4-anh-sang-08",type:"mc",q:"Vật nào cho ánh sáng truyền qua một phần?",options:["Tấm kính trong","Tấm sắt","Bức tường","Tấm kính mờ"],answer:3,explain:"Kính mờ cho một phần ánh sáng đi qua nên nhìn qua thấy mờ mờ."}]},{questions:[{id:"kh4-anh-sang-09",type:"match",q:"Nối vật với cách ánh sáng truyền qua.",pairs:[["Kính trong","Cho ánh sáng truyền qua"],["Giấy bóng mờ","Cho ánh sáng truyền qua một phần"],["Tấm bìa cứng","Cản ánh sáng"]],explain:"Mỗi vật cho ánh sáng truyền qua nhiều, ít hoặc cản ánh sáng."},{id:"kh4-anh-sang-10",type:"mc",q:"Vì sao Mặt Trăng không phải là nguồn sáng?",emoji:"🌕",options:["Vì Mặt Trăng quá nhỏ","Vì Mặt Trăng chỉ có ban ngày","Vì Mặt Trăng không tự phát sáng, chỉ hắt lại ánh sáng Mặt Trời","Vì Mặt Trăng ở quá gần"],answer:2,explain:"Mặt Trăng sáng nhờ hắt lại ánh sáng từ Mặt Trời."},{id:"kh4-anh-sang-11",type:"tf",q:"Trong phòng tối hoàn toàn, ta vẫn nhìn rõ đồ vật.",answer:!1,explain:"Không có ánh sáng truyền tới mắt thì ta không nhìn thấy vật."},{id:"kh4-anh-sang-12",type:"mc",q:"Chiếu đèn pin vào quả bóng, bóng tối của quả bóng nằm ở đâu?",options:["Ở cùng phía với chiếc đèn pin","Phía sau quả bóng, ngược phía với đèn","Ở ngay phía trên chiếc đèn pin","Không có bóng tối ở chỗ nào"],answer:1,explain:"Bóng tối nằm phía sau vật cản sáng, ngược phía nguồn sáng."},{id:"kh4-anh-sang-13",type:"mc",q:"Đưa đèn pin lại gần vật, bóng của vật trên tường thay đổi thế nào?",options:["Nhỏ đi","Biến mất","To ra","Đổi màu"],answer:2,explain:"Nguồn sáng càng gần vật thì bóng của vật càng to."},{id:"kh4-anh-sang-14",type:"multi",q:"Những vật nào cản ánh sáng?",options:["Bàn tay","Cái thước gỗ","Quyển vở","Tấm kính trong"],answers:[0,1,2],explain:"Vở, thước gỗ, bàn tay cản ánh sáng; kính trong cho ánh sáng đi qua."},{id:"kh4-anh-sang-15",type:"tf",q:"Bóng của một cái cây vào buổi sáng và buổi chiều nằm ở hai phía khác nhau.",answer:!0,explain:"Mặt Trời buổi sáng ở phía đông, buổi chiều ở phía tây nên bóng cây đổi phía."},{id:"kh4-anh-sang-16",type:"mc",q:"Vì sao ta nhìn ra ngoài được qua cửa kính trong?",options:["Vì kính trong là một nguồn sáng","Vì kính trong cho ánh sáng truyền qua","Vì kính trong cản hết ánh sáng","Vì kính trong luôn có màu đen"],answer:1,explain:"Ánh sáng từ cảnh vật bên ngoài truyền qua kính tới mắt ta."}]},{questions:[{id:"kh4-anh-sang-17",type:"order",q:"Sắp xếp thí nghiệm tìm vật cho ánh sáng truyền qua.",items:["Đặt đèn pin trước một tấm vật liệu","Bật đèn pin chiếu vào tấm vật liệu","Quan sát phía sau tấm vật liệu","Ghi lại vật liệu đó có cho ánh sáng truyền qua không"],explain:"Chiếu sáng, quan sát phía sau rồi ghi kết quả."},{id:"kh4-anh-sang-18",type:"mc",q:"Muốn ánh sáng vào phòng nhưng người bên ngoài không nhìn rõ bên trong, nên lắp cửa bằng gì?",options:["Kính trong","Kính mờ","Gỗ dày","Tôn"],answer:1,explain:"Kính mờ cho ánh sáng qua một phần nên không nhìn rõ được bên trong."},{id:"kh4-anh-sang-19",type:"mc",q:"Buổi trưa, Mặt Trời ở gần đỉnh đầu. Bóng của em lúc đó thế nào?",options:["Dài nhất trong ngày","Dài như lúc sáng sớm","Ngắn nhất trong ngày","Dài như lúc chiều tối"],answer:2,explain:"Mặt Trời càng cao thì bóng càng ngắn."},{id:"kh4-anh-sang-20",type:"tf",q:"Đứng ngoài trời nắng, bóng của em nằm ngược phía với Mặt Trời.",answer:!0,explain:"Bóng tối luôn ở phía sau vật, ngược phía nguồn sáng."},{id:"kh4-anh-sang-21",type:"mc",q:"Chi đặt bàn tay giữa đèn và bức tường để làm bóng con thỏ. Muốn bóng to hơn, Chi làm gì?",emoji:"🐰",options:["Đưa tay lại gần tường hơn","Tắt đèn","Mặc áo màu khác","Đưa tay lại gần đèn hơn"],answer:3,explain:"Vật càng gần nguồn sáng thì bóng càng to."},{id:"kh4-anh-sang-22",type:"multi",q:"Những vật nào nên làm bằng vật liệu cho ánh sáng truyền qua?",options:["Cửa sổ","Mái che nắng","Rèm chắn nắng","Mắt kính đeo"],answers:[0,3],explain:"Cửa sổ, mắt kính cần cho ánh sáng qua; rèm, mái che cần cản ánh sáng."},{id:"kh4-anh-sang-23",type:"mc",q:"Vì sao rèm cửa dày giúp ngủ ngon hơn vào buổi sáng?",options:["Vì rèm dày cản ánh sáng","Vì rèm dày phát ra ánh sáng","Vì rèm dày cho ánh sáng đi qua","Vì rèm dày làm Mặt Trời tắt"],answer:0,explain:"Rèm dày cản ánh sáng nên trong phòng tối hơn."},{id:"kh4-anh-sang-24",type:"tf",q:"Ánh sáng có thể tự đi vòng qua bức tường để chiếu sáng phía sau.",answer:!1,explain:"Ánh sáng truyền theo đường thẳng nên phía sau bức tường có bóng tối."}]}],challenge:{questions:[{id:"kh4-anh-sang-25",type:"mc",q:"Một cái cọc cắm thẳng đứng giữa sân. Buổi sáng bóng cọc ở phía tây. Buổi chiều bóng cọc ở phía nào?",options:["Phía tây","Phía nam","Không có bóng","Phía đông"],answer:3,explain:"Buổi chiều Mặt Trời ở phía tây nên bóng cọc ở phía đông."},{id:"kh4-anh-sang-26",type:"order",q:"Sắp xếp đường đi của ánh sáng giúp ta nhìn thấy quả táo.",items:["Bóng đèn phát ra ánh sáng","Ánh sáng chiếu tới quả táo","Ánh sáng từ quả táo truyền tới mắt","Mắt nhìn thấy quả táo"],explain:"Ánh sáng chiếu tới vật rồi từ vật truyền tới mắt."},{id:"kh4-anh-sang-27",type:"multi",q:"Những câu nào đúng?",options:["Kính trong cản ánh sáng","Ánh sáng truyền theo đường thẳng","Mặt Trăng tự phát ra ánh sáng","Bóng tối xuất hiện phía sau vật cản sáng"],answers:[1,3],explain:"Mặt Trăng chỉ hắt lại ánh sáng; kính trong cho ánh sáng truyền qua."},{id:"kh4-anh-sang-28",type:"mc",q:"Nhìn qua một ống hút thẳng thấy ngọn nến, uốn cong ống thì không thấy nữa. Điều này chứng tỏ gì?",options:["Ánh sáng đi vòng được","Ống hút là nguồn sáng","Ánh sáng truyền theo đường thẳng","Ngọn nến đã bị tắt"],answer:2,explain:"Ánh sáng không đi theo ống cong được vì nó truyền theo đường thẳng."},{id:"kh4-anh-sang-29",type:"tf",q:"Vật đứng yên, khi nguồn sáng di chuyển thì bóng của vật cũng thay đổi.",answer:!0,explain:"Vị trí nguồn sáng thay đổi làm bóng đổi hướng và đổi độ dài."},{id:"kh4-anh-sang-30",type:"match",q:"Nối hiện tượng với lí do.",pairs:[["Phía sau bức tường râm mát","Tường cản ánh sáng"],["Nhìn rõ cá trong bể kính","Kính trong cho ánh sáng truyền qua"],["Nhìn thấy Mặt Trăng ban đêm","Mặt Trăng hắt lại ánh sáng Mặt Trời"]],explain:"Mỗi hiện tượng được giải thích bằng cách ánh sáng truyền đi."}]},summary:["Nguồn sáng là vật tự phát ra ánh sáng.","Có vật cho ánh sáng truyền qua, truyền qua một phần, hoặc cản ánh sáng.","Ánh sáng truyền theo đường thẳng; phía sau vật cản sáng có bóng tối."]},{id:"kh4-vai-tro-anh-sang",title:"Bài 11: Vai trò của ánh sáng và bảo vệ mắt",weeks:[12,12],learn:[{title:"Ánh sáng với sự sống",text:"Thực vật cần ánh sáng để sống và lớn lên. Con người và động vật cần ánh sáng để nhìn, tìm thức ăn, giữ sức khỏe.",example:"🌱 ☀️"},{title:"Ánh sáng trong đời sống",text:"Ánh sáng giúp ta học tập, làm việc. Ánh sáng Mặt Trời còn dùng để phơi khô, sưởi ấm và làm ra điện.",example:"📖 💡 🔋"},{title:"Bảo vệ mắt",text:"Không nhìn thẳng vào Mặt Trời hay đèn quá sáng. Đọc, viết nơi đủ sáng, ngồi đúng tư thế, không dùng điện thoại, máy tính quá lâu.",example:"👀 😎"}],practice:[{questions:[{id:"kh4-vai-tro-anh-sang-01",type:"tf",q:"Cây xanh cần ánh sáng để sống và phát triển.",emoji:"🌱",answer:!0,explain:"Thiếu ánh sáng, cây yếu ớt, lá vàng úa."},{id:"kh4-vai-tro-anh-sang-02",type:"mc",q:"Việc làm nào có hại cho mắt?",options:["Nhìn thẳng vào Mặt Trời","Đọc sách nơi đủ sáng","Đội mũ khi trời nắng gắt","Nghỉ mắt sau khi học lâu"],answer:0,explain:"Ánh sáng Mặt Trời rất mạnh, nhìn thẳng vào có thể làm hỏng mắt."},{id:"kh4-vai-tro-anh-sang-03",type:"mc",q:"Khi đọc sách, em nên ngồi ở đâu?",options:["Nơi đủ ánh sáng","Nơi tối","Ngoài nắng gắt","Dưới gầm bàn"],answer:0,explain:"Đọc nơi đủ sáng giúp mắt không phải cố gắng nhiều."},{id:"kh4-vai-tro-anh-sang-04",type:"multi",q:"Ánh sáng Mặt Trời giúp con người làm gì?",options:["Phơi khô quần áo","Làm ra điện bằng pin mặt trời","Làm nước biển ngọt","Sưởi ấm"],answers:[0,1,3],explain:"Ánh sáng Mặt Trời dùng để phơi khô, sưởi ấm, làm ra điện."},{id:"kh4-vai-tro-anh-sang-05",type:"tf",q:"Đọc sách dưới ánh sáng quá yếu có hại cho mắt.",answer:!0,explain:"Ánh sáng yếu làm mắt phải cố gắng nhiều nên dễ mỏi."},{id:"kh4-vai-tro-anh-sang-06",type:"fill",q:"Không nên nhìn thẳng vào Mặt … vì có hại cho mắt.",answer:["Trời"],explain:"Không nhìn thẳng vào Mặt Trời để bảo vệ mắt."},{id:"kh4-vai-tro-anh-sang-07",type:"mc",q:"Với người viết tay phải, đèn bàn nên đặt ở phía nào?",options:["Phía sau lưng","Phía trước bên trái","Phía bên phải","Chiếu thẳng vào mắt"],answer:1,explain:"Đặt đèn phía trước bên trái thì bóng tay phải không che chỗ viết."},{id:"kh4-vai-tro-anh-sang-08",type:"mc",q:"Nhờ có ánh sáng, động vật làm được gì?",options:["Không cần ăn uống gì nữa","Không cần thở không khí nữa","Nhìn thấy để tìm thức ăn, tránh kẻ thù","Không cần uống nước nữa"],answer:2,explain:"Ánh sáng giúp động vật nhìn thấy để kiếm ăn và tránh nguy hiểm."}]},{questions:[{id:"kh4-vai-tro-anh-sang-09",type:"mc",q:"Vì sao cây để trong bóng tối lâu ngày thường yếu, lá vàng úa?",options:["Vì thừa ánh sáng","Vì chậu cây có màu tối","Vì cây quá to","Vì thiếu ánh sáng"],answer:3,explain:"Cây cần ánh sáng; thiếu ánh sáng cây yếu dần."},{id:"kh4-vai-tro-anh-sang-10",type:"match",q:"Nối tình huống với cách bảo vệ mắt.",pairs:[["Trời nắng gắt","Đội mũ rộng vành, đeo kính râm"],["Học bài buổi tối","Bật đèn đủ sáng"],["Dùng máy tính lâu","Nghỉ mắt, nhìn ra xa"]],explain:"Mỗi tình huống có cách bảo vệ mắt phù hợp."},{id:"kh4-vai-tro-anh-sang-11",type:"tf",q:"Ngồi sát màn hình ti vi là tốt cho mắt.",answer:!1,explain:"Ngồi quá gần màn hình làm mắt nhanh mỏi."},{id:"kh4-vai-tro-anh-sang-12",type:"multi",q:"Ánh sáng có vai trò gì với con người?",options:["Giúp nhìn thấy mọi vật","Giúp học tập, làm việc","Giúp cơ thể khỏe mạnh","Giúp ta không cần ăn"],answers:[0,1,2],explain:"Ánh sáng giúp ta nhìn, học tập, làm việc và khỏe mạnh."},{id:"kh4-vai-tro-anh-sang-13",type:"mc",q:"Vì sao không được chiếu đèn pin vào mắt bạn?",options:["Vì ánh sáng mạnh có thể làm hại mắt","Vì đèn pin sẽ bị hỏng ngay","Vì mắt bạn sẽ đổi màu mãi","Vì bạn sẽ ngủ quên mất"],answer:0,explain:"Ánh sáng mạnh chiếu thẳng vào mắt gây chói và có thể làm hại mắt."},{id:"kh4-vai-tro-anh-sang-14",type:"mc",q:"Chậu cây đặt cạnh cửa sổ thường mọc nghiêng về phía nào?",emoji:"🪴",options:["Phía tường tối","Phía có ánh sáng","Cắm xuống đất","Không nghiêng phía nào"],answer:1,explain:"Cây hướng về phía có ánh sáng."},{id:"kh4-vai-tro-anh-sang-15",type:"tf",q:"Ánh sáng quá mạnh hoặc quá yếu đều có hại cho mắt.",answer:!0,explain:"Cần ánh sáng vừa đủ để mắt không bị chói hoặc mỏi."},{id:"kh4-vai-tro-anh-sang-16",type:"mc",q:"Tư thế nào đúng khi đọc sách?",options:["Nằm sấp trên giường đọc sách","Cúi thật sát mặt vào trang sách","Ngồi thẳng lưng, mắt cách sách vừa phải","Vừa đi lại vừa đọc sách"],answer:2,explain:"Ngồi đúng tư thế giúp mắt và lưng không mỏi."}]},{questions:[{id:"kh4-vai-tro-anh-sang-17",type:"mc",q:"Lan học bài, đèn bàn chiếu thẳng vào mắt làm chói. Lan nên làm gì?",options:["Chỉnh đèn chiếu xuống mặt bàn","Tắt hết đèn trong phòng","Nhắm bớt một mắt lại","Đeo kính râm để học"],answer:0,explain:"Đèn cần chiếu vào chỗ đọc viết, không chiếu vào mắt."},{id:"kh4-vai-tro-anh-sang-18",type:"multi",q:"Những thói quen nào giúp bảo vệ mắt?",options:["Nằm đọc sách trong bóng tối","Đọc sách nơi đủ sáng","Không xem điện thoại quá lâu","Đọc sách trên xe đang rung lắc"],answers:[1,2],explain:"Đủ sáng và cho mắt nghỉ giúp mắt khỏe."},{id:"kh4-vai-tro-anh-sang-19",type:"order",q:"Sắp xếp thí nghiệm tìm hiểu cây có cần ánh sáng không.",items:["Chọn hai chậu cây giống nhau","Đặt một chậu nơi có ánh sáng, một chậu trong hộp tối","Tưới nước như nhau cho hai chậu","Sau nhiều ngày, so sánh hai chậu cây"],explain:"Chỉ khác nhau ở ánh sáng thì mới biết ánh sáng ảnh hưởng thế nào."},{id:"kh4-vai-tro-anh-sang-20",type:"mc",q:"Trong thí nghiệm trên, chậu cây trong hộp tối sau nhiều ngày sẽ thế nào?",options:["Xanh tốt hơn chậu kia","Yếu dần, lá vàng úa","Ra hoa nhiều hơn","Không thay đổi gì"],answer:1,explain:"Thiếu ánh sáng, cây không phát triển bình thường."},{id:"kh4-vai-tro-anh-sang-21",type:"tf",q:"Có thể nhìn thẳng vào Mặt Trời bằng mắt thường nếu chỉ nhìn một lúc.",answer:!1,explain:"Dù chỉ một lúc, ánh sáng Mặt Trời vẫn có thể làm hại mắt."},{id:"kh4-vai-tro-anh-sang-22",type:"mc",q:"Vì sao nhà kính trồng rau thường có mái trong suốt?",options:["Để cản bớt ánh sáng","Để nước mưa rơi vào","Để ánh sáng chiếu vào cho cây","Để chim bay vào"],answer:2,explain:"Mái trong suốt cho ánh sáng truyền qua tới cây."},{id:"kh4-vai-tro-anh-sang-23",type:"tf",q:"Phơi chăn màn dưới nắng giúp chăn khô và diệt bớt vi khuẩn.",answer:!0,explain:"Ánh nắng làm khô và diệt bớt một số vi khuẩn."},{id:"kh4-vai-tro-anh-sang-24",type:"match",q:"Nối vật với lợi ích của ánh sáng Mặt Trời.",pairs:[["Tấm pin mặt trời","Làm ra điện"],["Sân phơi thóc","Làm khô hạt"],["Ruộng lúa","Giúp cây lớn lên"]],explain:"Ánh sáng Mặt Trời có nhiều lợi ích."}]}],challenge:{questions:[{id:"kh4-vai-tro-anh-sang-25",type:"mc",q:"Bình xem điện thoại nhiều giờ liền, mắt mỏi và nhức. Lời khuyên nào đúng nhất?",options:["Tăng độ sáng màn hình lên thật cao","Xem trong phòng tối cho rõ","Giảm thời gian dùng, thỉnh thoảng nghỉ mắt","Dụi mắt thật mạnh"],answer:2,explain:"Cho mắt nghỉ và giảm thời gian nhìn màn hình giúp mắt đỡ mỏi."},{id:"kh4-vai-tro-anh-sang-26",type:"multi",q:"Những việc nào nguy hiểm cho mắt?",options:["Nhìn thẳng vào tia lửa hàn","Đeo kính bảo hộ khi làm việc có tia lửa","Chiếu đèn la-de vào mắt người khác","Học nơi đủ ánh sáng"],answers:[0,2],explain:"Ánh sáng quá mạnh như tia la-de, tia lửa hàn làm hại mắt."},{id:"kh4-vai-tro-anh-sang-27",type:"tf",q:"Cây trồng trong nhà nên thỉnh thoảng được đưa ra chỗ có ánh sáng.",answer:!0,explain:"Cây cần ánh sáng để sống khỏe."},{id:"kh4-vai-tro-anh-sang-28",type:"mc",q:"Hai cây đậu giống nhau: cây A để ở bậu cửa sổ, cây B để trong tủ kín. Sau một tuần, điều gì có thể xảy ra?",options:["Cây A xanh tốt hơn cây B","Cây B xanh tốt hơn cây A","Hai cây như nhau","Cả hai cây đều ra quả"],answer:0,explain:"Cây A có ánh sáng nên phát triển tốt hơn."},{id:"kh4-vai-tro-anh-sang-29",type:"match",q:"Nối việc làm với lí do.",pairs:[["Đội mũ khi đi nắng","Tránh nắng chói vào mắt"],["Bật đèn khi trời tối","Có đủ ánh sáng để nhìn rõ"],["Nghỉ mắt sau khi học lâu","Giúp mắt đỡ mỏi"]],explain:"Bảo vệ mắt bằng những việc làm đơn giản hằng ngày."},{id:"kh4-vai-tro-anh-sang-30",type:"mc",q:"Vì sao không nên đọc sách khi ngồi trên xe đang chạy?",options:["Vì trên xe không có ánh sáng","Vì sách sẽ bị rách","Vì xe sẽ chạy chậm lại","Vì chữ rung lắc làm mắt phải điều tiết nhiều, dễ mỏi"],answer:3,explain:"Chữ rung lắc liên tục làm mắt mỏi nhanh."}]},summary:["Ánh sáng cần cho sự sống của thực vật, động vật và con người.","Ánh sáng giúp ta học tập, làm việc; ánh sáng Mặt Trời còn dùng để phơi khô, làm ra điện.","Bảo vệ mắt: không nhìn thẳng vào nguồn sáng mạnh, học nơi đủ sáng, cho mắt nghỉ."]},{id:"kh4-am-thanh",title:"Bài 12: Âm thanh và sự lan truyền âm thanh",weeks:[13,13],learn:[{title:"Nguồn âm",text:"Âm thanh do các vật rung động phát ra. Vật phát ra âm thanh gọi là nguồn âm.",example:"🥁 🔔 🎸"},{title:"Âm thanh lan truyền",text:"Âm thanh lan truyền qua không khí, qua chất lỏng như nước và qua chất rắn như gỗ, sắt.",example:"🌬️ 💧 🪵"},{title:"Gần và xa",text:"Càng ra xa nguồn âm, âm thanh nghe càng nhỏ. Vật rung động mạnh thì phát ra âm thanh to hơn.",example:"🔊 ➡️ 🔉 ➡️ 🔈"}],practice:[{questions:[{id:"kh4-am-thanh-01",type:"mc",q:"Âm thanh do đâu mà có?",options:["Do ánh sáng chiếu vào vật","Do vật đứng yên","Do không khí đổi màu","Do các vật rung động phát ra"],answer:3,explain:"Vật rung động thì phát ra âm thanh."},{id:"kh4-am-thanh-02",type:"tf",q:"Khi gõ trống, mặt trống rung động và phát ra âm thanh.",emoji:"🥁",answer:!0,explain:"Mặt trống rung động tạo ra tiếng trống."},{id:"kh4-am-thanh-03",type:"tf",q:"Âm thanh không thể truyền qua nước.",answer:!1,explain:"Âm thanh truyền được qua chất lỏng như nước."},{id:"kh4-am-thanh-04",type:"mc",q:"Càng đi ra xa nguồn âm, em nghe âm thanh thế nào?",options:["Nhỏ dần","To dần","Không đổi","Biến thành ánh sáng"],answer:0,explain:"Âm thanh yếu dần khi truyền đi xa."},{id:"kh4-am-thanh-05",type:"fill",q:"Vật phát ra âm thanh gọi là nguồn … .",answer:["âm"],explain:"Vật phát ra âm thanh là nguồn âm."},{id:"kh4-am-thanh-06",type:"multi",q:"Những vật nào đang là nguồn âm?",options:["Quyển sách nằm yên trên bàn","Cái loa đang phát nhạc","Chiếc chuông đang reo","Cái trống đang được gõ"],answers:[1,2,3],explain:"Vật đang phát ra âm thanh là nguồn âm; sách nằm yên không phát ra âm thanh."},{id:"kh4-am-thanh-07",type:"mc",q:"Đặt tay lên cổ khi nói, em cảm thấy gì?",options:["Cổ nóng ran","Cổ lạnh đi","Cổ rung nhẹ","Không có gì"],answer:2,explain:"Khi nói, dây thanh trong cổ rung động."},{id:"kh4-am-thanh-08",type:"tf",q:"Gõ trống càng mạnh thì tiếng trống càng nhỏ.",answer:!1,explain:"Gõ mạnh thì mặt trống rung mạnh, tiếng trống to hơn."}]},{questions:[{id:"kh4-am-thanh-09",type:"mc",q:"Áp tai xuống mặt bàn, bạn gõ nhẹ ở đầu bàn bên kia, em vẫn nghe thấy. Điều đó chứng tỏ gì?",options:["Âm thanh truyền qua chất rắn","Âm thanh chỉ truyền qua không khí","Mặt bàn là nguồn sáng","Tai tự phát ra âm thanh"],answer:0,explain:"Âm thanh truyền qua mặt gỗ tới tai em."},{id:"kh4-am-thanh-10",type:"mc",q:"Rắc vài hạt gạo lên mặt trống rồi gõ, hạt gạo nảy lên. Vì sao?",options:["Vì gạo tự nhảy","Vì gió thổi","Vì mặt trống nóng lên","Vì mặt trống rung động"],answer:3,explain:"Mặt trống rung động làm hạt gạo nảy lên."},{id:"kh4-am-thanh-11",type:"match",q:"Nối nguồn âm với bộ phận rung động.",pairs:[["Cái trống","Mặt trống"],["Đàn ghi-ta","Dây đàn"],["Người đang nói","Dây thanh trong cổ"]],explain:"Bộ phận rung động là nơi phát ra âm thanh."},{id:"kh4-am-thanh-12",type:"tf",q:"Lấy tay giữ chặt mặt trống đang kêu thì tiếng trống tắt dần.",answer:!0,explain:"Giữ chặt làm mặt trống ngừng rung nên hết tiếng."},{id:"kh4-am-thanh-13",type:"mc",q:"Khi lặn dưới nước, ta vẫn nghe tiếng động. Điều đó cho thấy gì?",options:["Âm thanh không truyền qua nước","Nước là nguồn sáng","Tai không cần âm thanh","Âm thanh truyền được qua nước"],answer:3,explain:"Âm thanh truyền được qua chất lỏng."},{id:"kh4-am-thanh-14",type:"mc",q:"Vì sao tiếng còi xe ở xa nghe nhỏ hơn ở gần?",options:["Vì xe ở xa kêu khác hẳn xe ở gần","Vì tai chỉ nghe được tiếng ở gần","Vì không khí ở xa có màu khác","Vì âm thanh yếu dần khi truyền đi xa"],answer:3,explain:"Âm thanh càng truyền xa càng yếu."},{id:"kh4-am-thanh-15",type:"tf",q:"Âm thanh chỉ truyền được qua không khí.",answer:!1,explain:"Âm thanh truyền qua chất khí, chất lỏng và chất rắn."},{id:"kh4-am-thanh-16",type:"mc",q:"Gảy một dây đàn rồi chạm nhẹ tay vào dây, em thấy gì?",emoji:"🎸",options:["Dây đàn đang rung","Dây đàn nóng lên","Dây đàn đứng yên","Dây đàn phát sáng"],answer:0,explain:"Dây đàn rung động khi phát ra âm thanh."}]},{questions:[{id:"kh4-am-thanh-17",type:"order",q:"Sắp xếp thí nghiệm chứng tỏ âm thanh do vật rung động phát ra.",items:["Rắc vài hạt gạo lên mặt trống","Gõ nhẹ vào mặt trống","Quan sát thấy hạt gạo nảy lên","Kết luận mặt trống rung khi phát ra âm thanh"],explain:"Hạt gạo nảy lên cho thấy mặt trống rung động."},{id:"kh4-am-thanh-18",type:"mc",q:"Hai bạn làm “điện thoại” bằng hai cốc giấy nối với nhau bằng một sợi dây căng. Âm thanh truyền từ cốc này sang cốc kia chủ yếu qua đâu?",options:["Ánh sáng","Nước","Không qua đâu cả","Sợi dây căng"],answer:3,explain:"Âm thanh làm sợi dây rung và truyền sang cốc bên kia."},{id:"kh4-am-thanh-19",type:"mc",q:"Muốn nghe rõ tiếng chuông ở xa, em làm gì?",options:["Đi lại gần chuông hơn","Đi ra xa chuông hơn","Lấy tay bịt tai lại","Quay lưng chạy đi"],answer:0,explain:"Càng gần nguồn âm, âm thanh nghe càng to và rõ."},{id:"kh4-am-thanh-20",type:"tf",q:"Cá dưới ao có thể nghe thấy tiếng động trên bờ.",emoji:"🐟",answer:!0,explain:"Âm thanh truyền qua không khí rồi qua nước tới cá."},{id:"kh4-am-thanh-21",type:"multi",q:"Những cách nào làm âm thanh nghe to hơn?",options:["Lấy tay giữ chặt mặt trống","Gõ mạnh hơn vào trống","Đi ra xa nguồn âm","Đi lại gần nguồn âm"],answers:[1,3],explain:"Gần nguồn âm hoặc làm vật rung mạnh hơn thì nghe to hơn."},{id:"kh4-am-thanh-22",type:"mc",q:"Vì sao khi đóng kín cửa kính, tiếng ồn ngoài đường nhỏ đi?",options:["Vì cửa kính tự phát ra âm thanh","Vì xe cộ ngoài đường dừng lại hết","Vì cửa kính làm tai em to hơn","Vì cửa kính cản bớt âm thanh truyền vào"],answer:3,explain:"Cửa đóng kín cản bớt âm thanh từ ngoài vào."},{id:"kh4-am-thanh-23",type:"match",q:"Nối hiện tượng với môi trường truyền âm.",pairs:[["Nghe tiếng chim hót ngoài vườn","Không khí"],["Nghe tiếng gõ khi áp tai vào bàn","Chất rắn"],["Người lặn nghe tiếng động dưới nước","Nước"]],explain:"Âm thanh truyền qua chất khí, chất rắn và chất lỏng."},{id:"kh4-am-thanh-24",type:"tf",q:"Đứng càng gần loa thì nghe tiếng nhạc càng nhỏ.",answer:!1,explain:"Càng gần nguồn âm thì âm thanh càng to."}]}],challenge:{questions:[{id:"kh4-am-thanh-25",type:"mc",q:"Vì sao lấy hai tay bịt tai thì nghe tiếng nói nhỏ đi?",options:["Bàn tay phát ra âm thanh khác","Người kia ngừng nói chuyện","Bàn tay cản bớt âm thanh truyền tới tai","Tai không còn hoạt động nữa"],answer:2,explain:"Vật chắn giữa nguồn âm và tai làm âm thanh nhỏ đi."},{id:"kh4-am-thanh-26",type:"order",q:"Sắp xếp đường đi của tiếng trống tới tai em.",items:["Gõ vào mặt trống","Mặt trống rung động","Không khí xung quanh rung theo","Âm thanh truyền tới tai em"],explain:"Vật rung động làm không khí rung theo và truyền âm tới tai."},{id:"kh4-am-thanh-27",type:"multi",q:"Những câu nào đúng về âm thanh?",options:["Âm thanh do vật rung động phát ra","Âm thanh truyền qua chất rắn, chất lỏng, chất khí","Âm thanh truyền đi xa vẫn to như cũ","Vật không rung động cũng phát ra âm thanh"],answers:[0,1],explain:"Âm thanh do vật rung động phát ra và yếu dần khi truyền xa."},{id:"kh4-am-thanh-28",type:"mc",q:"Đặt đồng hồ báo thức đang reo vào hộp rồi phủ dần nhiều lớp vải dày. Tiếng chuông nghe thế nào?",emoji:"⏰",options:["Nhỏ dần","To dần","Không đổi","Biến thành ánh sáng"],answer:0,explain:"Các lớp vải dày cản bớt âm thanh."},{id:"kh4-am-thanh-29",type:"tf",q:"Dây đàn ngừng rung thì không còn phát ra âm thanh.",answer:!0,explain:"Hết rung động thì không còn âm thanh."},{id:"kh4-am-thanh-30",type:"mc",q:"Phúc nói nhỏ vào một đầu ống nhựa dài, Vy áp tai ở đầu kia vẫn nghe rõ. Vì sao?",options:["Ống nhựa tự phát ra tiếng nói giống hệt Phúc","Ánh sáng trong ống mang tiếng nói của Phúc đi","Vy nhìn miệng Phúc nên đoán ra được lời nói","Âm thanh truyền theo không khí trong ống, ít bị tỏa ra xung quanh"],answer:3,explain:"Ống giữ cho âm thanh không tỏa ra nhiều nên vẫn nghe rõ."}]},summary:["Âm thanh do vật rung động phát ra.","Âm thanh truyền qua chất khí, chất lỏng và chất rắn.","Càng xa nguồn âm, âm thanh nghe càng nhỏ."]},{id:"kh4-am-thanh-doi-song",title:"Bài 13: Âm thanh trong đời sống và chống tiếng ồn",weeks:[14,14],learn:[{title:"Âm thanh có ích",text:"Âm thanh giúp ta trò chuyện, học tập, nghe nhạc, nghe tiếng còi, tiếng chuông báo hiệu.",example:"🗣️ 🎵 🔔"},{title:"Tiếng ồn",text:"Tiếng ồn quá to, kéo dài có thể làm hại tai, gây mệt mỏi, mất ngủ, khó tập trung.",example:"🔊 😣"},{title:"Chống tiếng ồn",text:"Trồng cây xanh, đóng cửa, dùng vật liệu cách âm, nói nhỏ nơi công cộng, không bật loa quá to.",example:"🌳 🚪 🤫"}],practice:[{questions:[{id:"kh4-am-thanh-doi-song-01",type:"multi",q:"Âm thanh giúp con người làm gì?",options:["Nhìn thấy trong bóng tối","Nghe nhạc","Nghe chuông báo cháy","Trò chuyện với nhau"],answers:[1,2,3],explain:"Âm thanh giúp ta giao tiếp, giải trí và nhận biết báo hiệu."},{id:"kh4-am-thanh-doi-song-02",type:"tf",q:"Tiếng ồn quá to có thể làm hại tai.",answer:!0,explain:"Âm thanh quá to, kéo dài làm hại tai."},{id:"kh4-am-thanh-doi-song-03",type:"mc",q:"Việc nào gây tiếng ồn làm phiền hàng xóm?",options:["Nói chuyện nhỏ nhẹ","Ngồi đọc sách","Tưới cây ngoài sân","Bật loa thật to lúc nửa đêm"],answer:3,explain:"Bật loa to lúc nửa đêm làm mọi người mất ngủ."},{id:"kh4-am-thanh-doi-song-04",type:"mc",q:"Ở thư viện, em cần làm gì?",emoji:"📚",options:["Nói to, cười đùa","Gõ bàn liên tục","Giữ trật tự, nói nhỏ","Mở nhạc thật to"],answer:2,explain:"Thư viện cần yên tĩnh để mọi người đọc sách."},{id:"kh4-am-thanh-doi-song-05",type:"fill",q:"Trồng nhiều cây … giúp giảm tiếng ồn từ đường phố.",answer:["xanh"],explain:"Hàng cây xanh giúp cản bớt tiếng ồn."},{id:"kh4-am-thanh-doi-song-06",type:"tf",q:"Tiếng còi xe cứu thương giúp mọi người biết để nhường đường.",emoji:"🚑",answer:!0,explain:"Âm thanh báo hiệu giúp mọi người kịp nhường đường."},{id:"kh4-am-thanh-doi-song-07",type:"mc",q:"Âm thanh nào báo hiệu nguy hiểm?",options:["Tiếng hát ru","Tiếng lá rơi","Tiếng nhạc du dương","Chuông báo cháy"],answer:3,explain:"Chuông báo cháy báo cho mọi người biết có cháy."},{id:"kh4-am-thanh-doi-song-08",type:"tf",q:"Đeo tai nghe vặn âm lượng thật to suốt nhiều giờ là tốt cho tai.",answer:!1,explain:"Nghe to và lâu có hại cho tai."}]},{questions:[{id:"kh4-am-thanh-doi-song-09",type:"match",q:"Nối nguồn tiếng ồn với cách giảm.",pairs:[["Tiếng xe cộ ngoài đường","Đóng cửa, trồng cây xanh"],["Tiếng máy khoan ở công trường","Thợ đeo nút bịt tai"],["Tiếng ti vi quá to","Vặn nhỏ âm lượng"]],explain:"Mỗi nguồn ồn có cách giảm phù hợp."},{id:"kh4-am-thanh-doi-song-10",type:"multi",q:"Tiếng ồn có thể gây hại gì?",options:["Gây mất ngủ","Làm khó tập trung học","Gây mệt mỏi, đau đầu","Giúp ngủ ngon hơn"],answers:[0,1,2],explain:"Tiếng ồn gây mệt mỏi, mất ngủ, khó tập trung."},{id:"kh4-am-thanh-doi-song-11",type:"mc",q:"Vì sao bệnh viện, trường học cần yên tĩnh?",options:["Để bác sĩ và thầy cô phải nói to hơn","Để học sinh được ngủ trong giờ học","Để người bệnh nghỉ ngơi và học sinh tập trung học","Để tiết kiệm điện cho bệnh viện, trường học"],answer:2,explain:"Yên tĩnh giúp nghỉ ngơi và học tập tốt."},{id:"kh4-am-thanh-doi-song-12",type:"tf",q:"Âm thanh chỉ có hại, không có ích gì.",answer:!1,explain:"Âm thanh có nhiều lợi ích như giao tiếp, học tập, báo hiệu."},{id:"kh4-am-thanh-doi-song-13",type:"mc",q:"Phòng thu âm thường phủ tường bằng vật liệu nào để cách âm?",options:["Kính mỏng","Tôn mỏng","Xốp, bông, đệm dày","Giấy bóng"],answer:2,explain:"Vật liệu mềm, xốp hút bớt âm thanh."},{id:"kh4-am-thanh-doi-song-14",type:"mc",q:"Tiếng trống trường giúp học sinh biết điều gì?",emoji:"🥁",options:["Trời sắp có mưa","Có khách đến nhà","Giờ vào lớp, giờ ra chơi","Đã đến giờ đi ngủ"],answer:2,explain:"Tiếng trống trường báo hiệu giờ học, giờ chơi."},{id:"kh4-am-thanh-doi-song-15",type:"tf",q:"Nói chuyện nhỏ nhẹ nơi công cộng là cách giảm tiếng ồn.",answer:!0,explain:"Nói nhỏ nhẹ giúp nơi công cộng yên tĩnh hơn."},{id:"kh4-am-thanh-doi-song-16",type:"mc",q:"Vì sao người thợ làm việc cạnh máy móc ồn cần đeo nút bịt tai?",options:["Để nghe rõ tiếng máy hơn","Để giữ ấm tai","Để trông đẹp hơn","Để bảo vệ tai"],answer:3,explain:"Nút bịt tai giảm tiếng ồn đi vào tai."}]},{questions:[{id:"kh4-am-thanh-doi-song-17",type:"mc",q:"Nhà Hà gần đường lớn rất ồn. Cách nào giúp giảm tiếng ồn vào nhà?",options:["Mở toang hết các cửa cho thoáng","Bật loa thật to cho át tiếng xe","Chặt hết cây xanh ở trước nhà","Trồng cây xanh trước nhà và đóng kín cửa khi cần"],answer:3,explain:"Cây xanh và cửa đóng kín cản bớt tiếng ồn."},{id:"kh4-am-thanh-doi-song-18",type:"multi",q:"Những việc nào thể hiện ý thức giữ yên tĩnh?",options:["Không bấm còi xe khi không cần","Hát thật to lúc nửa đêm","Vặn nhỏ ti vi buổi tối","La hét trong lớp học"],answers:[0,2],explain:"Giữ yên tĩnh là tôn trọng người xung quanh."},{id:"kh4-am-thanh-doi-song-19",type:"tf",q:"Ở nơi rất ồn như khi xem bắn pháo hoa gần, có thể bịt tai để bảo vệ tai.",answer:!0,explain:"Bịt tai giúp giảm âm thanh quá to vào tai."},{id:"kh4-am-thanh-doi-song-20",type:"order",q:"Sắp xếp các âm thanh từ nhỏ đến to.",items:["Tiếng lá rơi","Tiếng nói chuyện bình thường","Tiếng còi ô tô ở gần","Tiếng máy khoan bê tông ngay bên cạnh"],explain:"Tiếng lá rơi rất nhỏ, tiếng máy khoan sát bên rất to."},{id:"kh4-am-thanh-doi-song-21",type:"mc",q:"Thầy tổng phụ trách dùng loa khi nói với cả trường ở sân. Vì sao?",options:["Để âm thanh nhỏ đi","Để thầy đỡ mệt hơn","Để sân trường mát hơn","Để âm thanh to hơn, mọi người nghe rõ"],answer:3,explain:"Loa làm âm thanh to hơn, nghe được ở xa."},{id:"kh4-am-thanh-doi-song-22",type:"mc",q:"Bình muốn nghe nhạc bằng tai nghe. Cách nào an toàn cho tai?",emoji:"🎧",options:["Vặn âm lượng to nhất có thể","Đeo tai nghe khi ngủ suốt cả đêm","Nghe liên tục từ sáng tới tối","Vặn âm lượng vừa phải, nghe trong thời gian ngắn"],answer:3,explain:"Âm lượng vừa phải và thời gian ngắn giúp bảo vệ tai."},{id:"kh4-am-thanh-doi-song-23",type:"match",q:"Nối âm thanh với tác dụng.",pairs:[["Tiếng chuông báo thức","Đánh thức ta dậy"],["Tiếng còi tàu","Báo hiệu tàu sắp đến"],["Tiếng nhạc nhẹ","Giúp ta thư giãn"]],explain:"Mỗi âm thanh có tác dụng riêng."},{id:"kh4-am-thanh-doi-song-24",type:"tf",q:"Trong giờ ngủ trưa ở trường, nói chuyện to không ảnh hưởng tới người khác.",answer:!1,explain:"Nói to làm các bạn khác mất ngủ."}]}],challenge:{questions:[{id:"kh4-am-thanh-doi-song-25",type:"multi",q:"Cách nào vừa giảm tiếng ồn vừa làm môi trường xanh hơn?",options:["Chặt cây bên đường","Đốt lá khô ven đường","Trồng hàng cây xanh ven đường"],answers:[2],explain:"Hàng cây xanh cản tiếng ồn và làm không khí trong lành."},{id:"kh4-am-thanh-doi-song-26",type:"mc",q:"Khu nhà ở gần sân bay rất ồn. Giải pháp nào phù hợp cho các ngôi nhà?",emoji:"✈️",options:["Dùng cửa và tường cách âm","Mở hết cửa","Bật nhạc to để át tiếng máy bay","Ngồi ngoài sân cả ngày"],answer:0,explain:"Vật liệu cách âm cản bớt tiếng ồn vào nhà."},{id:"kh4-am-thanh-doi-song-27",type:"tf",q:"Tiếng ồn chỉ ảnh hưởng tới con người, không ảnh hưởng tới động vật.",answer:!1,explain:"Tiếng ồn lớn làm nhiều con vật sợ hãi, bỏ chỗ ở."},{id:"kh4-am-thanh-doi-song-28",type:"mc",q:"Vì sao tường trong rạp hát thường được phủ vật liệu mềm, xốp?",options:["Để rạp hát sáng sủa hơn","Để hút bớt âm thanh, tránh tiếng vang","Để bức tường nặng hơn","Để âm thanh to mãi không tắt"],answer:1,explain:"Vật liệu mềm, xốp hút bớt âm thanh dội lại."},{id:"kh4-am-thanh-doi-song-29",type:"order",q:"Sắp xếp việc làm khi nghe chuông báo cháy ở trường.",items:["Dừng việc đang làm và giữ bình tĩnh","Nghe hướng dẫn của thầy cô","Xếp hàng đi theo lối thoát hiểm","Tập trung ở nơi an toàn"],explain:"Bình tĩnh, nghe hướng dẫn, thoát ra theo lối thoát hiểm."},{id:"kh4-am-thanh-doi-song-30",type:"match",q:"Nối nơi chốn với cách cư xử phù hợp.",pairs:[["Trong bệnh viện","Đi nhẹ, nói khẽ"],["Trong lớp giờ kiểm tra","Giữ im lặng"],["Buổi tối ở khu nhà đông người","Vặn nhỏ loa, ti vi"]],explain:"Giữ yên tĩnh đúng lúc, đúng chỗ là tôn trọng mọi người."}]},summary:["Âm thanh giúp ta giao tiếp, học tập, giải trí và nhận biết báo hiệu.","Tiếng ồn quá to, kéo dài có hại cho sức khỏe.","Giảm tiếng ồn bằng cây xanh, cửa kín, vật liệu cách âm và cư xử lịch sự."]},{id:"kh4-nhiet-do",title:"Bài 14: Nhiệt độ và sự truyền nhiệt",weeks:[15,16],learn:[{title:"Nóng và lạnh",text:"Vật nóng có nhiệt độ cao, vật lạnh có nhiệt độ thấp. Để đo nhiệt độ, ta dùng nhiệt kế.",example:"🌡️"},{title:"Một số nhiệt độ",text:"Nhiệt độ cơ thể người khỏe mạnh khoảng 37 độ C. Nước đá đang tan khoảng 0 độ C. Nước đang sôi khoảng 100 độ C.",example:"🧊 0 °C · 🧍 37 °C · ♨️ 100 °C"},{title:"Sự truyền nhiệt",text:"Nhiệt truyền từ vật nóng hơn sang vật lạnh hơn. Vật nhận nhiệt thì nóng lên, vật tỏa nhiệt thì lạnh đi.",example:"☕ ➡️ 🥄"}],practice:[{questions:[{id:"kh4-nhiet-do-01",type:"mc",q:"Dụng cụ nào dùng để đo nhiệt độ?",emoji:"🌡️",options:["Nhiệt kế","Thước kẻ","Cái cân","Đồng hồ"],answer:0,explain:"Nhiệt kế dùng để đo nhiệt độ."},{id:"kh4-nhiet-do-02",type:"number",q:"Nhiệt độ cơ thể người khỏe mạnh khoảng bao nhiêu độ C?",answer:37,unit:"°C",explain:"Người khỏe mạnh có nhiệt độ cơ thể khoảng 37 độ C."},{id:"kh4-nhiet-do-03",type:"tf",q:"Nhiệt truyền từ vật nóng hơn sang vật lạnh hơn.",answer:!0,explain:"Nhiệt luôn truyền từ vật nóng hơn sang vật lạnh hơn."},{id:"kh4-nhiet-do-04",type:"mc",q:"Nước đang sôi có nhiệt độ khoảng bao nhiêu?",options:["0 độ C","100 độ C","37 độ C","10 độ C"],answer:1,explain:"Nước sôi ở khoảng 100 độ C."},{id:"kh4-nhiet-do-05",type:"fill",q:"Vật nóng hơn có nhiệt độ … hơn vật lạnh.",answer:["cao"],explain:"Vật càng nóng thì nhiệt độ càng cao."},{id:"kh4-nhiet-do-06",type:"tf",q:"Cầm cốc nước đá, tay ta lạnh đi vì tay truyền nhiệt cho cốc.",answer:!0,explain:"Tay nóng hơn cốc nên tay tỏa nhiệt sang cốc và lạnh đi."},{id:"kh4-nhiet-do-07",type:"mc",q:"Thả thìa kim loại vào cốc nước nóng, một lúc sau cán thìa thế nào?",emoji:"🥄",options:["Nóng lên","Lạnh đi","Không đổi","Đông lại"],answer:0,explain:"Nước nóng truyền nhiệt cho thìa nên thìa nóng lên."},{id:"kh4-nhiet-do-08",type:"number",q:"Nước đá đang tan có nhiệt độ khoảng bao nhiêu độ C?",answer:0,unit:"°C",explain:"Nước đá đang tan có nhiệt độ khoảng 0 độ C."}]},{questions:[{id:"kh4-nhiet-do-09",type:"mc",q:"Đặt cốc nước nóng vào chậu nước lạnh. Điều gì xảy ra?",options:["Nước trong cốc càng lúc càng nóng thêm","Nước trong chậu càng lúc càng lạnh thêm","Nước trong cốc nguội đi, nước trong chậu ấm lên","Nước trong cốc và trong chậu không đổi"],answer:2,explain:"Nước nóng trong cốc truyền nhiệt sang nước lạnh trong chậu."},{id:"kh4-nhiet-do-10",type:"match",q:"Nối nhiệt độ với vật.",pairs:[["Khoảng 0 độ C","Nước đá đang tan"],["Khoảng 37 độ C","Cơ thể người khỏe mạnh"],["Khoảng 100 độ C","Nước đang sôi"]],explain:"Đây là những nhiệt độ quen thuộc cần nhớ."},{id:"kh4-nhiet-do-11",type:"tf",q:"Khi chườm khăn mát lên trán, trán tỏa nhiệt sang khăn nên mát đi.",answer:!0,explain:"Trán nóng hơn khăn nên truyền nhiệt sang khăn."},{id:"kh4-nhiet-do-12",type:"mc",q:"Hà bị sốt. Nhiệt độ cơ thể của Hà có thể là bao nhiêu?",options:["37 độ C","39 độ C","30 độ C","0 độ C"],answer:1,explain:"Sốt là khi nhiệt độ cơ thể cao hơn mức bình thường khoảng 37 độ C."},{id:"kh4-nhiet-do-13",type:"mc",q:"Đặt nồi canh lên bếp đang đun, nồi canh thế nào?",options:["Tỏa nhiệt và lạnh đi","Không thay đổi","Đông đặc lại","Nhận nhiệt và nóng lên"],answer:3,explain:"Bếp nóng hơn truyền nhiệt cho nồi canh."},{id:"kh4-nhiet-do-14",type:"mc",q:"Một cốc nước để trên bàn và một cốc nước để trong tủ lạnh. Cốc nào có nhiệt độ thấp hơn?",options:["Cốc trên bàn","Cốc trong tủ lạnh","Hai cốc bằng nhau","Không so sánh được"],answer:1,explain:"Trong tủ lạnh lạnh hơn nên nước trong đó có nhiệt độ thấp hơn."},{id:"kh4-nhiet-do-15",type:"tf",q:"Cốc trà nóng để lâu trên bàn sẽ nguội dần vì nó tỏa nhiệt ra xung quanh.",emoji:"🍵",answer:!0,explain:"Trà nóng hơn không khí nên tỏa nhiệt và nguội đi."},{id:"kh4-nhiet-do-16",type:"mc",q:"Để canh nguội nhanh, mẹ đặt bát canh vào chậu nước lạnh. Nhiệt truyền thế nào?",options:["Từ nước lạnh sang bát canh","Không truyền đi đâu","Từ nước lạnh lên không khí","Từ bát canh sang nước lạnh"],answer:3,explain:"Nhiệt truyền từ vật nóng hơn là bát canh sang nước lạnh."}]},{questions:[{id:"kh4-nhiet-do-17",type:"order",q:"Sắp xếp các bước đo nhiệt độ cơ thể bằng nhiệt kế điện tử.",items:["Bật nhiệt kế","Đặt đầu đo vào nách và kẹp chặt tay","Chờ đến khi nhiệt kế kêu bíp","Lấy ra đọc kết quả"],explain:"Bật máy, kẹp đúng chỗ, chờ tín hiệu rồi đọc kết quả."},{id:"kh4-nhiet-do-18",type:"mc",q:"Khi bị sốt, em nên làm gì trước tiên?",options:["Đắp thật nhiều chăn","Báo cho người lớn biết","Ra nắng cho ấm","Tự uống thuốc tùy ý"],answer:1,explain:"Người lớn sẽ đo nhiệt độ, chườm mát và đưa đi khám khi cần."},{id:"kh4-nhiet-do-19",type:"number",q:"Buổi sáng nhiệt độ ngoài trời là 25 độ C, đến trưa tăng thêm 7 độ C. Buổi trưa nhiệt độ là bao nhiêu độ C?",answer:32,unit:"°C",explain:"Nhiệt độ buổi trưa là 25 + 7 = 32 độ C."},{id:"kh4-nhiet-do-20",type:"tf",q:"Áp tay vào thành nồi đang đun là cách an toàn để biết nồi đã nóng chưa.",answer:!1,explain:"Áp tay vào nồi đang đun có thể bị bỏng."},{id:"kh4-nhiet-do-21",type:"mc",q:"Đổ chung một cốc nước 20 độ C và một cốc nước 60 độ C vào một bình. Nhiệt độ nước trong bình thế nào?",options:["Cao hơn 60 độ C","Ở giữa 20 độ C và 60 độ C","Thấp hơn 20 độ C","Bằng đúng 0 độ C"],answer:1,explain:"Nước nóng truyền nhiệt cho nước lạnh nên nhiệt độ ở giữa hai mức."},{id:"kh4-nhiet-do-22",type:"multi",q:"Những việc nào dựa vào sự truyền nhiệt?",options:["Lọc nước bằng cát","Pha nước muối","Chườm khăn mát khi sốt","Ngâm chai nước vào chậu nước đá cho mát"],answers:[2,3],explain:"Chườm mát và làm mát chai nước là nhờ nhiệt truyền từ vật nóng sang vật lạnh."},{id:"kh4-nhiet-do-23",type:"mc",q:"Vì sao chạm tay vào cốc nước đá ta thấy lạnh?",options:["Vì cốc truyền cái lạnh sang tay ta","Vì tay truyền nhiệt sang cốc nên tay lạnh đi","Vì cốc tỏa nhiệt sang làm tay lạnh","Vì bàn tay ta không có chút nhiệt nào"],answer:1,explain:"Không có “cái lạnh” truyền đi; chỉ có nhiệt truyền từ tay sang cốc."},{id:"kh4-nhiet-do-24",type:"number",q:"An đo được nhiệt độ cơ thể là 39 độ C. Nhiệt độ bình thường khoảng 37 độ C. Nhiệt độ của An cao hơn bình thường bao nhiêu độ C?",answer:2,unit:"°C",explain:"Nhiệt độ cao hơn là 39 − 37 = 2 độ C."}]}],challenge:{questions:[{id:"kh4-nhiet-do-25",type:"mc",q:"Một thìa kim loại để trong cốc nước sôi, một thìa để trong cốc nước đá. Sau một lúc, thìa nào nóng hơn?",options:["Thìa trong cốc nước đá","Hai thìa như nhau","Không thìa nào thay đổi","Thìa trong cốc nước sôi"],answer:3,explain:"Nước sôi truyền nhiệt cho thìa; thìa trong nước đá thì tỏa nhiệt nên lạnh đi."},{id:"kh4-nhiet-do-26",type:"order",q:"Sắp xếp các vật theo nhiệt độ từ thấp đến cao.",items:["Nước đá đang tan","Cốc nước mát trong phòng","Cơ thể người khỏe mạnh","Nước đang sôi"],explain:"Khoảng 0 độ C, nước mát, khoảng 37 độ C rồi khoảng 100 độ C."},{id:"kh4-nhiet-do-27",type:"tf",q:"Vật lạnh truyền cái lạnh sang vật nóng.",answer:!1,explain:"Chỉ có nhiệt truyền từ vật nóng hơn sang vật lạnh hơn."},{id:"kh4-nhiet-do-28",type:"multi",q:"Vật nào đang tỏa nhiệt?",options:["Que kem đang chảy dưới nắng","Viên nước đá đang tan trong cốc","Cốc sữa nóng đang nguội dần","Nồi cơm vừa nấu xong để trên bàn"],answers:[2,3],explain:"Vật đang nguội đi là vật tỏa nhiệt; đá và kem đang nhận nhiệt nên tan chảy."},{id:"kh4-nhiet-do-29",type:"number",q:"Một cốc nước nóng 80 độ C, sau một lúc nguội còn 45 độ C. Nhiệt độ đã giảm bao nhiêu độ C?",answer:35,unit:"°C",explain:"Nhiệt độ đã giảm 80 − 45 = 35 độ C."},{id:"kh4-nhiet-do-30",type:"mc",q:"Vì sao khi bị bỏng nhẹ, người ta xả nước mát lên chỗ bỏng?",options:["Nước mát truyền cái lạnh vào trong da","Nước mát làm da nóng thêm một chút","Nước mát làm vết bỏng to ra nhanh","Nước mát nhận nhiệt từ da, làm da bớt nóng"],answer:3,explain:"Da nóng truyền nhiệt sang nước mát nên chỗ bỏng dịu đi."}]},summary:["Nhiệt kế dùng để đo nhiệt độ; người khỏe mạnh khoảng 37 độ C.","Nhiệt truyền từ vật nóng hơn sang vật lạnh hơn.","Vật nhận nhiệt thì nóng lên, vật tỏa nhiệt thì lạnh đi."]},{id:"kh4-dan-nhiet-cach-nhiet",title:"Bài 15: Vật dẫn nhiệt và vật cách nhiệt",weeks:[17,18],learn:[{title:"Vật dẫn nhiệt tốt",text:"Kim loại như đồng, nhôm, sắt dẫn nhiệt tốt. Xoong, nồi, chảo thường làm bằng kim loại để nấu nhanh chín.",example:"🍳 🥘"},{title:"Vật dẫn nhiệt kém",text:"Gỗ, nhựa, cao su, len, bông, xốp, không khí dẫn nhiệt kém. Chúng còn được gọi là vật cách nhiệt.",example:"🧤 🧣 📦"},{title:"Ứng dụng",text:"Quai nồi làm bằng nhựa hoặc gỗ để không bị bỏng. Áo len, chăn bông giữ ấm. Hộp xốp, bình giữ nhiệt giữ nóng hoặc giữ lạnh lâu.",example:"🫖 🧥"}],practice:[{questions:[{id:"kh4-dan-nhiet-cach-nhiet-01",type:"multi",q:"Những vật nào dẫn nhiệt tốt?",options:["Cốc nhựa","Thìa nhôm","Thanh sắt","Nồi đồng","Đũa gỗ"],answers:[1,2,3],explain:"Kim loại như nhôm, đồng, sắt dẫn nhiệt tốt."},{id:"kh4-dan-nhiet-cach-nhiet-02",type:"multi",q:"Những vật nào dẫn nhiệt kém?",options:["Nồi nhôm","Hộp xốp","Găng tay len","Đũa gỗ","Chảo sắt"],answers:[1,2,3],explain:"Gỗ, len, xốp dẫn nhiệt kém."},{id:"kh4-dan-nhiet-cach-nhiet-03",type:"mc",q:"Quai nồi thường làm bằng gì để cầm không bị bỏng?",options:["Đồng","Sắt","Nhựa hoặc gỗ","Nhôm"],answer:2,explain:"Nhựa và gỗ dẫn nhiệt kém nên cầm không bị nóng."},{id:"kh4-dan-nhiet-cach-nhiet-04",type:"tf",q:"Kim loại dẫn nhiệt kém.",answer:!1,explain:"Kim loại như đồng, nhôm, sắt dẫn nhiệt tốt."},{id:"kh4-dan-nhiet-cach-nhiet-05",type:"fill",q:"Gỗ, nhựa, len, bông là những vật dẫn nhiệt … .",answer:["kém"],explain:"Chúng dẫn nhiệt kém nên được dùng để cách nhiệt."},{id:"kh4-dan-nhiet-cach-nhiet-06",type:"mc",q:"Vì sao xoong, nồi thường làm bằng kim loại?",options:["Vì kim loại dẫn nhiệt tốt, nấu nhanh chín","Vì kim loại dẫn nhiệt kém, giữ ấm lâu","Vì kim loại nhẹ hơn cả tờ giấy","Vì kim loại có nhiều màu sắc đẹp"],answer:0,explain:"Kim loại truyền nhiệt từ bếp vào thức ăn nhanh."},{id:"kh4-dan-nhiet-cach-nhiet-07",type:"tf",q:"Không khí là vật dẫn nhiệt tốt.",answer:!1,explain:"Không khí dẫn nhiệt kém nên giúp giữ ấm."},{id:"kh4-dan-nhiet-cach-nhiet-08",type:"mc",q:"Mùa đông, mặc áo len giúp gì?",emoji:"🧶",options:["Làm cơ thể lạnh đi","Làm áo nhẹ hơn","Giữ ấm cơ thể","Làm trời ấm lên"],answer:2,explain:"Len dẫn nhiệt kém nên giữ nhiệt của cơ thể lại."}]},{questions:[{id:"kh4-dan-nhiet-cach-nhiet-09",type:"match",q:"Nối đồ vật với lí do làm bằng vật liệu đó.",pairs:[["Nồi bằng nhôm","Dẫn nhiệt tốt, nấu nhanh chín"],["Quai nồi bằng nhựa","Cách nhiệt, cầm không bỏng"],["Hộp xốp đựng đá","Giữ lạnh lâu"]],explain:"Chọn vật liệu theo khả năng dẫn nhiệt."},{id:"kh4-dan-nhiet-cach-nhiet-10",type:"mc",q:"Cắm một thìa nhôm và một thìa nhựa vào cốc nước nóng. Sau một lúc, cán thìa nào nóng hơn?",options:["Thìa nhôm","Thìa nhựa","Hai thìa nóng như nhau","Không thìa nào nóng"],answer:0,explain:"Nhôm dẫn nhiệt tốt hơn nhựa."},{id:"kh4-dan-nhiet-cach-nhiet-11",type:"tf",q:"Chăn bông giữ ấm vì giữa các sợi bông có nhiều không khí.",answer:!0,explain:"Không khí và bông dẫn nhiệt kém nên giữ ấm tốt."},{id:"kh4-dan-nhiet-cach-nhiet-12",type:"mc",q:"Vì sao cần lót miếng lót bằng vải dày hoặc gỗ khi đặt nồi nóng lên bàn?",options:["Để nồi nóng thêm lâu","Để nhiệt không làm hỏng mặt bàn","Để nồi trông đẹp hơn","Để bàn dẫn nhiệt tốt hơn"],answer:1,explain:"Vải dày, gỗ cách nhiệt nên bảo vệ mặt bàn."},{id:"kh4-dan-nhiet-cach-nhiet-13",type:"multi",q:"Bộ phận nào cần làm bằng vật dẫn nhiệt tốt?",options:["Tay cầm chảo","Găng tay nhấc nồi","Lòng chảo","Đáy nồi"],answers:[2,3],explain:"Đáy nồi, lòng chảo cần dẫn nhiệt tốt; tay cầm, găng tay cần cách nhiệt."},{id:"kh4-dan-nhiet-cach-nhiet-14",type:"mc",q:"Ngày lạnh, chạm tay vào thanh sắt thấy lạnh hơn chạm vào tấm gỗ dù hai vật để cùng chỗ. Vì sao?",options:["Vì thanh sắt chứa nhiều cái lạnh hơn gỗ","Vì sắt dẫn nhiệt tốt, lấy nhiệt từ tay nhanh hơn","Vì tấm gỗ tự phát ra nhiệt sưởi ấm tay","Vì thanh sắt nhẹ hơn tấm gỗ rất nhiều"],answer:1,explain:"Sắt dẫn nhiệt tốt nên nhiệt từ tay truyền sang sắt nhanh, ta thấy lạnh hơn."},{id:"kh4-dan-nhiet-cach-nhiet-15",type:"tf",q:"Bình giữ nhiệt giữ cho nước nóng lâu vì nó cách nhiệt tốt.",answer:!0,explain:"Bình giữ nhiệt ngăn nhiệt thoát ra ngoài."},{id:"kh4-dan-nhiet-cach-nhiet-16",type:"mc",q:"Cách nào giúp giữ nước đá lâu tan nhất?",options:["Để trong hộp sắt mỏng ngoài nắng","Để trong chậu nhôm không đậy","Để trong hộp xốp có nắp","Để trên đĩa cạnh bếp"],answer:2,explain:"Xốp cách nhiệt, nắp đậy kín giúp đá lâu tan."}]},{questions:[{id:"kh4-dan-nhiet-cach-nhiet-17",type:"order",q:"Sắp xếp thí nghiệm so sánh sự dẫn nhiệt của thìa nhôm và thìa nhựa.",items:["Chuẩn bị thìa nhôm và thìa nhựa cùng cỡ","Cắm hai thìa vào cốc nước nóng","Chờ khoảng một phút","Chạm nhẹ vào cán hai thìa để so sánh"],explain:"Hai thìa cùng cỡ, cùng cốc nước, chỉ khác vật liệu thì mới so sánh được."},{id:"kh4-dan-nhiet-cach-nhiet-18",type:"mc",q:"Mẹ nhắc Nam dùng lót tay khi nhấc nồi. Lót tay nên làm bằng gì?",options:["Nhôm","Sắt","Đồng","Vải dày"],answer:3,explain:"Vải dày dẫn nhiệt kém nên tay không bị bỏng."},{id:"kh4-dan-nhiet-cach-nhiet-19",type:"multi",q:"Muốn mang cơm đi mà vẫn giữ cơm nóng lâu, có thể làm gì?",options:["Đựng trong đĩa nhôm không đậy","Đựng trong hộp giữ nhiệt","Mở nắp hộp trước quạt","Bọc hộp cơm bằng khăn dày"],answers:[1,3],explain:"Vật cách nhiệt và đậy kín giúp cơm lâu nguội."},{id:"kh4-dan-nhiet-cach-nhiet-20",type:"tf",q:"Mùa đông, mặc nhiều lớp áo giữ ấm tốt vì giữa các lớp áo có không khí.",answer:!0,explain:"Lớp không khí giữa các áo dẫn nhiệt kém nên giữ ấm."},{id:"kh4-dan-nhiet-cach-nhiet-21",type:"mc",q:"Vì sao thùng đựng kem của người bán hàng rong thường làm bằng xốp?",emoji:"🍦",options:["Vì xốp dẫn nhiệt rất tốt","Vì xốp cách nhiệt, giữ kem lâu tan","Vì xốp làm kem nóng lên","Vì xốp có mùi thơm"],answer:1,explain:"Xốp dẫn nhiệt kém nên nhiệt bên ngoài khó truyền vào kem."},{id:"kh4-dan-nhiet-cach-nhiet-22",type:"mc",q:"Chảo sắt có tay cầm cũng bằng sắt. Khi nấu cần chú ý gì?",options:["Cầm bằng tay không cho chắc","Nhúng tay vào nước lạnh rồi cầm","Không cần chú ý điều gì","Dùng lót tay khi cầm vì tay cầm sẽ nóng"],answer:3,explain:"Sắt dẫn nhiệt tốt nên tay cầm cũng nóng lên."},{id:"kh4-dan-nhiet-cach-nhiet-23",type:"match",q:"Nối vật với tác dụng chính.",pairs:[["Bình giữ nhiệt","Giữ nước nóng lâu"],["Thìa nhôm khuấy canh","Nóng lên nhanh"],["Áo bông","Giữ ấm cơ thể"]],explain:"Vật dẫn nhiệt tốt nóng lên nhanh; vật cách nhiệt giữ nhiệt."},{id:"kh4-dan-nhiet-cach-nhiet-24",type:"tf",q:"Dùng đũa nhôm để đảo thức ăn trong chảo dầu nóng thì an toàn hơn đũa tre.",answer:!1,explain:"Nhôm dẫn nhiệt tốt nên đũa nhôm nóng lên nhanh, dễ gây bỏng tay."}]}],challenge:{questions:[{id:"kh4-dan-nhiet-cach-nhiet-25",type:"mc",q:"Cửa sổ hai lớp kính có lớp không khí ở giữa giúp nhà ấm hơn vào mùa đông. Vì sao?",options:["Vì không khí dẫn nhiệt kém","Vì không khí dẫn nhiệt tốt","Vì kính phát ra nhiệt","Vì không khí có màu"],answer:0,explain:"Lớp không khí giữa hai tấm kính cản nhiệt thoát ra ngoài."},{id:"kh4-dan-nhiet-cach-nhiet-26",type:"multi",q:"Những vật liệu nào là vật cách nhiệt?",options:["Xốp","Len","Gỗ khô","Đồng","Nhôm"],answers:[0,1,2],explain:"Xốp, len, gỗ khô dẫn nhiệt kém; đồng, nhôm dẫn nhiệt tốt."},{id:"kh4-dan-nhiet-cach-nhiet-27",type:"mc",q:"Ba cốc nước nóng như nhau: một cốc bọc giấy báo mỏng, một cốc bọc khăn len dày, một cốc không bọc. Cốc nào giữ nóng lâu nhất?",options:["Cốc bọc khăn len dày","Cốc bọc giấy báo mỏng","Cốc không bọc","Ba cốc nguội như nhau"],answer:0,explain:"Khăn len dày cách nhiệt tốt nhất trong ba cách."},{id:"kh4-dan-nhiet-cach-nhiet-28",type:"tf",q:"Bọc ống dẫn nước nóng bằng lớp vật liệu cách nhiệt giúp nước ít bị nguội.",answer:!0,explain:"Lớp cách nhiệt ngăn nhiệt thoát ra ngoài."},{id:"kh4-dan-nhiet-cach-nhiet-29",type:"order",q:"Sắp xếp thí nghiệm tìm vật liệu giữ đá lâu tan.",items:["Lấy các viên đá to bằng nhau","Bọc mỗi viên bằng một vật liệu khác nhau","Đặt các viên đá ở cùng một nơi","Sau một thời gian, so sánh viên nào tan ít nhất"],explain:"Các viên đá giống nhau, chỉ khác vật liệu bọc thì mới so sánh công bằng."},{id:"kh4-dan-nhiet-cach-nhiet-30",type:"mc",q:"Bình giữ nhiệt có giữ lạnh cho nước đá được không?",options:["Được, vì bình cách nhiệt nên nhiệt bên ngoài khó truyền vào","Không được, vì bình giữ nhiệt chỉ giữ được nước nóng","Không được, vì bình giữ nhiệt làm đá tan nhanh hơn","Chỉ được khi để bình ở ngoài nắng thật lâu"],answer:0,explain:"Vật cách nhiệt ngăn nhiệt truyền qua theo cả hai chiều."}]},summary:["Kim loại dẫn nhiệt tốt; gỗ, nhựa, len, bông, xốp, không khí dẫn nhiệt kém.","Vật dẫn nhiệt tốt dùng làm xoong nồi; vật cách nhiệt dùng làm quai nồi, áo ấm, hộp giữ nhiệt.","Dùng lót tay, tay cầm cách nhiệt để không bị bỏng."]}]},{id:"thuc-vat-dong-vat",title:"Thực vật và động vật",lessons:[{id:"kh4-nhu-cau-thuc-vat",title:"Bài 16: Nhu cầu sống của thực vật",weeks:[19,19],learn:[{title:"Thực vật cần gì",text:"Thực vật cần nước, ánh sáng, không khí, chất khoáng và nhiệt độ thích hợp để sống và phát triển.",example:"💧 ☀️ 🌬️ 🌱"},{title:"Trao đổi chất ở thực vật",text:"Cây lấy nước và chất khoáng từ đất qua rễ, lấy khí các-bô-níc từ không khí. Khi có ánh sáng, cây chế tạo chất dinh dưỡng và thải ra khí ô-xi.",example:"🌳 ⬇️ 💧 · ⬆️ 🌬️"},{title:"Mỗi loài một nhu cầu",text:"Có cây cần nhiều nước như lúa; có cây cần ít nước như xương rồng. Có cây ưa sáng, có cây ưa bóng râm như lá lốt.",example:"🌾 🌵"}],practice:[{questions:[{id:"kh4-nhu-cau-thuc-vat-01",type:"multi",q:"Thực vật cần những gì để sống và phát triển?",options:["Chất khoáng","Ánh sáng","Nước","Tiếng nhạc","Không khí"],answers:[0,1,2,4],explain:"Thực vật cần nước, ánh sáng, không khí, chất khoáng và nhiệt độ thích hợp."},{id:"kh4-nhu-cau-thuc-vat-02",type:"mc",q:"Cây hút nước và chất khoáng từ đất nhờ bộ phận nào?",options:["Hoa","Quả","Rễ","Lá"],answer:2,explain:"Rễ cây hút nước và chất khoáng từ đất."},{id:"kh4-nhu-cau-thuc-vat-03",type:"tf",q:"Khi có ánh sáng, cây lấy khí các-bô-níc và thải ra khí ô-xi.",answer:!0,explain:"Cây dùng khí các-bô-níc để chế tạo chất dinh dưỡng và thải ra khí ô-xi."},{id:"kh4-nhu-cau-thuc-vat-04",type:"mc",q:"Cây nào cần ít nước?",emoji:"🌵",options:["Cây lúa","Cây rau muống","Cây xương rồng","Cây sen"],answer:2,explain:"Xương rồng sống được ở nơi khô hạn, cần rất ít nước."},{id:"kh4-nhu-cau-thuc-vat-05",type:"fill",q:"Cây lấy nước và chất … từ đất qua rễ.",answer:["khoáng"],explain:"Rễ cây hút nước và chất khoáng hòa tan trong đất."},{id:"kh4-nhu-cau-thuc-vat-06",type:"tf",q:"Cây có thể sống lâu trong tủ tối mà không cần ánh sáng.",answer:!1,explain:"Cây cần ánh sáng để chế tạo chất dinh dưỡng."},{id:"kh4-nhu-cau-thuc-vat-07",type:"mc",q:"Phân bón cung cấp cho cây chủ yếu thứ gì?",options:["Ánh sáng","Không khí","Chất khoáng","Nhiệt độ"],answer:2,explain:"Phân bón bổ sung chất khoáng cho đất trồng."},{id:"kh4-nhu-cau-thuc-vat-08",type:"mc",q:"Cây nào sống được trong nước?",emoji:"🪷",options:["Cây xương rồng","Cây sen","Cây ngô","Cây mía"],answer:1,explain:"Sen sống ở ao, hồ, đầm."}]},{questions:[{id:"kh4-nhu-cau-thuc-vat-09",type:"match",q:"Nối cây với nhu cầu về nước.",pairs:[["Cây lúa","Cần nhiều nước"],["Cây xương rồng","Cần ít nước"],["Cây sen","Sống trong nước"]],explain:"Mỗi loài cây cần lượng nước khác nhau."},{id:"kh4-nhu-cau-thuc-vat-10",type:"match",q:"Nối thứ cây lấy vào với nơi lấy.",pairs:[["Nước và chất khoáng","Từ đất qua rễ"],["Khí các-bô-níc","Từ không khí qua lá"],["Ánh sáng","Từ Mặt Trời"]],explain:"Cây lấy nước, chất khoáng từ đất và khí các-bô-níc từ không khí."},{id:"kh4-nhu-cau-thuc-vat-11",type:"mc",q:"Vì sao cây để trong tủ kín lâu ngày bị vàng lá?",options:["Vì thừa nước","Vì thừa chất khoáng","Vì tủ quá rộng","Vì thiếu ánh sáng"],answer:3,explain:"Không có ánh sáng, cây không chế tạo được chất dinh dưỡng."},{id:"kh4-nhu-cau-thuc-vat-12",type:"tf",q:"Mọi loài cây đều cần lượng nước và ánh sáng như nhau.",answer:!1,explain:"Có cây cần nhiều nước, có cây cần ít; có cây ưa sáng, có cây ưa bóng."},{id:"kh4-nhu-cau-thuc-vat-13",type:"multi",q:"Cây nào ưa bóng râm?",options:["Cây dương xỉ","Cây lá lốt","Cây hướng dương","Cây lúa"],answers:[0,1],explain:"Lá lốt, dương xỉ sống tốt ở nơi râm mát; lúa và hướng dương ưa nhiều nắng."},{id:"kh4-nhu-cau-thuc-vat-14",type:"mc",q:"Khi chế tạo chất dinh dưỡng, cây thải ra khí gì?",options:["Khí các-bô-níc","Khói","Bụi","Khí ô-xi"],answer:3,explain:"Cây thải ra khí ô-xi khi chế tạo chất dinh dưỡng."},{id:"kh4-nhu-cau-thuc-vat-15",type:"tf",q:"Trời quá lạnh hoặc quá nóng đều có thể làm cây chậm lớn.",answer:!0,explain:"Cây cần nhiệt độ thích hợp để phát triển."},{id:"kh4-nhu-cau-thuc-vat-16",type:"mc",q:"Vì sao cây trồng trên đất bạc màu thường còi cọc?",options:["Vì đất có quá nhiều ánh sáng","Vì đất thiếu chất khoáng","Vì đất quá tơi xốp","Vì đất có màu đẹp"],answer:1,explain:"Đất bạc màu nghèo chất khoáng nên cây không đủ chất để lớn."}]},{questions:[{id:"kh4-nhu-cau-thuc-vat-17",type:"order",q:"Sắp xếp thí nghiệm tìm hiểu cây có cần nước không.",items:["Chọn hai cây con giống nhau","Đặt cả hai cây ở nơi có ánh sáng","Chỉ tưới nước cho một cây","Sau vài ngày, so sánh hai cây"],explain:"Hai cây chỉ khác nhau ở việc có được tưới hay không."},{id:"kh4-nhu-cau-thuc-vat-18",type:"mc",q:"Trong thí nghiệm trên, cây không được tưới nước sẽ thế nào?",options:["Xanh tốt hơn","Ra hoa sớm hơn","Héo dần","Không thay đổi"],answer:2,explain:"Thiếu nước, cây héo dần."},{id:"kh4-nhu-cau-thuc-vat-19",type:"mc",q:"Nam trồng cây xương rồng trong chậu. Nên tưới thế nào?",options:["Tưới ngập nước mỗi ngày","Ngâm cả chậu trong nước","Tưới ít, khi đất đã khô","Không bao giờ tưới"],answer:2,explain:"Xương rồng cần ít nước; tưới nhiều dễ thối rễ."},{id:"kh4-nhu-cau-thuc-vat-20",type:"multi",q:"Bác nông dân muốn lúa tốt. Cần chú ý điều gì?",options:["Ruộng đủ nước","Bón phân hợp lí","Đủ ánh sáng","Che kín ruộng lúa"],answers:[0,1,2],explain:"Lúa cần nhiều nước, đủ chất khoáng và nhiều ánh sáng."},{id:"kh4-nhu-cau-thuc-vat-21",type:"tf",q:"Chậu cây đặt trong phòng tối nên thỉnh thoảng được mang ra chỗ có ánh sáng.",answer:!0,explain:"Cây cần ánh sáng để sống khỏe."},{id:"kh4-nhu-cau-thuc-vat-22",type:"mc",q:"Vì sao không nên tưới quá nhiều nước cho cây trồng cạn?",options:["Vì cây sẽ lớn quá nhanh","Vì đất bị úng, rễ cây thiếu không khí","Vì cây sẽ ra quả quá to","Vì nước làm lá đổi màu đẹp hơn"],answer:1,explain:"Đất ngập nước làm rễ thiếu không khí và dễ thối."},{id:"kh4-nhu-cau-thuc-vat-23",type:"match",q:"Nối dấu hiệu với điều cây đang thiếu.",pairs:[["Lá héo rũ, đất khô nứt","Thiếu nước"],["Thân vươn dài, lá vàng nhạt ở chỗ tối","Thiếu ánh sáng"],["Cây còi cọc trên đất bạc màu","Thiếu chất khoáng"]],explain:"Quan sát cây giúp biết cây đang thiếu gì."},{id:"kh4-nhu-cau-thuc-vat-24",type:"mc",q:"Lan đặt chậu hoa hướng dương ở góc nhà tối. Lời khuyên nào đúng?",emoji:"🌻",options:["Để nguyên ở góc nhà","Cất chậu vào trong tủ","Tưới thật nhiều nước","Đưa chậu ra chỗ nhiều nắng"],answer:3,explain:"Hướng dương là cây ưa sáng."}]}],challenge:{questions:[{id:"kh4-nhu-cau-thuc-vat-25",type:"mc",q:"Cây xanh góp phần làm cho không khí có thêm khí nào?",options:["Khí các-bô-níc","Khói","Bụi","Khí ô-xi"],answer:3,explain:"Khi chế tạo chất dinh dưỡng, cây thải ra khí ô-xi."},{id:"kh4-nhu-cau-thuc-vat-26",type:"mc",q:"Hai cây giống nhau: cây A trồng trong đất có bón phân hợp lí, cây B trồng trong cát không bón phân. Sau một thời gian, cây nào tốt hơn?",options:["Cây B","Hai cây như nhau","Cả hai đều chết ngay","Cây A"],answer:3,explain:"Cây A có đủ chất khoáng nên phát triển tốt hơn."},{id:"kh4-nhu-cau-thuc-vat-27",type:"multi",q:"Khi làm thí nghiệm xem cây có cần ánh sáng không, cần giữ giống nhau những điều nào?",options:["Loại đất","Lượng nước tưới","Loại cây","Ánh sáng"],answers:[0,1,2],explain:"Chỉ để ánh sáng khác nhau, những điều khác phải giống nhau."},{id:"kh4-nhu-cau-thuc-vat-28",type:"tf",q:"Cây cần không khí nên đất trồng cần tơi xốp.",answer:!0,explain:"Đất tơi xốp có nhiều không khí cho rễ cây."},{id:"kh4-nhu-cau-thuc-vat-29",type:"match",q:"Nối cây với nơi sống thích hợp.",pairs:[["Cây lúa","Ruộng nước"],["Cây xương rồng","Nơi khô hạn"],["Cây lá lốt","Chỗ râm mát, ẩm"]],explain:"Mỗi loài cây hợp với một nơi sống."},{id:"kh4-nhu-cau-thuc-vat-30",type:"mc",q:"Vì sao rau trồng trong nhà kính có mái trong suốt vẫn lớn tốt?",options:["Vì ánh sáng vẫn chiếu qua mái kính và cây được chăm sóc đủ nước","Vì trong nhà kính hoàn toàn không có không khí","Vì cây trồng trong nhà kính không cần nước","Vì mái kính cản hết ánh sáng chiếu vào cây"],answer:0,explain:"Nhà kính trong suốt cho ánh sáng đi qua, cây vẫn đủ điều kiện sống."}]},summary:["Thực vật cần nước, ánh sáng, không khí, chất khoáng và nhiệt độ thích hợp.","Cây lấy nước, chất khoáng, khí các-bô-níc và thải ra khí ô-xi khi chế tạo chất dinh dưỡng.","Mỗi loài cây có nhu cầu riêng về nước và ánh sáng."]},{id:"kh4-nhu-cau-dong-vat",title:"Bài 17: Nhu cầu sống của động vật",weeks:[20,20],learn:[{title:"Động vật cần gì",text:"Động vật cần thức ăn, nước, không khí, ánh sáng và nhiệt độ thích hợp để sống và phát triển.",example:"🍖 💧 🌬️ ☀️"},{title:"Trao đổi chất ở động vật",text:"Động vật lấy thức ăn, nước, khí ô-xi từ môi trường; thải ra phân, nước tiểu và khí các-bô-níc.",example:"🐄 🌿 💧 🌬️"},{title:"Thức ăn khác nhau",text:"Có loài ăn thực vật như trâu, bò, thỏ; có loài ăn thịt như hổ; có loài ăn cả thực vật và động vật như lợn, gà.",example:"🐃 🐅 🐖"}],practice:[{questions:[{id:"kh4-nhu-cau-dong-vat-01",type:"multi",q:"Động vật cần những gì để sống?",options:["Không khí","Đồ chơi","Nước","Thức ăn"],answers:[0,2,3],explain:"Động vật cần thức ăn, nước, không khí, ánh sáng và nhiệt độ thích hợp."},{id:"kh4-nhu-cau-dong-vat-02",type:"mc",q:"Con vật nào ăn cỏ?",emoji:"🐄",options:["Con hổ","Con mèo","Con bò","Con đại bàng"],answer:2,explain:"Bò ăn cỏ, là loài ăn thực vật."},{id:"kh4-nhu-cau-dong-vat-03",type:"mc",q:"Khi thở, động vật lấy vào khí gì?",options:["Khí các-bô-níc","Khói","Bụi","Khí ô-xi"],answer:3,explain:"Động vật lấy khí ô-xi để thở."},{id:"kh4-nhu-cau-dong-vat-04",type:"tf",q:"Động vật thải ra môi trường phân, nước tiểu và khí các-bô-níc.",answer:!0,explain:"Đó là những chất động vật thải ra trong quá trình sống."},{id:"kh4-nhu-cau-dong-vat-05",type:"mc",q:"Con vật nào ăn thịt?",emoji:"🐅",options:["Con trâu","Con thỏ","Con dê","Con hổ"],answer:3,explain:"Hổ săn bắt con vật khác để ăn thịt."},{id:"kh4-nhu-cau-dong-vat-06",type:"fill",q:"Động vật lấy khí … từ không khí để thở.",answer:["ô-xi","ô xi","ôxi","oxi","oxy"],explain:"Động vật cần khí ô-xi để thở."},{id:"kh4-nhu-cau-dong-vat-07",type:"tf",q:"Động vật không cần nước để sống.",answer:!1,explain:"Động vật cần nước; thiếu nước động vật sẽ chết."},{id:"kh4-nhu-cau-dong-vat-08",type:"mc",q:"Con gà thường ăn những gì?",emoji:"🐔",options:["Chỉ ăn cỏ tươi","Chỉ ăn thịt bò","Chỉ uống nước lã","Thóc, ngô và sâu bọ"],answer:3,explain:"Gà ăn cả hạt và sâu bọ."}]},{questions:[{id:"kh4-nhu-cau-dong-vat-09",type:"match",q:"Nối con vật với thức ăn chính.",pairs:[["Con trâu","Cỏ"],["Con hổ","Thịt con vật khác"],["Con lợn","Cả thực vật và động vật"]],explain:"Mỗi loài động vật có thức ăn khác nhau."},{id:"kh4-nhu-cau-dong-vat-10",type:"mc",q:"Vì sao chuồng nuôi gà cần thoáng khí?",options:["Vì gà thích gió lạnh","Vì gà không cần ăn","Vì gà cần không khí để thở","Vì chuồng kín làm gà đẻ nhiều"],answer:2,explain:"Chuồng thoáng giúp gà có đủ không khí."},{id:"kh4-nhu-cau-dong-vat-11",type:"tf",q:"Mùa đông giá rét, chuồng vật nuôi cần được che chắn để giữ ấm.",answer:!0,explain:"Vật nuôi cần nhiệt độ thích hợp, trời rét cần giữ ấm."},{id:"kh4-nhu-cau-dong-vat-12",type:"multi",q:"Con vật nào ăn thực vật?",options:["Con trâu","Con thỏ","Con hổ","Con dê","Con sói"],answers:[0,1,3],explain:"Thỏ, trâu, dê ăn thực vật; hổ, sói ăn thịt."},{id:"kh4-nhu-cau-dong-vat-13",type:"mc",q:"Vì sao vật nuôi bị bỏ đói lâu ngày sẽ gầy yếu?",options:["Vì được uống quá nhiều nước sạch","Vì được hít thở quá nhiều không khí","Vì thiếu thức ăn cung cấp chất dinh dưỡng","Vì được ngủ quá nhiều mỗi ngày"],answer:2,explain:"Thức ăn cung cấp chất dinh dưỡng giúp động vật sống và lớn lên."},{id:"kh4-nhu-cau-dong-vat-14",type:"tf",q:"Động vật tự chế tạo được chất dinh dưỡng từ ánh sáng giống cây xanh.",answer:!1,explain:"Động vật phải ăn thực vật hoặc động vật khác để có chất dinh dưỡng."},{id:"kh4-nhu-cau-dong-vat-15",type:"mc",q:"Con vật nào sống được ở vùng băng tuyết rất lạnh?",emoji:"🐻‍❄️",options:["Lạc đà","Con trâu","Con voi","Gấu trắng"],answer:3,explain:"Gấu trắng có bộ lông dày và lớp mỡ dày, sống được ở vùng băng giá."},{id:"kh4-nhu-cau-dong-vat-16",type:"mc",q:"Thức ăn có vai trò gì với động vật?",options:["Giúp động vật không cần thở không khí nữa","Giúp động vật không cần uống nước nữa","Cung cấp chất dinh dưỡng giúp động vật sống và lớn lên","Không có vai trò gì với động vật"],answer:2,explain:"Thức ăn là nguồn chất dinh dưỡng của động vật."}]},{questions:[{id:"kh4-nhu-cau-dong-vat-17",type:"mc",q:"Chú chó con bị nhốt nhầm trong nhà kho kín, nóng, không có nước. Cần làm gì ngay?",options:["Cứ để nguyên trong nhà kho","Cho ăn thật nhiều đồ khô","Mang ra phơi ngoài nắng","Đưa ra chỗ thoáng mát và cho uống nước"],answer:3,explain:"Chó con cần không khí, nước và nhiệt độ thích hợp."},{id:"kh4-nhu-cau-dong-vat-18",type:"multi",q:"Một con mèo cần những gì hằng ngày?",options:["Bị nhốt trong hộp kín","Nước sạch","Chỗ ở thoáng, sạch","Thức ăn phù hợp"],answers:[1,2,3],explain:"Mèo cần thức ăn, nước và chỗ ở thoáng, sạch."},{id:"kh4-nhu-cau-dong-vat-19",type:"mc",q:"Vì sao mùa hè người ta hay cho trâu đầm mình dưới nước?",emoji:"🐃",options:["Để trâu ăn cá","Để trâu được mát","Để trâu học bơi","Để trâu đổi màu da"],answer:1,explain:"Trâu cần nhiệt độ thích hợp, đầm nước giúp trâu mát."},{id:"kh4-nhu-cau-dong-vat-20",type:"tf",q:"Mọi loài động vật đều ăn cùng một loại thức ăn.",answer:!1,explain:"Có loài ăn thực vật, có loài ăn thịt, có loài ăn tạp."},{id:"kh4-nhu-cau-dong-vat-21",type:"mc",q:"Ngọc nuôi thỏ. Nên cho thỏ ăn gì?",emoji:"🐇",options:["Rau, cỏ sạch","Thịt sống","Cá khô","Bánh kẹo"],answer:0,explain:"Thỏ là loài ăn thực vật."},{id:"kh4-nhu-cau-dong-vat-22",type:"match",q:"Nối con vật với nơi ở thích hợp.",pairs:[["Con cá","Ao, hồ"],["Con gà","Chuồng cao ráo"],["Con vịt","Gần ao nước"]],explain:"Mỗi con vật cần nơi ở phù hợp với nhu cầu sống."},{id:"kh4-nhu-cau-dong-vat-23",type:"tf",q:"Nhiều loài động vật cần ánh sáng để nhìn, kiếm ăn và tránh kẻ thù.",answer:!0,explain:"Ánh sáng giúp nhiều loài động vật nhìn thấy để kiếm ăn, tránh nguy hiểm."},{id:"kh4-nhu-cau-dong-vat-24",type:"mc",q:"Nuôi quá nhiều cá trong một bình nhỏ, không sục khí thì điều gì dễ xảy ra?",options:["Cá lớn nhanh hơn","Cá thiếu ô-xi, dễ chết","Cá đổi màu đẹp hơn","Nước sạch hơn trước"],answer:1,explain:"Bình nhỏ, nhiều cá thì nước nhanh thiếu ô-xi."}]}],challenge:{questions:[{id:"kh4-nhu-cau-dong-vat-25",type:"multi",q:"Động vật lấy những gì từ môi trường?",options:["Khí ô-xi","Thức ăn","Nước","Khí các-bô-níc"],answers:[0,1,2],explain:"Động vật lấy thức ăn, nước, khí ô-xi và thải ra khí các-bô-níc."},{id:"kh4-nhu-cau-dong-vat-26",type:"multi",q:"Động vật thải ra môi trường những gì?",options:["Khí các-bô-níc","Khí ô-xi","Phân","Nước tiểu"],answers:[0,2,3],explain:"Động vật thải ra phân, nước tiểu, khí các-bô-níc."},{id:"kh4-nhu-cau-dong-vat-27",type:"mc",q:"So với thực vật, động vật khác ở điểm nào khi lấy chất dinh dưỡng?",options:["Động vật phải ăn thức ăn có sẵn, không tự chế tạo được","Động vật chế tạo chất dinh dưỡng từ ánh sáng","Động vật không cần chất dinh dưỡng","Động vật hút chất khoáng qua rễ"],answer:0,explain:"Chỉ thực vật tự chế tạo được chất dinh dưỡng nhờ ánh sáng."},{id:"kh4-nhu-cau-dong-vat-28",type:"tf",q:"Thiếu khí ô-xi, động vật sẽ chết nhanh hơn so với khi thiếu thức ăn.",answer:!0,explain:"Động vật chỉ chịu được thiếu ô-xi trong thời gian rất ngắn."},{id:"kh4-nhu-cau-dong-vat-29",type:"mc",q:"Trong vườn thú, cần cho hổ ăn gì?",options:["Thịt","Cỏ","Lúa","Rau"],answer:0,explain:"Hổ là loài ăn thịt."},{id:"kh4-nhu-cau-dong-vat-30",type:"match",q:"Nối nhu cầu sống với ví dụ.",pairs:[["Thức ăn","Bò gặm cỏ"],["Nước","Voi uống nước ở hồ"],["Nhiệt độ thích hợp","Chó nằm chỗ râm mát ngày hè"]],explain:"Mỗi ví dụ cho thấy một nhu cầu sống của động vật."}]},summary:["Động vật cần thức ăn, nước, không khí, ánh sáng và nhiệt độ thích hợp.","Động vật lấy thức ăn, nước, khí ô-xi và thải ra phân, nước tiểu, khí các-bô-níc.","Mỗi loài động vật có thức ăn và nơi sống khác nhau."]},{id:"kh4-cham-soc-cay",title:"Bài 18: Chăm sóc cây trồng",weeks:[21,21],learn:[{title:"Chăm sóc cây",text:"Tưới nước vừa đủ, bón phân hợp lí, đặt cây nơi có ánh sáng phù hợp, làm cỏ và xới đất cho tơi xốp.",example:"🪴 💧 🌞"},{title:"Phòng sâu bệnh",text:"Thường xuyên quan sát cây, bắt sâu, ngắt bỏ lá bị bệnh, giữ vườn sạch sẽ.",example:"🐛 ✂️"},{title:"Theo dõi cây",text:"Ghi lại sự lớn lên của cây giúp sớm biết cây thiếu nước, thiếu ánh sáng hay thiếu chất khoáng.",example:"📏 📒"}],practice:[{questions:[{id:"kh4-cham-soc-cay-01",type:"multi",q:"Những việc nào là chăm sóc cây?",options:["Bẻ cành chơi","Bón phân","Làm cỏ","Tưới nước"],answers:[1,2,3],explain:"Tưới nước, làm cỏ, bón phân giúp cây phát triển tốt."},{id:"kh4-cham-soc-cay-02",type:"mc",q:"Vì sao cần nhổ cỏ dại quanh gốc cây?",options:["Để cây trồng có thêm nhiều bóng râm","Để đất trong vườn cứng chặt lại","Để cây trồng nhận ít ánh sáng hơn","Để cỏ dại không tranh nước và chất khoáng của cây"],answer:3,explain:"Cỏ dại hút bớt nước và chất khoáng của cây trồng."},{id:"kh4-cham-soc-cay-03",type:"tf",q:"Xới đất giúp đất tơi xốp, rễ cây có không khí.",answer:!0,explain:"Đất tơi xốp có nhiều không khí, rễ phát triển tốt."},{id:"kh4-cham-soc-cay-04",type:"mc",q:"Khi thấy sâu ăn lá rau trong vườn, em có thể làm gì?",emoji:"🐛",options:["Mặc kệ","Nhổ cả cây đi","Bắt sâu và báo người lớn","Tưới thêm thật nhiều nước"],answer:2,explain:"Bắt sâu kịp thời giúp cây không bị hại."},{id:"kh4-cham-soc-cay-05",type:"fill",q:"Cây cần được tưới … vừa đủ, không quá nhiều, không quá ít.",answer:["nước"],explain:"Tưới nước vừa đủ giúp cây khỏe."},{id:"kh4-cham-soc-cay-06",type:"tf",q:"Tưới thật nhiều nước mỗi ngày luôn tốt cho mọi loại cây.",answer:!1,explain:"Tưới quá nhiều làm úng rễ; mỗi cây cần lượng nước khác nhau."},{id:"kh4-cham-soc-cay-07",type:"mc",q:"Nên tưới cây vào lúc nào trong ngày?",options:["Sáng sớm hoặc chiều mát","Giữa trưa nắng gắt","Lúc nắng to nhất","Bất kì lúc nào trời nóng nhất"],answer:0,explain:"Tưới lúc mát, nước ít bay hơi, cây hút được nhiều hơn."},{id:"kh4-cham-soc-cay-08",type:"mc",q:"Chậu hoa để trong nhà nên đặt ở đâu?",options:["Trong tủ đóng kín","Dưới gầm giường tối","Gần cửa sổ có ánh sáng","Trong nhà kho tối"],answer:2,explain:"Cây cần ánh sáng để sống."}]},{questions:[{id:"kh4-cham-soc-cay-09",type:"match",q:"Nối việc làm với tác dụng.",pairs:[["Tưới nước","Cung cấp nước cho cây"],["Bón phân","Cung cấp chất khoáng"],["Xới đất","Giúp đất tơi xốp"]],explain:"Mỗi việc chăm sóc đáp ứng một nhu cầu của cây."},{id:"kh4-cham-soc-cay-10",type:"mc",q:"Vì sao không nên tưới cây vào giữa trưa nắng gắt?",options:["Vì nước bay hơi nhanh, cây khó hút được nhiều","Vì giữa trưa cây không cần nước","Vì nước làm cây nóng lên","Vì giữa trưa đất không thấm nước"],answer:0,explain:"Tưới lúc nắng gắt, nước bay hơi nhanh nên phí nước."},{id:"kh4-cham-soc-cay-11",type:"tf",q:"Bón quá nhiều phân có thể làm cây bị hại.",answer:!0,explain:"Bón phân cần vừa đủ, đúng cách."},{id:"kh4-cham-soc-cay-12",type:"multi",q:"Dấu hiệu nào cho thấy cây cần được tưới?",options:["Đất khô","Đất ẩm ướt","Lá xanh tươi","Lá héo rũ"],answers:[0,3],explain:"Đất khô, lá héo là dấu hiệu cây thiếu nước."},{id:"kh4-cham-soc-cay-13",type:"mc",q:"Vì sao cần ngắt bỏ lá bị bệnh?",options:["Để cây có nhiều lá hơn","Để cây cao nhanh hơn","Để cây ra hoa ngay","Để bệnh không lây sang lá khác"],answer:3,explain:"Ngắt bỏ lá bệnh giúp hạn chế bệnh lây lan."},{id:"kh4-cham-soc-cay-14",type:"tf",q:"Cây lớn lên vẫn nên để mãi trong chậu thật nhỏ.",answer:!1,explain:"Khi cây lớn, chậu to hơn có thêm đất cho rễ phát triển."},{id:"kh4-cham-soc-cay-15",type:"mc",q:"Vì sao khi trồng rau cần để khoảng cách giữa các cây?",options:["Để mỗi cây đủ chỗ, đủ ánh sáng và chất dinh dưỡng","Để mảnh vườn trông thật trống trải","Để cỏ dại có chỗ mọc nhiều hơn","Để trồng được ít cây hơn trên luống"],answer:0,explain:"Cây trồng quá dày sẽ tranh nhau ánh sáng và chất dinh dưỡng."},{id:"kh4-cham-soc-cay-16",type:"mc",q:"Cây con mới trồng gặp nắng gắt cần được làm gì?",options:["Nhổ cây lên phơi nắng","Không tưới nước nữa","Che bớt nắng và tưới nước","Bón thật nhiều phân"],answer:2,explain:"Cây con còn yếu nên cần che nắng và đủ nước."}]},{questions:[{id:"kh4-cham-soc-cay-17",type:"order",q:"Sắp xếp các bước trồng cây con vào chậu.",items:["Cho đất tơi xốp vào chậu","Đào một hố nhỏ giữa chậu","Đặt cây con vào, lấp đất và nén nhẹ","Tưới nước vừa đủ"],explain:"Chuẩn bị đất, trồng cây rồi tưới nước."},{id:"kh4-cham-soc-cay-18",type:"mc",q:"Chậu cây của Vy có lá vàng, đất lúc nào cũng sũng nước. Vy nên làm gì?",options:["Tưới thêm nhiều nước","Cất vào tủ tối","Bón thêm thật nhiều phân","Tưới ít lại và cho chậu thoát nước tốt"],answer:3,explain:"Đất sũng nước làm rễ thiếu không khí, cây vàng lá."},{id:"kh4-cham-soc-cay-19",type:"multi",q:"Nhóm em trồng rau ở vườn trường. Những việc nào cần làm thường xuyên?",options:["Nhổ cỏ dại","Nhổ cây lên xem rễ mỗi ngày","Đổ nước xà phòng vào gốc","Quan sát và tưới nước khi đất khô"],answers:[0,3],explain:"Quan sát, tưới nước, nhổ cỏ giúp rau phát triển tốt."},{id:"kh4-cham-soc-cay-20",type:"tf",q:"Ghi chép chiều cao của cây mỗi tuần giúp biết cây lớn nhanh hay chậm.",answer:!0,explain:"Ghi chép đều đặn giúp theo dõi và chăm sóc cây kịp thời."},{id:"kh4-cham-soc-cay-21",type:"number",q:"Tuần trước cây đậu cao 8 cm, tuần này cao 13 cm. Cây đã cao thêm bao nhiêu xăng-ti-mét?",answer:5,unit:"cm",explain:"Cây cao thêm 13 − 8 = 5 cm."},{id:"kh4-cham-soc-cay-22",type:"mc",q:"Cây trong chậu ở góc tối có thân vươn dài, lá nhợt nhạt. Cây thiếu gì?",options:["Ánh sáng","Nước","Không khí","Đất"],answer:0,explain:"Thiếu ánh sáng, cây vươn dài tìm ánh sáng và lá nhợt nhạt."},{id:"kh4-cham-soc-cay-23",type:"match",q:"Nối vấn đề của cây với cách xử lí.",pairs:[["Đất khô, lá héo","Tưới nước"],["Cây còi cọc, lá nhỏ","Bón phân hợp lí"],["Có sâu ăn lá","Bắt sâu"]],explain:"Tìm đúng nguyên nhân để chăm sóc đúng cách."},{id:"kh4-cham-soc-cay-24",type:"tf",q:"Có thể đổ nước rửa bát có xà phòng vào gốc cây thay cho phân bón.",answer:!1,explain:"Nước xà phòng có thể làm hại cây, không thay được phân bón."}]}],challenge:{questions:[{id:"kh4-cham-soc-cay-25",type:"mc",q:"Hai chậu cây giống nhau: chậu A tưới vừa đủ, chậu B lúc nào cũng ngập nước. Sau hai tuần, chậu nào dễ bị thối rễ?",options:["Chậu B","Chậu A","Cả hai như nhau","Không chậu nào"],answer:0,explain:"Ngập nước lâu, rễ thiếu không khí và dễ thối."},{id:"kh4-cham-soc-cay-26",type:"order",q:"Sắp xếp việc theo dõi sự lớn lên của cây đậu.",items:["Gieo hạt đậu vào chậu đất ẩm","Ghi lại ngày hạt nảy mầm","Đo chiều cao cây mỗi tuần","Ghi kết quả vào bảng và nhận xét"],explain:"Gieo hạt, theo dõi, đo rồi ghi chép và nhận xét."},{id:"kh4-cham-soc-cay-27",type:"multi",q:"Những cách nào giúp cây ít bị sâu bệnh?",options:["Giữ vườn sạch cỏ","Ngắt bỏ lá bị bệnh","Để lá úa, rác mục đầy gốc cây","Thường xuyên quan sát, bắt sâu"],answers:[0,1,3],explain:"Vườn sạch, theo dõi thường xuyên giúp hạn chế sâu bệnh."},{id:"kh4-cham-soc-cay-28",type:"number",q:"Một luống rau cần tưới 3 bình nước mỗi ngày. Trong 5 ngày cần tưới bao nhiêu bình nước?",answer:15,unit:"bình",explain:"Số bình nước cần là 3 × 5 = 15 bình."},{id:"kh4-cham-soc-cay-29",type:"mc",q:"Vì sao trước khi trồng cây, người ta thường cày, xới đất?",options:["Để đất cứng hơn","Để đất hết chất khoáng","Để cỏ dại mọc nhanh","Để đất tơi xốp, có không khí, rễ dễ phát triển"],answer:3,explain:"Đất tơi xốp giúp rễ có không khí và dễ đâm sâu."},{id:"kh4-cham-soc-cay-30",type:"tf",q:"Mỗi loại cây cần cách chăm sóc khác nhau về nước và ánh sáng.",answer:!0,explain:"Cần tìm hiểu nhu cầu của từng loại cây để chăm sóc đúng."}]},summary:["Chăm sóc cây: tưới nước vừa đủ, bón phân hợp lí, đủ ánh sáng, làm cỏ, xới đất.","Thường xuyên quan sát, bắt sâu, ngắt lá bệnh.","Theo dõi và ghi chép giúp chăm sóc cây kịp thời."]},{id:"kh4-cham-soc-vat-nuoi",title:"Bài 19: Chăm sóc vật nuôi",weeks:[22,22],learn:[{title:"Chăm sóc vật nuôi",text:"Cho vật nuôi ăn thức ăn phù hợp, uống nước sạch; giữ chuồng trại sạch sẽ, thoáng mát mùa hè, ấm áp mùa đông.",example:"🐕 🐈 🐔"},{title:"Phòng bệnh",text:"Tiêm phòng cho vật nuôi theo hướng dẫn của cán bộ thú y. Tách riêng con vật bị ốm.",example:"💉"},{title:"An toàn và yêu thương",text:"Không đánh đập, trêu chọc vật nuôi. Rửa tay bằng xà phòng sau khi chăm sóc vật nuôi.",example:"🧼 ❤️"}],practice:[{questions:[{id:"kh4-cham-soc-vat-nuoi-01",type:"multi",q:"Việc nào là chăm sóc vật nuôi?",options:["Cho ăn đúng bữa","Trêu chọc con vật","Cho uống nước sạch","Dọn chuồng sạch sẽ"],answers:[0,2,3],explain:"Cho ăn, uống và giữ chuồng sạch là chăm sóc vật nuôi."},{id:"kh4-cham-soc-vat-nuoi-02",type:"tf",q:"Cần rửa tay bằng xà phòng sau khi chăm sóc vật nuôi.",emoji:"🧼",answer:!0,explain:"Rửa tay giúp tránh vi khuẩn từ vật nuôi."},{id:"kh4-cham-soc-vat-nuoi-03",type:"mc",q:"Mùa đông giá rét, chuồng trại cần làm gì?",options:["Che chắn cho ấm","Mở toang cho gió lùa","Dội nước lạnh","Dỡ mái chuồng"],answer:0,explain:"Vật nuôi cần được giữ ấm khi trời rét."},{id:"kh4-cham-soc-vat-nuoi-04",type:"mc",q:"Chó, mèo cần được tiêm phòng bệnh nào để bảo vệ cả con người?",options:["Bệnh dại","Bệnh sâu răng","Bệnh cận thị","Bệnh đau mắt do đọc sách"],answer:0,explain:"Tiêm phòng dại cho chó, mèo giúp phòng bệnh dại lây sang người."},{id:"kh4-cham-soc-vat-nuoi-05",type:"fill",q:"Vật nuôi cần được uống nước … hằng ngày.",answer:["sạch"],explain:"Nước sạch giúp vật nuôi khỏe mạnh."},{id:"kh4-cham-soc-vat-nuoi-06",type:"tf",q:"Có thể cho vật nuôi ăn thức ăn ôi thiu.",answer:!1,explain:"Thức ăn ôi thiu làm vật nuôi bị bệnh."},{id:"kh4-cham-soc-vat-nuoi-07",type:"mc",q:"Mùa hè, chuồng trại nên thế nào?",options:["Đóng kín, bí hơi","Phơi dưới nắng gắt","Thoáng mát","Ẩm ướt"],answer:2,explain:"Chuồng thoáng mát giúp vật nuôi dễ chịu khi trời nóng."},{id:"kh4-cham-soc-vat-nuoi-08",type:"mc",q:"Khi bị chó, mèo cắn hoặc cào, em cần làm gì?",options:["Rửa vết thương bằng xà phòng và nước sạch, báo người lớn ngay","Giấu đi, không nói cho bố mẹ biết","Bôi đất hoặc lá cây vào vết thương","Đánh lại con vật cho nó sợ"],answer:0,explain:"Rửa sạch vết thương và báo người lớn để được đưa đi khám kịp thời."}]},{questions:[{id:"kh4-cham-soc-vat-nuoi-09",type:"match",q:"Nối vật nuôi với thức ăn phù hợp.",pairs:[["Con trâu","Cỏ, rơm"],["Con gà","Thóc, ngô"],["Con thỏ","Rau, cỏ"]],explain:"Mỗi con vật cần thức ăn phù hợp."},{id:"kh4-cham-soc-vat-nuoi-10",type:"mc",q:"Vì sao phải dọn chuồng vật nuôi thường xuyên?",options:["Để vật nuôi ít bị bệnh và chuồng không hôi","Để vật nuôi ăn ít đi mỗi ngày","Để chuồng trại rộng rãi hơn","Để vật nuôi ngủ được nhiều hơn"],answer:0,explain:"Chuồng sạch giúp vật nuôi khỏe và giữ vệ sinh môi trường."},{id:"kh4-cham-soc-vat-nuoi-11",type:"tf",q:"Con vật bị ốm nên được tách riêng để tránh lây bệnh cho con khác.",answer:!0,explain:"Tách riêng con ốm giúp bệnh không lây lan."},{id:"kh4-cham-soc-vat-nuoi-12",type:"multi",q:"Dấu hiệu nào cho thấy vật nuôi có thể bị ốm?",options:["Bỏ ăn","Ăn ngon, chạy nhảy","Lông mượt, mắt sáng","Nằm lì, mệt mỏi"],answers:[0,3],explain:"Bỏ ăn, mệt mỏi là dấu hiệu vật nuôi có thể bị ốm."},{id:"kh4-cham-soc-vat-nuoi-13",type:"mc",q:"Vì sao nên tiêm phòng cho vật nuôi?",options:["Để vật nuôi lớn gấp đôi ngay","Để vật nuôi ít bị bệnh","Để vật nuôi không cần ăn","Để vật nuôi đổi màu lông"],answer:1,explain:"Tiêm phòng giúp vật nuôi phòng một số bệnh."},{id:"kh4-cham-soc-vat-nuoi-14",type:"tf",q:"Đánh đập vật nuôi giúp chúng ngoan hơn.",answer:!1,explain:"Cần đối xử nhẹ nhàng, yêu thương vật nuôi."},{id:"kh4-cham-soc-vat-nuoi-15",type:"mc",q:"Vì sao không nên cho chó, mèo ăn bánh kẹo của người?",options:["Vì chó, mèo không biết nhai bánh","Vì không phù hợp, có thể làm chúng bị bệnh","Vì bánh kẹo của người quá rẻ","Vì chó, mèo không thích vị ngọt"],answer:1,explain:"Vật nuôi cần thức ăn phù hợp với loài."},{id:"kh4-cham-soc-vat-nuoi-16",type:"mc",q:"Chuồng gà nên đặt ở đâu?",options:["Nơi cao ráo, thoáng, cách xa nhà ở","Trong phòng ngủ","Cạnh bếp nấu ăn","Chỗ trũng, ngập nước"],answer:0,explain:"Chuồng cao ráo, thoáng và xa nhà ở giúp gà khỏe và giữ vệ sinh."}]},{questions:[{id:"kh4-cham-soc-vat-nuoi-17",type:"order",q:"Sắp xếp các bước dọn chuồng thỏ.",items:["Đeo găng tay và khẩu trang","Đưa thỏ ra chỗ an toàn","Quét dọn, rửa sạch chuồng","Để chuồng khô rồi cho thỏ vào","Rửa tay bằng xà phòng"],explain:"Bảo vệ bản thân, dọn sạch chuồng, rồi rửa tay sau khi làm."},{id:"kh4-cham-soc-vat-nuoi-18",type:"mc",q:"Chú chó nhà Tùng bỏ ăn hai ngày. Tùng nên làm gì?",options:["Báo bố mẹ để đưa chó đi khám thú y","Mặc kệ, vài hôm sẽ khỏi","Ép chó ăn thật nhiều","Nhốt chó vào phòng tối"],answer:0,explain:"Bỏ ăn lâu là dấu hiệu bệnh, cần được thú y khám."},{id:"kh4-cham-soc-vat-nuoi-19",type:"multi",q:"Những việc nào thể hiện yêu thương vật nuôi?",options:["Để chó ngoài trời mưa rét","Kéo đuôi mèo","Cho ăn đúng bữa","Vuốt ve nhẹ nhàng"],answers:[2,3],explain:"Chăm sóc chu đáo, nhẹ nhàng là yêu thương vật nuôi."},{id:"kh4-cham-soc-vat-nuoi-20",type:"tf",q:"Rửa sạch máng ăn, máng uống giúp vật nuôi khỏe mạnh.",answer:!0,explain:"Máng sạch giúp vật nuôi tránh vi khuẩn gây bệnh."},{id:"kh4-cham-soc-vat-nuoi-21",type:"mc",q:"Trời rét đậm, nhà Khoa có trâu. Nên làm gì?",options:["Thả trâu ngoài đồng cả đêm","Tắm nước lạnh cho trâu","Che chắn chuồng, giữ ấm cho trâu","Không cho trâu ăn"],answer:2,explain:"Trời rét đậm, trâu cần được giữ ấm và cho ăn đủ."},{id:"kh4-cham-soc-vat-nuoi-22",type:"mc",q:"Vì sao không nên cho vật nuôi uống nước ao tù bẩn?",options:["Vì vật nuôi dễ bị bệnh","Vì nước ao quá ngọt","Vì vật nuôi sẽ lớn quá nhanh","Vì nước ao quá trong"],answer:0,explain:"Nước bẩn có vi khuẩn gây bệnh."},{id:"kh4-cham-soc-vat-nuoi-23",type:"match",q:"Nối việc làm với lợi ích.",pairs:[["Tiêm phòng","Phòng bệnh"],["Dọn chuồng sạch","Giảm mùi hôi, ít ruồi muỗi"],["Cho ăn đủ chất","Vật nuôi lớn nhanh, khỏe mạnh"]],explain:"Mỗi việc chăm sóc mang lại một lợi ích."},{id:"kh4-cham-soc-vat-nuoi-24",type:"tf",q:"Chơi với chó, mèo lạ lúc nào cũng an toàn vì con vật nào cũng hiền.",answer:!1,explain:"Chó, mèo lạ có thể cắn, cào; không nên tự ý trêu chọc."}]}],challenge:{questions:[{id:"kh4-cham-soc-vat-nuoi-25",type:"mc",q:"Vì sao chuồng trại nên đặt xa giếng nước?",options:["Để vật nuôi không uống được nước giếng","Để giếng nước nhận được nhiều nắng hơn","Để phân, nước thải không làm bẩn nước giếng","Để chuồng trại có chỗ rộng rãi hơn"],answer:2,explain:"Chất thải vật nuôi có thể thấm vào đất làm bẩn nước giếng."},{id:"kh4-cham-soc-vat-nuoi-26",type:"multi",q:"Khi nuôi vật nuôi, những việc nào giúp bảo vệ sức khỏe con người?",options:["Ăn uống trong chuồng","Tiêm phòng dại cho chó, mèo","Ôm hôn vật nuôi đang ốm","Rửa tay sau khi chăm sóc"],answers:[1,3],explain:"Vệ sinh và tiêm phòng giúp bảo vệ cả người và vật nuôi."},{id:"kh4-cham-soc-vat-nuoi-27",type:"number",q:"Mỗi con gà ăn 1 nắm thóc mỗi bữa, mỗi ngày 2 bữa. Nhà Lan có 6 con gà. Mỗi ngày cần bao nhiêu nắm thóc?",answer:12,unit:"nắm",explain:"Số nắm thóc cần là 6 × 2 = 12 nắm."},{id:"kh4-cham-soc-vat-nuoi-28",type:"tf",q:"Vật nuôi chết vì bệnh không được vứt xuống ao, sông.",answer:!0,explain:"Xác vật nuôi bị bệnh làm ô nhiễm nước và lây bệnh, cần xử lí theo hướng dẫn."},{id:"kh4-cham-soc-vat-nuoi-29",type:"mc",q:"Thỏ nhà Vy bị đau bụng sau khi ăn rau bẩn còn ướt. Lần sau Vy nên làm gì?",options:["Cho thỏ ăn rau bẩn hơn","Cho thỏ ăn rau sạch, đã để ráo nước","Không cho thỏ ăn nữa","Cho thỏ ăn bánh kẹo"],answer:1,explain:"Thức ăn sạch, phù hợp giúp thỏ khỏe mạnh."},{id:"kh4-cham-soc-vat-nuoi-30",type:"match",q:"Nối dấu hiệu với cách xử lí.",pairs:[["Vật nuôi bỏ ăn, mệt mỏi","Báo người lớn, đưa đi khám"],["Chuồng có mùi hôi","Dọn rửa chuồng"],["Máng nước bẩn","Thay nước sạch"]],explain:"Phát hiện sớm và xử lí kịp thời giúp vật nuôi khỏe."}]},summary:["Cho vật nuôi ăn uống đủ, sạch; giữ chuồng trại sạch, thoáng, ấm.","Tiêm phòng, tách riêng con ốm, báo người lớn khi vật nuôi có dấu hiệu bệnh.","Yêu thương vật nuôi và rửa tay sau khi chăm sóc chúng."]}]},{id:"nam",title:"Nấm",lessons:[{id:"kh4-nam-an",title:"Bài 20: Đặc điểm của nấm. Nấm ăn",weeks:[23,23],learn:[{title:"Nấm ở quanh ta",text:"Nấm có nhiều hình dạng, màu sắc, kích thước khác nhau. Nấm thường sống ở nơi ẩm ướt như đất ẩm, rơm rạ mục, thân gỗ mục, thức ăn để lâu.",example:"🍄"},{title:"Nấm khác cây xanh",text:"Nhiều loại nấm có mũ nấm và thân nấm. Nấm không tự chế tạo chất dinh dưỡng nhờ ánh sáng như cây xanh.",example:"🍄 ≠ 🌱"},{title:"Nấm ăn",text:"Nhiều loại nấm ăn được như nấm rơm, nấm hương, nấm kim châm, nấm sò, mộc nhĩ. Nấm ăn thơm ngon, bổ dưỡng.",example:"🍲"}],practice:[{questions:[{id:"kh4-nam-an-01",type:"multi",q:"Những loại nấm nào ăn được?",options:["Nấm rơm","Nấm hương","Mộc nhĩ","Nấm lạ mọc dại trong rừng"],answers:[0,1,2],explain:"Nấm rơm, nấm hương, mộc nhĩ là nấm ăn; nấm lạ mọc dại có thể là nấm độc."},{id:"kh4-nam-an-02",type:"mc",q:"Nấm thường mọc ở đâu?",options:["Trên bãi cát khô ngoài nắng gắt","Trên mặt tấm kính khô ráo","Nơi ẩm ướt như rơm rạ mục, thân gỗ mục","Trong bếp lửa đang cháy to"],answer:2,explain:"Nấm ưa nơi ẩm ướt, có chất dinh dưỡng."},{id:"kh4-nam-an-03",type:"tf",q:"Nấm có nhiều hình dạng và màu sắc khác nhau.",answer:!0,explain:"Có nấm hình chiếc ô, có nấm hình tai, có nấm rất nhỏ."},{id:"kh4-nam-an-04",type:"mc",q:"Phần hình chiếc ô ở trên cùng của cây nấm gọi là gì?",emoji:"🍄",options:["Chân nấm","Rễ nấm","Lá nấm","Mũ nấm"],answer:3,explain:"Phần hình chiếc ô là mũ nấm."},{id:"kh4-nam-an-05",type:"fill",q:"Mộc nhĩ, nấm hương, nấm rơm là những loại nấm … được.",answer:["ăn"],explain:"Đó là các loại nấm ăn được, thường dùng làm thức ăn."},{id:"kh4-nam-an-06",type:"tf",q:"Nấm ăn là thức ăn ngon và bổ dưỡng.",answer:!0,explain:"Nấm ăn được dùng nấu nhiều món ngon, bổ."},{id:"kh4-nam-an-07",type:"mc",q:"Nấm rơm thường được trồng trên gì?",options:["Đá cuội","Cát khô","Rơm rạ","Tấm sắt"],answer:2,explain:"Đúng như tên gọi, nấm rơm mọc trên rơm rạ ẩm."},{id:"kh4-nam-an-08",type:"tf",q:"Nấm tự chế tạo chất dinh dưỡng nhờ ánh sáng giống như cây xanh.",answer:!1,explain:"Nấm không chế tạo chất dinh dưỡng nhờ ánh sáng; nấm lấy chất dinh dưỡng từ nơi nó sống."}]},{questions:[{id:"kh4-nam-an-09",type:"match",q:"Nối loại nấm với đặc điểm.",pairs:[["Nấm rơm","Mọc trên rơm rạ"],["Mộc nhĩ","Màu nâu sẫm, hình như cái tai"],["Nấm kim châm","Thân dài, mảnh, màu trắng"]],explain:"Mỗi loại nấm ăn có hình dạng riêng."},{id:"kh4-nam-an-10",type:"mc",q:"Vì sao nấm thường mọc nhiều vào mùa mưa?",options:["Vì trời nắng gắt","Vì trời khô hanh","Vì trời ẩm ướt","Vì trời có gió mùa khô"],answer:2,explain:"Nấm phát triển mạnh ở nơi ẩm ướt."},{id:"kh4-nam-an-11",type:"multi",q:"Nấm có thể sống ở những nơi nào?",options:["Thân gỗ mục","Thức ăn để lâu","Lò nướng đang nóng","Đất ẩm"],answers:[0,1,3],explain:"Nấm sống ở nơi ẩm, có chất dinh dưỡng."},{id:"kh4-nam-an-12",type:"mc",q:"Nấm lấy chất dinh dưỡng từ đâu?",options:["Từ nơi nấm mọc như rơm rạ, gỗ mục, thức ăn","Từ ánh sáng Mặt Trời giống cây xanh","Từ những viên đá cuội ở quanh nấm","Từ không khí khô ráo xung quanh"],answer:0,explain:"Nấm lấy chất dinh dưỡng từ vật mà nó mọc trên đó."},{id:"kh4-nam-an-13",type:"tf",q:"Nấm hương không thể phơi khô để dùng lâu.",answer:!1,explain:"Nấm hương thường được phơi khô để để được lâu."},{id:"kh4-nam-an-14",type:"mc",q:"Vì sao nên mua nấm ăn ở nơi có nguồn gốc rõ ràng?",options:["Để nấm rẻ hơn","Để tránh nhầm với nấm độc","Để nấm to hơn","Để nấm có nhiều màu"],answer:1,explain:"Nấm rõ nguồn gốc là nấm trồng, an toàn khi ăn."},{id:"kh4-nam-an-15",type:"tf",q:"Mọi cây nấm có màu trắng đều ăn được.",answer:!1,explain:"Có những loại nấm độc màu trắng; không thể dựa vào màu để biết nấm ăn được."},{id:"kh4-nam-an-16",type:"mc",q:"Kích thước của các loại nấm thế nào?",options:["Có loại to, có loại rất nhỏ phải dùng kính hiển vi mới thấy","Loại nấm nào cũng to bằng cái bát ăn cơm","Loại nấm nào cũng to bằng nhau","Loại nấm nào cũng dài như một cái cây"],answer:0,explain:"Nấm có nhiều kích thước, có loại rất nhỏ."}]},{questions:[{id:"kh4-nam-an-17",type:"order",q:"Sắp xếp các bước quan sát một cây nấm rơm.",items:["Đặt cây nấm lên đĩa sạch","Dùng kính lúp quan sát các bộ phận","Vẽ lại và ghi tên các bộ phận","Rửa tay sau khi quan sát"],explain:"Quan sát, ghi chép rồi rửa tay sạch sẽ."},{id:"kh4-nam-an-18",type:"mc",q:"Mẹ mua nấm hương khô. Trước khi nấu cần làm gì?",options:["Nấu ngay không cần rửa","Phơi thêm nắng","Để vào ngăn đá","Ngâm nước cho nở rồi rửa sạch"],answer:3,explain:"Nấm khô cần ngâm cho nở mềm và rửa sạch trước khi nấu."},{id:"kh4-nam-an-19",type:"multi",q:"Muốn trồng nấm rơm, cần những điều kiện nào?",options:["Nắng gắt cả ngày","Độ ẩm thích hợp","Có rơm rạ","Đất cát khô cằn"],answers:[1,2],explain:"Nấm rơm cần rơm rạ và độ ẩm thích hợp."},{id:"kh4-nam-an-20",type:"tf",q:"Thấy nấm lạ mọc trong vườn, có thể hái về nấu nếu trông giống nấm ở chợ.",answer:!1,explain:"Nhiều nấm độc trông giống nấm ăn; không được hái nấm lạ."},{id:"kh4-nam-an-21",type:"mc",q:"Vì sao đống rơm rạ để ẩm lâu ngày thường mọc nấm?",options:["Vì rơm rạ chính là hạt giống của nấm","Vì đống rơm rạ luôn khô và nóng","Vì nắng chiếu nhiều vào đống rơm","Vì nấm ưa ẩm và lấy chất dinh dưỡng từ rơm"],answer:3,explain:"Rơm ẩm là nơi thích hợp cho nấm phát triển."},{id:"kh4-nam-an-22",type:"mc",q:"Mộc nhĩ còn được gọi là gì?",options:["Nấm rơm","Nấm kim châm","Nấm hương","Nấm mèo"],answer:3,explain:"Mộc nhĩ còn được gọi là nấm mèo."},{id:"kh4-nam-an-23",type:"multi",q:"Những món ăn nào có dùng nấm ăn?",options:["Nấm xào rau","Cơm trắng","Nước chanh","Canh nấm"],answers:[0,3],explain:"Nấm ăn dùng để nấu canh, xào."},{id:"kh4-nam-an-24",type:"number",q:"Một bịch nấm rơm có 25 cây nấm. Mẹ mua 3 bịch. Mẹ có bao nhiêu cây nấm?",answer:75,unit:"cây",explain:"Số cây nấm là 25 × 3 = 75 cây."}]}],challenge:{questions:[{id:"kh4-nam-an-25",type:"mc",q:"Điểm nào giúp phân biệt nấm với cây xanh?",options:["Nấm cần nhiều ánh sáng hơn cây xanh","Nấm có lá to và xanh hơn cây","Nấm có hoa và quả giống như cây","Nấm không tự chế tạo chất dinh dưỡng nhờ ánh sáng"],answer:3,explain:"Cây xanh chế tạo chất dinh dưỡng nhờ ánh sáng, nấm thì không."},{id:"kh4-nam-an-26",type:"multi",q:"Những điều kiện nào giúp nấm phát triển?",options:["Khô ráo, nắng gắt","Có chất dinh dưỡng như rơm, gỗ mục","Ẩm ướt"],answers:[1,2],explain:"Nấm cần ẩm và chất dinh dưỡng."},{id:"kh4-nam-an-27",type:"tf",q:"Có loại nấm rất nhỏ, mắt thường không nhìn thấy được.",answer:!0,explain:"Ví dụ nấm men rất nhỏ, phải dùng kính hiển vi mới thấy."},{id:"kh4-nam-an-28",type:"match",q:"Nối loại nấm với nơi thường mọc.",pairs:[["Nấm rơm","Đống rơm rạ ẩm"],["Mộc nhĩ","Thân gỗ mục"],["Mốc xanh, mốc trắng","Bánh mì để lâu"]],explain:"Mỗi loại nấm có nơi mọc quen thuộc."},{id:"kh4-nam-an-29",type:"mc",q:"Vì sao không nên tự hái nấm dại về ăn?",options:["Vì nấm dại không có mùi","Vì nấm dại quá nhỏ","Vì nấm dại rất đắt","Vì nhiều nấm độc trông giống nấm ăn"],answer:3,explain:"Rất khó phân biệt nấm độc với nấm ăn bằng mắt."},{id:"kh4-nam-an-30",type:"mc",q:"Vườn trường có khúc gỗ mục để ở chỗ ẩm. Sau mùa mưa, điều gì dễ xảy ra?",options:["Khúc gỗ nảy mầm thành cây","Khúc gỗ biến thành đá","Nấm mọc trên khúc gỗ","Khúc gỗ khô cứng hơn"],answer:2,explain:"Gỗ mục, ẩm là nơi thích hợp cho nấm mọc."}]},summary:["Nấm có nhiều hình dạng, màu sắc, kích thước; thường sống nơi ẩm ướt.","Nấm không tự chế tạo chất dinh dưỡng nhờ ánh sáng như cây xanh.","Nhiều loại nấm ăn được như nấm rơm, nấm hương, mộc nhĩ."]},{id:"kh4-nam-men-nam-moc",title:"Bài 21: Nấm men và nấm mốc",weeks:[24,24],learn:[{title:"Nấm men",text:"Nấm men rất nhỏ. Người ta dùng nấm men để làm bánh mì, bánh bao; nấm men làm bột nở, bánh mềm và xốp.",example:"🍞 🥟"},{title:"Nấm mốc",text:"Nấm mốc mọc trên thức ăn, đồ vật để nơi ẩm, ấm. Nấm mốc làm hỏng thức ăn; thức ăn bị mốc thì không được ăn.",example:"🍞 🟢"},{title:"Bảo quản thức ăn",text:"Để thức ăn nơi sạch, khô ráo; làm lạnh, phơi khô, ướp muối hoặc đóng hộp để hạn chế nấm mốc.",example:"🧊 ☀️ 🧂 🥫"}],practice:[{questions:[{id:"kh4-nam-men-nam-moc-01",type:"mc",q:"Người ta dùng nấm men để làm gì?",emoji:"🍞",options:["Làm muối","Làm bánh mì","Làm đường phèn","Làm nước đá"],answer:1,explain:"Nấm men làm bột bánh mì nở xốp."},{id:"kh4-nam-men-nam-moc-02",type:"tf",q:"Thức ăn bị mốc vẫn ăn được sau khi cạo bỏ chỗ mốc.",answer:!1,explain:"Nấm mốc có thể lan sâu vào thức ăn; thức ăn mốc phải bỏ đi."},{id:"kh4-nam-men-nam-moc-03",type:"mc",q:"Nấm mốc dễ phát triển ở nơi nào?",options:["Nơi khô ráo, lạnh giá","Nơi ẩm và ấm","Trong ngăn đá tủ lạnh","Ngoài nắng gắt"],answer:1,explain:"Ẩm và ấm là điều kiện thuận lợi cho nấm mốc."},{id:"kh4-nam-men-nam-moc-04",type:"multi",q:"Những cách nào giúp bảo quản thức ăn, hạn chế nấm mốc?",options:["Làm lạnh","Phơi khô","Ướp muối","Để thức ăn nơi ẩm ướt"],answers:[0,1,2],explain:"Làm lạnh, phơi khô, ướp muối làm nấm mốc khó phát triển."},{id:"kh4-nam-men-nam-moc-05",type:"fill",q:"Nấm … làm cho bột bánh mì nở xốp.",answer:["men"],explain:"Nấm men làm bột bánh nở."},{id:"kh4-nam-men-nam-moc-06",type:"tf",q:"Bánh mì để lâu nơi ẩm không bao giờ bị mốc.",answer:!1,explain:"Bánh mì để lâu nơi ẩm rất dễ bị nấm mốc."},{id:"kh4-nam-men-nam-moc-07",type:"mc",q:"Dấu hiệu nào cho thấy thức ăn đã bị mốc?",options:["Có lớp như lông tơ màu trắng, xanh hoặc đen","Thức ăn thơm ngon hơn lúc đầu","Thức ăn sáng bóng, tươi mới","Thức ăn tự nóng lên"],answer:0,explain:"Nấm mốc thường trông như lớp lông tơ có màu."},{id:"kh4-nam-men-nam-moc-08",type:"mc",q:"Nấm men có kích thước thế nào?",options:["To như một cây nấm rơm","To bằng một quả cam","Dài như một sợi dây","Rất nhỏ, phải dùng kính hiển vi mới thấy rõ"],answer:3,explain:"Nấm men rất nhỏ, mắt thường không thấy từng con."}]},{questions:[{id:"kh4-nam-men-nam-moc-09",type:"match",q:"Nối cách bảo quản với thức ăn.",pairs:[["Phơi khô","Cá khô, mực khô"],["Làm lạnh","Thịt tươi, rau"],["Đóng hộp","Cá hộp, thịt hộp"]],explain:"Mỗi loại thức ăn có cách bảo quản phù hợp."},{id:"kh4-nam-men-nam-moc-10",type:"mc",q:"Vì sao bánh mì làm có nấm men thì mềm và xốp?",options:["Vì nấm men làm bánh cứng lại","Vì nấm men làm bánh mặn","Vì nấm men làm bột tan ra","Vì nấm men tạo ra khí làm bột nở"],answer:3,explain:"Khí do nấm men tạo ra làm bột phồng lên, bánh xốp."},{id:"kh4-nam-men-nam-moc-11",type:"tf",q:"Quần áo, giày dép để nơi ẩm lâu ngày cũng có thể bị mốc.",answer:!0,explain:"Nấm mốc mọc được trên nhiều đồ vật để nơi ẩm."},{id:"kh4-nam-men-nam-moc-12",type:"multi",q:"Vì sao không được ăn thức ăn bị mốc?",options:["Vì thức ăn mốc quá thơm","Có thể gây đau bụng","Có thể gây ngộ độc"],answers:[1,2],explain:"Thức ăn mốc có thể chứa chất độc gây hại."},{id:"kh4-nam-men-nam-moc-13",type:"mc",q:"Vì sao để thức ăn trong tủ lạnh giúp lâu hỏng hơn?",options:["Vì nhiệt độ thấp làm nấm mốc, vi khuẩn chậm phát triển","Vì trong tủ lạnh luôn có ánh sáng","Vì tủ lạnh làm thức ăn to ra","Vì tủ lạnh có nhiều không khí ẩm"],answer:0,explain:"Lạnh làm nấm mốc và vi khuẩn phát triển chậm."},{id:"kh4-nam-men-nam-moc-14",type:"tf",q:"Một số loại nấm mốc được dùng để làm tương.",answer:!0,explain:"Khi làm tương, người ta dùng một loại nấm mốc có ích."},{id:"kh4-nam-men-nam-moc-15",type:"mc",q:"Lạc bị mốc thì xử lí thế nào?",emoji:"🥜",options:["Rang lên rồi ăn","Bỏ đi, không ăn","Rửa sạch rồi ăn","Trộn với lạc tốt"],answer:1,explain:"Lạc mốc có chất độc, rang hay rửa cũng không hết."},{id:"kh4-nam-men-nam-moc-16",type:"mc",q:"Nấm men được dùng khi làm loại bánh nào?",options:["Bánh bao","Bánh chưng","Cơm nắm"],answer:0,explain:"Bột bánh bao được ủ với men cho nở."}]},{questions:[{id:"kh4-nam-men-nam-moc-17",type:"order",q:"Sắp xếp thí nghiệm quan sát nấm mốc trên bánh mì.",items:["Lấy một lát bánh mì, nhỏ vài giọt nước","Cho vào túi ni lông và buộc kín","Để ở nơi ấm vài ngày","Quan sát qua túi, không mở túi ra"],explain:"Bánh mì ẩm để nơi ấm sẽ mốc; quan sát qua túi để an toàn."},{id:"kh4-nam-men-nam-moc-18",type:"mc",q:"Trong thí nghiệm trên, vì sao không nên mở túi bánh mì đã mốc?",options:["Để bánh mì không lạnh","Để bánh mì mốc nhanh hơn","Để túi không bị rách","Để không hít phải nấm mốc bay ra"],answer:3,explain:"Nấm mốc có thể bay vào không khí và gây hại khi hít phải."},{id:"kh4-nam-men-nam-moc-19",type:"mc",q:"Nhà Chi có nhiều thóc. Cách nào giúp thóc không bị mốc?",options:["Để thóc ướt trong bao kín","Cất ở góc bếp ẩm","Tưới nước cho thóc","Phơi thật khô, cất nơi khô ráo"],answer:3,explain:"Khô ráo giúp nấm mốc khó phát triển."},{id:"kh4-nam-men-nam-moc-20",type:"mc",q:"Hai lát bánh mì như nhau: lát A để trong tủ lạnh, lát B để nơi ấm và ẩm. Lát nào dễ bị mốc trước?",options:["Lát A","Hai lát mốc cùng lúc","Lát B","Không lát nào mốc"],answer:2,explain:"Nơi ấm và ẩm giúp nấm mốc phát triển nhanh."},{id:"kh4-nam-men-nam-moc-21",type:"tf",q:"Thức ăn đóng hộp vẫn cần xem hạn sử dụng trước khi ăn.",answer:!0,explain:"Hết hạn sử dụng thì thức ăn có thể đã hỏng."},{id:"kh4-nam-men-nam-moc-22",type:"mc",q:"Bình làm bánh bao cùng mẹ nhưng bột không nở. Lí do có thể là gì?",options:["Quên cho men vào bột","Bột có màu quá trắng","Nồi hấp quá to","Bánh nặn quá tròn"],answer:0,explain:"Không có men, bột không nở."},{id:"kh4-nam-men-nam-moc-23",type:"match",q:"Nối loại nấm với ích lợi hoặc tác hại.",pairs:[["Nấm men","Làm bánh mì nở xốp"],["Nấm mốc trên thức ăn","Làm hỏng thức ăn"],["Nấm rơm","Dùng làm thức ăn"]],explain:"Có nấm có ích, có nấm gây hại."},{id:"kh4-nam-men-nam-moc-24",type:"tf",q:"Để bánh mì trong túi kín ở nơi ấm, ẩm giúp bánh lâu bị mốc hơn.",answer:!1,explain:"Nơi ấm, ẩm làm bánh mì nhanh bị mốc hơn."}]}],challenge:{questions:[{id:"kh4-nam-men-nam-moc-25",type:"mc",q:"Vì sao người ta phơi khô cá, mực để bảo quản?",options:["Vì phơi khô làm cá to hơn","Vì khô thì nấm mốc, vi khuẩn khó phát triển","Vì nắng làm cá có thêm muối","Vì cá khô không bao giờ hỏng"],answer:1,explain:"Thiếu nước, nấm mốc và vi khuẩn khó phát triển."},{id:"kh4-nam-men-nam-moc-26",type:"multi",q:"Những việc nào giúp nhà ở ít bị nấm mốc?",options:["Phơi chăn màn khi có nắng","Để quần áo ướt trong tủ kín","Mở cửa cho thoáng khi trời khô","Đóng kín cửa suốt mùa mưa"],answers:[0,2],explain:"Thoáng và khô giúp hạn chế nấm mốc."},{id:"kh4-nam-men-nam-moc-27",type:"tf",q:"Thuốc kháng sinh pê-ni-xi-lin được làm từ một loại nấm mốc.",answer:!0,explain:"Pê-ni-xi-lin là thuốc kháng sinh lấy từ nấm mốc."},{id:"kh4-nam-men-nam-moc-28",type:"mc",q:"Nấm men và nấm mốc giống nhau ở điểm nào?",options:["Đều là thực vật có lá","Đều là nấm","Đều làm bánh mì nở","Đều ăn ngay được"],answer:1,explain:"Nấm men và nấm mốc đều thuộc nhóm nấm."},{id:"kh4-nam-men-nam-moc-29",type:"order",q:"Sắp xếp những gì xảy ra với lát bánh mì để lâu nơi ẩm.",items:["Bánh mì còn mới, mềm","Xuất hiện vài đốm nhỏ","Đốm mốc lan rộng như lông tơ","Bánh mì hỏng hoàn toàn"],explain:"Nấm mốc lan dần làm bánh hỏng."},{id:"kh4-nam-men-nam-moc-30",type:"mc",q:"Vì sao không nên cho bánh mì còn nóng vào túi kín ngay?",options:["Vì hơi nước đọng lại làm bánh ẩm, dễ mốc","Vì túi sẽ làm bánh lạnh quá","Vì bánh sẽ nở to hơn","Vì bánh sẽ thơm hơn"],answer:0,explain:"Hơi nóng ngưng tụ thành nước làm bánh ẩm, nấm mốc dễ mọc."}]},summary:["Nấm men dùng để làm bánh mì, bánh bao nở xốp.","Nấm mốc làm hỏng thức ăn; thức ăn bị mốc phải bỏ đi.","Bảo quản thức ăn bằng cách làm lạnh, phơi khô, ướp muối, đóng hộp."]},{id:"kh4-nam-doc",title:"Bài 22: Nấm độc và phòng tránh ngộ độc nấm",weeks:[25,25],learn:[{title:"Nấm độc",text:"Có nhiều loại nấm độc. Ăn phải nấm độc có thể bị ngộ độc, nguy hiểm đến tính mạng.",example:"🍄 ⚠️"},{title:"Khó phân biệt",text:"Nhiều nấm độc trông rất giống nấm ăn. Không thể phân biệt nấm độc chỉ bằng màu sắc hay mùi.",example:"🍄 ❓"},{title:"Phòng tránh",text:"Không hái, không ăn nấm lạ, nấm mọc dại. Chỉ ăn nấm rõ nguồn gốc. Thấy nôn, đau bụng sau khi ăn nấm phải báo người lớn và đến cơ sở y tế ngay.",example:"🚫 🏥"}],practice:[{questions:[{id:"kh4-nam-doc-01",type:"tf",q:"Ăn phải nấm độc có thể nguy hiểm đến tính mạng.",answer:!0,explain:"Nấm độc có thể gây ngộ độc nặng."},{id:"kh4-nam-doc-02",type:"mc",q:"Thấy nấm lạ mọc trong vườn, em nên làm gì?",options:["Hái về nấu canh","Nếm thử một chút","Cho bạn ăn thử","Không hái, không ăn"],answer:3,explain:"Nấm lạ có thể là nấm độc."},{id:"kh4-nam-doc-03",type:"multi",q:"Dấu hiệu nào có thể là ngộ độc nấm?",options:["Ăn ngon miệng","Ngủ ngon giấc","Tiêu chảy","Đau bụng","Buồn nôn, nôn"],answers:[2,3,4],explain:"Nôn, đau bụng, tiêu chảy là dấu hiệu ngộ độc thường gặp."},{id:"kh4-nam-doc-04",type:"mc",q:"Chỉ nên ăn loại nấm nào?",options:["Nấm lạ hái trong rừng sâu","Nấm có màu đẹp mọc ven đường","Nấm rõ nguồn gốc, mua ở nơi tin cậy","Nấm mọc dưới gốc cây lạ"],answer:2,explain:"Nấm rõ nguồn gốc là nấm trồng, an toàn."},{id:"kh4-nam-doc-05",type:"fill",q:"Không hái, không ăn nấm … vì có thể là nấm độc.",answer:["lạ","dại"],explain:"Nấm lạ, nấm mọc dại có thể là nấm độc."},{id:"kh4-nam-doc-06",type:"tf",q:"Nấm độc lúc nào cũng có màu sặc sỡ nên rất dễ nhận ra.",answer:!1,explain:"Có nấm độc màu trắng hoặc nâu trông rất bình thường."},{id:"kh4-nam-doc-07",type:"mc",q:"Có dấu hiệu ngộ độc sau khi ăn nấm thì cần làm gì?",options:["Đi ngủ một giấc cho khỏe","Ăn thêm nấm cho đỡ đói","Báo người lớn và đến cơ sở y tế ngay","Giấu đi, không nói với ai"],answer:2,explain:"Cần được cấp cứu kịp thời."},{id:"kh4-nam-doc-08",type:"tf",q:"Nhiều nấm độc trông giống nấm ăn được.",answer:!0,explain:"Vì vậy rất dễ nhầm lẫn nếu tự hái nấm."}]},{questions:[{id:"kh4-nam-doc-09",type:"mc",q:"Vì sao không thể dựa vào màu sắc để phân biệt nấm độc?",options:["Vì loại nấm độc nào cũng chỉ có màu đỏ","Vì loại nấm ăn nào cũng có màu sặc sỡ","Vì có nấm độc màu trắng, màu nâu trông bình thường","Vì các loại nấm đều không có màu sắc"],answer:2,explain:"Màu sắc không giúp biết chắc nấm có độc hay không."},{id:"kh4-nam-doc-10",type:"multi",q:"Những việc làm nào giúp phòng tránh ngộ độc nấm?",options:["Không ăn nấm mọc dại","Nếm thử một chút nấm lạ","Hái nấm đẹp trong rừng về nấu","Mua nấm ở nơi tin cậy"],answers:[0,3],explain:"Chỉ ăn nấm rõ nguồn gốc, không ăn nấm lạ."},{id:"kh4-nam-doc-11",type:"tf",q:"Nấu chín kĩ thì nấm độc trở thành nấm ăn được.",answer:!1,explain:"Nhiều chất độc trong nấm không mất đi khi nấu chín."},{id:"kh4-nam-doc-12",type:"mc",q:"Đi cắm trại thấy nhiều nấm đẹp, một bạn rủ hái về nấu. Em nên làm gì?",options:["Cùng hái với bạn cho vui","Nếm thử một miếng trước","Khuyên bạn không hái và báo thầy cô","Mang về cho em nhỏ chơi"],answer:2,explain:"Nấm mọc dại có thể là nấm độc."},{id:"kh4-nam-doc-13",type:"match",q:"Nối tình huống với cách xử lí.",pairs:[["Thấy nấm lạ trong vườn","Không hái, không ăn"],["Đau bụng, nôn sau khi ăn nấm","Báo người lớn, đi khám ngay"],["Đi chợ mua nấm","Chọn nơi bán rõ nguồn gốc"]],explain:"Mỗi tình huống có cách xử lí an toàn."},{id:"kh4-nam-doc-14",type:"mc",q:"Vì sao ăn nấm mọc dại rất nguy hiểm?",options:["Vì nấm dại quá cứng","Vì nấm dại không có mùi","Vì nấm dại quá ít","Vì có thể là nấm độc"],answer:3,explain:"Không biết chắc nấm dại có độc hay không."},{id:"kh4-nam-doc-15",type:"tf",q:"Chỉ ăn một ít nấm độc cũng có thể bị ngộ độc.",answer:!0,explain:"Có loại nấm rất độc, ăn ít cũng nguy hiểm."},{id:"kh4-nam-doc-16",type:"mc",q:"Khi đưa người nghi bị ngộ độc nấm đi cấp cứu, nên mang theo gì?",options:["Phần nấm còn lại nếu có","Đồ chơi yêu thích","Sách vở của em","Không cần mang gì"],answer:0,explain:"Mẫu nấm giúp bác sĩ biết loại nấm để chữa trị."}]},{questions:[{id:"kh4-nam-doc-17",type:"order",q:"Sắp xếp việc cần làm khi nghi bị ngộ độc nấm.",items:["Ngừng ăn món nấm ngay","Báo cho người lớn","Đến cơ sở y tế gần nhất"],explain:"Ngừng ăn, báo người lớn rồi đi cấp cứu kịp thời."},{id:"kh4-nam-doc-18",type:"mc",q:"Ông của Dũng hái được nấm trong rừng trông giống nấm ăn. Dũng nên nói gì?",options:["Ông nấu ngay cho cháu ăn","Ông cho cháu nếm thử","Nấm đẹp thế chắc không độc","Ông ơi, nấm lạ có thể là nấm độc, mình đừng ăn ạ"],answer:3,explain:"Nấm rừng lạ có thể là nấm độc dù trông giống nấm ăn."},{id:"kh4-nam-doc-19",type:"multi",q:"Những câu nào đúng?",options:["Nấm độc chỉ mọc trong rừng sâu","Nấm độc có thể gây tử vong","Nhiều nấm độc giống nấm ăn","Nấm có mùi thơm thì không độc"],answers:[1,2],explain:"Nấm độc có thể mọc ở nhiều nơi và có mùi bình thường."},{id:"kh4-nam-doc-20",type:"tf",q:"Nhiều người cùng bị đau bụng, nôn sau bữa ăn có nấm lạ thì cần đi cấp cứu ngay.",answer:!0,explain:"Đó có thể là ngộ độc nấm, cần cứu chữa kịp thời."},{id:"kh4-nam-doc-21",type:"mc",q:"Vì sao trẻ em không được tự hái nấm để ăn?",options:["Vì cây nấm quá nặng để mang về","Vì rất khó phân biệt nấm độc và nấm ăn","Vì nấm chỉ mọc vào ban đêm","Vì nấm ăn không ngon chút nào"],answer:1,explain:"Ngay cả người lớn cũng dễ nhầm nấm độc với nấm ăn."},{id:"kh4-nam-doc-22",type:"mc",q:"Lớp em muốn tuyên truyền phòng ngộ độc nấm. Việc làm nào phù hợp?",options:["Hái nấm lạ đem tặng các bạn","Nếm thử từng loại nấm để biết","Mang nấm dại vào lớp để chơi","Vẽ tranh, làm áp phích “Không ăn nấm lạ”"],answer:3,explain:"Tuyên truyền giúp mọi người cảnh giác với nấm lạ."},{id:"kh4-nam-doc-23",type:"match",q:"Nối loại nấm với cách dùng đúng.",pairs:[["Nấm rơm mua ở chợ","Rửa sạch, nấu chín để ăn"],["Nấm lạ mọc dại","Không hái, không ăn"],["Bánh mì có nấm mốc","Bỏ đi"]],explain:"Mỗi loại nấm cần được dùng hoặc xử lí đúng cách."},{id:"kh4-nam-doc-24",type:"tf",q:"Có thể cho vật nuôi ăn thử nấm lạ để biết nấm có độc không.",answer:!1,explain:"Làm vậy vừa hại vật nuôi vừa không đáng tin."}]}],challenge:{questions:[{id:"kh4-nam-doc-25",type:"mc",q:"Một gia đình hái nấm rừng về ăn, vài giờ sau cả nhà bị nôn, đau bụng. Nguyên nhân nhiều khả năng nhất là gì?",options:["Ăn quá ít","Ngộ độc nấm","Uống quá nhiều nước sạch","Ngủ quá sớm"],answer:1,explain:"Ăn nấm rừng lạ rồi cùng có dấu hiệu ngộ độc là dấu hiệu của ngộ độc nấm."},{id:"kh4-nam-doc-26",type:"multi",q:"Cách làm nào là đúng để phòng ngộ độc nấm?",options:["Nấm màu trắng thì ăn được","Chỉ ăn nấm rõ nguồn gốc","Không ăn nấm lạ","Nấm có mùi thơm thì ăn được"],answers:[1,2],explain:"Không có cách “thử” nấm độc nào đáng tin; chỉ ăn nấm rõ nguồn gốc."},{id:"kh4-nam-doc-27",type:"tf",q:"Dấu hiệu ngộ độc nấm có khi xuất hiện sau nhiều giờ, nên không được chủ quan.",answer:!0,explain:"Có loại nấm độc gây dấu hiệu muộn, rất nguy hiểm."},{id:"kh4-nam-doc-28",type:"mc",q:"Vì sao cần đưa người ngộ độc nấm đến cơ sở y tế càng sớm càng tốt?",options:["Để được ăn thêm","Để được ngủ","Để được cứu chữa kịp thời","Để không phải uống nước"],answer:2,explain:"Cứu chữa sớm giúp giảm nguy hiểm."},{id:"kh4-nam-doc-29",type:"match",q:"Nối loại nấm với điều cần nhớ.",pairs:[["Nấm ăn","Rõ nguồn gốc, nấu chín"],["Nấm mốc trên thức ăn","Không ăn thức ăn đã mốc"],["Nấm độc","Có thể gây chết người"]],explain:"Hiểu đúng về nấm giúp sống an toàn."},{id:"kh4-nam-doc-30",type:"order",q:"Sắp xếp các việc khi mua và dùng nấm ăn.",items:["Chọn nơi bán nấm rõ nguồn gốc","Chọn nấm tươi, không dập nát","Mang về rửa sạch","Nấu chín rồi mới ăn"],explain:"Chọn đúng nơi, đúng nấm, sơ chế sạch và nấu chín."}]},summary:["Nấm độc có thể gây ngộ độc, nguy hiểm đến tính mạng.","Nhiều nấm độc giống nấm ăn; không phân biệt được bằng màu sắc, mùi.","Không hái, không ăn nấm lạ; có dấu hiệu ngộ độc phải đến cơ sở y tế ngay."]}]},{id:"con-nguoi-suc-khoe",title:"Con người và sức khỏe",lessons:[{id:"kh4-chat-dinh-duong",title:"Bài 23: Các nhóm chất dinh dưỡng",weeks:[26,26],learn:[{title:"Các nhóm chất",text:"Thức ăn có các nhóm chất dinh dưỡng: chất bột đường, chất đạm, chất béo, vi-ta-min và chất khoáng.",example:"🍚 🍗 🥜 🥦"},{title:"Vai trò",text:"Chất bột đường cung cấp năng lượng. Chất đạm giúp xây dựng cơ thể. Chất béo cung cấp năng lượng, giúp hấp thu một số vi-ta-min. Vi-ta-min và chất khoáng giúp cơ thể khỏe mạnh, phòng bệnh.",example:"⚡ 💪 🛡️"},{title:"Thức ăn chứa gì",text:"Gạo, ngô, khoai, bánh mì nhiều chất bột đường. Thịt, cá, trứng, đậu nhiều chất đạm. Dầu ăn, mỡ, lạc, vừng nhiều chất béo. Rau, quả nhiều vi-ta-min và chất khoáng.",example:"🍞 🥚 🫒 🍊"}],practice:[{questions:[{id:"kh4-chat-dinh-duong-01",type:"mc",q:"Gạo, ngô, khoai chứa nhiều chất gì?",emoji:"🌽",options:["Chất đạm","Chất béo","Chất khoáng","Chất bột đường"],answer:3,explain:"Gạo, ngô, khoai là thức ăn giàu chất bột đường."},{id:"kh4-chat-dinh-duong-02",type:"mc",q:"Thịt, cá, trứng chứa nhiều chất gì?",emoji:"🥚",options:["Chất béo","Chất đạm","Chất bột đường","Vi-ta-min"],answer:1,explain:"Thịt, cá, trứng giàu chất đạm."},{id:"kh4-chat-dinh-duong-03",type:"mc",q:"Dầu ăn, mỡ, lạc, vừng chứa nhiều chất gì?",options:["Chất béo","Chất đạm","Chất bột đường","Chất khoáng"],answer:0,explain:"Dầu ăn, mỡ, lạc, vừng giàu chất béo."},{id:"kh4-chat-dinh-duong-04",type:"tf",q:"Rau và quả chín chứa nhiều vi-ta-min và chất khoáng.",emoji:"🥕",answer:!0,explain:"Rau, quả là nguồn vi-ta-min và chất khoáng."},{id:"kh4-chat-dinh-duong-05",type:"fill",q:"Chất bột … cung cấp năng lượng cho cơ thể hoạt động.",answer:["đường"],explain:"Chất bột đường là nguồn năng lượng chủ yếu."},{id:"kh4-chat-dinh-duong-06",type:"tf",q:"Chất đạm chỉ có trong thịt, không có trong các loại đậu.",answer:!1,explain:"Các loại đậu, đậu phụ cũng giàu chất đạm."},{id:"kh4-chat-dinh-duong-07",type:"multi",q:"Thức ăn nào chứa nhiều chất bột đường?",options:["Cơm","Dầu ăn","Bánh mì","Khoai lang","Cá"],answers:[0,2,3],explain:"Cơm, bánh mì, khoai lang giàu chất bột đường."},{id:"kh4-chat-dinh-duong-08",type:"tf",q:"Chỉ cần ăn một loại thức ăn là đủ chất dinh dưỡng.",answer:!1,explain:"Không loại thức ăn nào có đủ mọi chất, cần ăn nhiều loại."}]},{questions:[{id:"kh4-chat-dinh-duong-09",type:"match",q:"Nối nhóm chất với vai trò.",pairs:[["Chất bột đường","Cung cấp năng lượng chủ yếu"],["Chất đạm","Xây dựng cơ thể, giúp lớn lên"],["Vi-ta-min và chất khoáng","Giúp phòng bệnh, cơ thể khỏe mạnh"]],explain:"Mỗi nhóm chất có vai trò riêng."},{id:"kh4-chat-dinh-duong-10",type:"mc",q:"Chất nào giúp xây dựng cơ thể, giúp em lớn lên?",options:["Chất béo","Chất đạm","Chất bột đường","Nước lọc"],answer:1,explain:"Chất đạm giúp xây dựng và đổi mới cơ thể."},{id:"kh4-chat-dinh-duong-11",type:"mc",q:"Chất béo có vai trò gì?",options:["Làm cơ thể không cần ăn rau xanh nữa","Cung cấp năng lượng, giúp hấp thu một số vi-ta-min","Thay thế hoàn toàn cho nước uống hằng ngày","Giúp xương không bao giờ bị gãy dù ngã"],answer:1,explain:"Chất béo cung cấp năng lượng và giúp hấp thu các vi-ta-min A, D, E, K."},{id:"kh4-chat-dinh-duong-12",type:"multi",q:"Thức ăn nào chứa nhiều chất đạm?",options:["Rau muống","Cá","Gạo","Đậu phụ","Trứng"],answers:[1,3,4],explain:"Trứng, đậu phụ, cá giàu chất đạm."},{id:"kh4-chat-dinh-duong-13",type:"tf",q:"Đậu phụ chứa ít chất đạm hơn cơm trắng.",answer:!1,explain:"Đậu phụ làm từ đậu tương, giàu chất đạm hơn cơm trắng."},{id:"kh4-chat-dinh-duong-14",type:"mc",q:"Quả cam chứa nhiều chất gì?",emoji:"🍊",options:["Chất béo","Chất đạm","Vi-ta-min","Chất bột đường"],answer:2,explain:"Cam là quả giàu vi-ta-min."},{id:"kh4-chat-dinh-duong-15",type:"tf",q:"Chất béo không cần cho cơ thể nên không nên ăn chút nào.",answer:!1,explain:"Cơ thể cần chất béo, chỉ nên ăn vừa phải."},{id:"kh4-chat-dinh-duong-16",type:"mc",q:"Vì sao bữa sáng nên có cơm, bánh mì hoặc phở?",options:["Để có thật nhiều vi-ta-min","Để có năng lượng học tập","Để cơ thể có thêm chất khoáng","Để bữa trưa không cần ăn nữa"],answer:1,explain:"Cơm, bánh mì, phở cung cấp chất bột đường cho năng lượng."}]},{questions:[{id:"kh4-chat-dinh-duong-17",type:"mc",q:"Bữa ăn có cơm, trứng rán, rau luộc. Rau luộc cung cấp chủ yếu chất gì?",options:["Chất béo và chất đạm","Vi-ta-min và chất khoáng","Chất bột đường và chất béo","Chất đạm và chất bột đường"],answer:1,explain:"Rau là nguồn vi-ta-min và chất khoáng."},{id:"kh4-chat-dinh-duong-18",type:"multi",q:"Lan chỉ ăn cơm với rau. Lan nên ăn thêm thức ăn nào để có chất đạm?",options:["Bánh mì","Thịt","Trứng","Khoai","Cá"],answers:[1,2,4],explain:"Thịt, cá, trứng giàu chất đạm; bánh mì, khoai giàu chất bột đường."},{id:"kh4-chat-dinh-duong-19",type:"match",q:"Nối thức ăn với nhóm chất có nhiều nhất.",pairs:[["Bánh mì","Chất bột đường"],["Thịt bò","Chất đạm"],["Dầu ăn","Chất béo"],["Rau cải","Vi-ta-min và chất khoáng"]],explain:"Mỗi thức ăn giàu một nhóm chất."},{id:"kh4-chat-dinh-duong-20",type:"tf",q:"Ngô và khoai chứa nhiều chất đạm hơn cá.",answer:!1,explain:"Ngô, khoai giàu chất bột đường; cá giàu chất đạm."},{id:"kh4-chat-dinh-duong-21",type:"mc",q:"Vì sao trẻ em đang lớn cần ăn đủ chất đạm?",options:["Để da đổi màu","Để ngủ ít đi","Để cơ thể lớn lên","Để không cần uống nước"],answer:2,explain:"Chất đạm giúp xây dựng cơ thể."},{id:"kh4-chat-dinh-duong-22",type:"mc",q:"Vận động viên chạy nhiều cần ăn đủ chất bột đường. Vì sao?",emoji:"🏃",options:["Vì chất bột đường giúp mắt nhìn rõ hơn","Vì chất bột đường thay được nước uống","Vì chất bột đường cung cấp năng lượng","Vì chất bột đường làm cơ bắp nhỏ đi"],answer:2,explain:"Chạy nhiều cần nhiều năng lượng."},{id:"kh4-chat-dinh-duong-23",type:"tf",q:"Lạc và vừng chứa rất ít chất béo.",emoji:"🥜",answer:!1,explain:"Lạc, vừng giàu chất béo nên được dùng để ép dầu."},{id:"kh4-chat-dinh-duong-24",type:"order",q:"Sắp xếp các bước tìm hiểu các nhóm chất trong một bữa ăn.",items:["Ghi lại các món ăn trong bữa","Kể tên thực phẩm trong từng món","Xếp mỗi thực phẩm vào nhóm chất","Nhận xét bữa ăn đã đủ chất chưa"],explain:"Liệt kê món, thực phẩm, xếp nhóm rồi nhận xét."}]}],challenge:{questions:[{id:"kh4-chat-dinh-duong-25",type:"mc",q:"Bữa ăn có cơm, đậu phụ sốt cà chua, canh bí. Thức ăn nào cung cấp nhiều chất đạm nhất?",options:["Cơm trắng","Đậu phụ","Canh bí xanh","Cà chua chín"],answer:1,explain:"Đậu phụ giàu chất đạm."},{id:"kh4-chat-dinh-duong-26",type:"multi",q:"Những thức ăn nào chứa nhiều chất béo?",options:["Dầu ăn","Lạc rang","Rau muống","Mỡ lợn","Gạo"],answers:[0,1,3],explain:"Mỡ, lạc, dầu ăn giàu chất béo."},{id:"kh4-chat-dinh-duong-27",type:"tf",q:"Có thể chỉ ăn rau quả mà bỏ hẳn chất bột đường, chất đạm, chất béo.",answer:!1,explain:"Cơ thể cần đủ các nhóm chất; không nhóm nào thay thế hoàn toàn nhóm khác."},{id:"kh4-chat-dinh-duong-28",type:"mc",q:"Ăn quá nhiều chất béo, chất bột đường mà ít vận động thì dễ bị gì?",options:["Cơ thể bị thiếu năng lượng","Cơ thể gầy đi rất nhanh","Thừa cân, béo phì","Mắt nhìn rõ hơn bình thường"],answer:2,explain:"Năng lượng thừa tích lại làm cơ thể thừa cân."},{id:"kh4-chat-dinh-duong-29",type:"match",q:"Nối thực phẩm với nhóm chất có nhiều nhất.",pairs:[["Đậu tương","Chất đạm"],["Mỡ lợn","Chất béo"],["Bún","Chất bột đường"]],explain:"Mỗi thực phẩm giàu một nhóm chất."},{id:"kh4-chat-dinh-duong-30",type:"number",q:"Giả sử mỗi quả trứng có 6 g chất đạm. Hai quả trứng có bao nhiêu gam chất đạm?",answer:12,unit:"g",explain:"Số gam chất đạm là 6 × 2 = 12 g."}]},summary:["Thức ăn có các nhóm chất: bột đường, đạm, béo, vi-ta-min và chất khoáng.","Chất bột đường, chất béo cho năng lượng; chất đạm xây dựng cơ thể; vi-ta-min và chất khoáng giúp phòng bệnh.","Cần ăn nhiều loại thức ăn để có đủ các nhóm chất."]},{id:"kh4-an-uong-can-bang",title:"Bài 24: Chế độ ăn uống cân bằng",weeks:[27,27],learn:[{title:"Ăn uống cân bằng",text:"Ăn đủ các nhóm chất với lượng hợp lí; phối hợp nhiều loại thực phẩm và thường xuyên thay đổi món.",example:"🍽️"},{title:"Tháp dinh dưỡng",text:"Nên ăn đủ lương thực, nhiều rau quả; ăn vừa phải thịt, cá, trứng, sữa; ăn ít chất béo; hạn chế đường và muối.",example:"🔺"},{title:"Thói quen tốt",text:"Ăn đủ bữa, không bỏ bữa sáng, uống đủ nước, hạn chế đồ chiên rán, đồ ngọt và nước ngọt có ga.",example:"🥛 🚫🥤"}],practice:[{questions:[{id:"kh4-an-uong-can-bang-01",type:"tf",q:"Nên ăn hạn chế muối và đường.",answer:!0,explain:"Ăn nhiều muối, đường không tốt cho sức khỏe."},{id:"kh4-an-uong-can-bang-02",type:"mc",q:"Nên ăn nhiều nhóm thức ăn nào?",options:["Lương thực, rau và quả","Đường và bánh kẹo","Muối và đồ mặn","Mỡ và đồ chiên rán"],answer:0,explain:"Lương thực, rau, quả nên ăn đủ và nhiều."},{id:"kh4-an-uong-can-bang-03",type:"mc",q:"Vì sao nên thường xuyên thay đổi món ăn?",options:["Để có đủ chất và ăn ngon miệng","Để chỉ ăn một loại thức ăn","Để bữa ăn ít chất đạm hơn","Để ăn được nhiều bánh kẹo hơn"],answer:0,explain:"Thay đổi món giúp có đủ chất và không chán ăn."},{id:"kh4-an-uong-can-bang-04",type:"tf",q:"Bỏ bữa sáng không ảnh hưởng gì đến việc học.",answer:!1,explain:"Bỏ bữa sáng dễ mệt, khó tập trung học."},{id:"kh4-an-uong-can-bang-05",type:"fill",q:"Ăn uống … bằng là ăn đủ các nhóm chất với lượng hợp lí.",answer:["cân"],explain:"Đó là chế độ ăn uống cân bằng."},{id:"kh4-an-uong-can-bang-06",type:"multi",q:"Thói quen nào tốt cho sức khỏe?",options:["Ăn nhiều rau quả","Uống đủ nước","Uống nhiều nước ngọt có ga","Ăn nhiều đồ chiên rán"],answers:[0,1],explain:"Rau quả và nước lọc tốt cho sức khỏe."},{id:"kh4-an-uong-can-bang-07",type:"tf",q:"Ăn bánh kẹo thay cơm giúp cơ thể khỏe hơn.",answer:!1,explain:"Bánh kẹo nhiều đường, thiếu nhiều chất cần thiết."},{id:"kh4-an-uong-can-bang-08",type:"mc",q:"Đồ uống nào tốt nhất cho cơ thể hằng ngày?",emoji:"💧",options:["Nước lọc sạch","Nước ngọt có ga","Trà sữa nhiều đường","Nước tăng lực"],answer:0,explain:"Nước lọc sạch tốt nhất cho cơ thể."}]},{questions:[{id:"kh4-an-uong-can-bang-09",type:"match",q:"Nối nhóm thực phẩm với mức nên ăn.",pairs:[["Lương thực như gạo, ngô","Ăn đủ, nhiều nhất"],["Thịt, cá, trứng","Ăn vừa phải"],["Muối, đường","Ăn hạn chế"]],explain:"Tháp dinh dưỡng cho biết nên ăn bao nhiêu mỗi nhóm."},{id:"kh4-an-uong-can-bang-10",type:"mc",q:"Vì sao cần ăn hạn chế muối?",emoji:"🧂",options:["Ăn mặn lâu ngày dễ bị huyết áp cao","Vì muối làm thức ăn mất hết vi-ta-min","Vì muối làm cơ thể lớn lên quá nhanh","Vì muối không có trong món ăn nào"],answer:0,explain:"Ăn nhiều muối lâu ngày dễ mắc bệnh huyết áp cao."},{id:"kh4-an-uong-can-bang-11",type:"tf",q:"Một bữa ăn chỉ có cơm và rau là đã cân bằng.",answer:!1,explain:"Bữa ăn đó còn thiếu chất đạm, chất béo."},{id:"kh4-an-uong-can-bang-12",type:"mc",q:"Bữa ăn nào cân đối nhất?",options:["Cơm trắng, khoai rán, bánh mì","Cơm, cá kho, rau luộc, quả chuối","Thịt rán, trứng rán, nước ngọt","Bánh kẹo, nước ngọt, kem que"],answer:1,explain:"Bữa đó có đủ bột đường, đạm, béo, vi-ta-min và chất khoáng."},{id:"kh4-an-uong-can-bang-13",type:"mc",q:"Vì sao nên hạn chế đồ chiên rán?",options:["Vì đồ chiên rán có quá nhiều vi-ta-min","Vì đồ chiên rán không có chút chất béo","Vì nhiều chất béo, dễ gây thừa cân","Vì đồ chiên rán làm cơ thể thiếu muối"],answer:2,explain:"Đồ chiên rán nhiều dầu mỡ."},{id:"kh4-an-uong-can-bang-14",type:"tf",q:"Uống nước ngọt có ga thay nước lọc hằng ngày là thói quen tốt.",answer:!1,explain:"Nước ngọt có ga nhiều đường, không tốt cho răng và sức khỏe."},{id:"kh4-an-uong-can-bang-15",type:"mc",q:"Mỗi ngày em cần ăn mấy bữa chính?",options:["Một bữa","Hai bữa, nhịn sáng","Không cần bữa nào","Ba bữa"],answer:3,explain:"Ăn đủ ba bữa chính: sáng, trưa, tối."},{id:"kh4-an-uong-can-bang-16",type:"tf",q:"Ăn đa dạng thực phẩm giúp cơ thể có đủ chất dinh dưỡng.",answer:!0,explain:"Mỗi loại thực phẩm có chất khác nhau nên cần ăn đa dạng."}]},{questions:[{id:"kh4-an-uong-can-bang-17",type:"order",q:"Sắp xếp các bước lập thực đơn một ngày cho gia đình.",items:["Chọn đủ các nhóm thực phẩm","Lên món cho bữa sáng, trưa, tối","Kiểm tra muối, đường, chất béo không quá nhiều","Ghi thực đơn và cùng gia đình thực hiện"],explain:"Chọn thực phẩm, lên món, kiểm tra rồi thực hiện."},{id:"kh4-an-uong-can-bang-18",type:"mc",q:"Tùng thích ăn gà rán và uống nước ngọt mỗi ngày. Em khuyên Tùng thế nào?",options:["Ăn gà rán cả ba bữa cho đủ chất đạm","Ăn ít đồ rán, uống nước lọc, ăn thêm rau","Uống thêm nhiều nước ngọt cho đỡ khát","Thay hết cơm bằng gà rán và kem que"],answer:1,explain:"Hạn chế đồ rán, nước ngọt và ăn thêm rau quả."},{id:"kh4-an-uong-can-bang-19",type:"multi",q:"Bữa ăn của Hà có cơm, thịt kho. Nên thêm món nào cho cân đối?",options:["Nước ngọt có ga","Rau luộc","Bánh ngọt","Một quả chuối"],answers:[1,3],explain:"Rau, quả bổ sung vi-ta-min, chất khoáng và chất xơ."},{id:"kh4-an-uong-can-bang-20",type:"tf",q:"Chỉ trẻ em mới cần ăn uống cân bằng, người lớn thì không cần.",answer:!1,explain:"Mọi người đều cần ăn uống cân bằng."},{id:"kh4-an-uong-can-bang-21",type:"mc",q:"Ngọc không thích ăn rau. Rau quả giúp Ngọc có thêm gì?",options:["Thật nhiều chất béo và chất đạm","Thật nhiều muối và đường","Vi-ta-min, chất khoáng và chất xơ","Không có chất gì, chỉ no bụng"],answer:2,explain:"Rau quả giàu vi-ta-min, chất khoáng, chất xơ."},{id:"kh4-an-uong-can-bang-22",type:"number",q:"Giả sử mỗi ngày em uống 6 cốc nước. Trong 7 ngày em uống bao nhiêu cốc nước?",answer:42,unit:"cốc",explain:"Số cốc nước là 6 × 7 = 42 cốc."},{id:"kh4-an-uong-can-bang-23",type:"match",q:"Nối thói quen với lời khuyên.",pairs:[["Hay bỏ bữa sáng","Ăn sáng đầy đủ trước khi đi học"],["Ăn quá mặn","Giảm bớt nước chấm, muối"],["Ít ăn rau","Mỗi bữa đều có rau, quả"]],explain:"Sửa thói quen chưa tốt để ăn uống cân bằng."},{id:"kh4-an-uong-can-bang-24",type:"tf",q:"Ăn thật no một bữa rồi nhịn các bữa khác là cách ăn hợp lí.",answer:!1,explain:"Cần ăn đều đặn, đủ bữa."}]}],challenge:{questions:[{id:"kh4-an-uong-can-bang-25",type:"mc",q:"Nhà Khoa ăn cá rán liền ba ngày. Lời khuyên nào phù hợp nhất?",options:["Đổi món, chế biến nhiều cách khác","Tiếp tục ăn cá rán cả tuần","Bỏ cá, chỉ ăn cơm với muối","Đổi cá rán thành gà rán, khoai rán"],answer:0,explain:"Thay đổi món và cách chế biến giúp ăn ngon và đủ chất."},{id:"kh4-an-uong-can-bang-26",type:"multi",q:"Những thực đơn nào cân đối?",options:["Cơm, khoai tây chiên, bánh mì","Bún, thịt bò, rau sống, quả cam","Bánh ngọt, kem, nước ngọt","Cơm, đậu phụ sốt cà chua, canh rau, quả ổi"],answers:[1,3],explain:"Thực đơn cân đối có đủ các nhóm chất."},{id:"kh4-an-uong-can-bang-27",type:"tf",q:"Uống sữa và ăn các loại đậu giúp xương chắc khỏe.",emoji:"🥛",answer:!0,explain:"Sữa và đậu có can-xi, chất đạm tốt cho xương."},{id:"kh4-an-uong-can-bang-28",type:"mc",q:"Mai tăng cân nhanh vì hay ăn vặt bánh kẹo, ít vận động. Mai nên làm gì?",options:["Nhịn hẳn bữa tối mỗi ngày","Ăn thêm bánh kẹo, ngủ nhiều hơn","Chỉ uống nước ngọt thay bữa ăn","Giảm đồ ngọt, vận động, ăn đủ bữa"],answer:3,explain:"Ăn uống hợp lí kết hợp vận động giúp giữ cân nặng."},{id:"kh4-an-uong-can-bang-29",type:"order",q:"Sắp xếp các nhóm thực phẩm theo mức nên ăn từ nhiều đến ít.",items:["Gạo, ngô, khoai","Rau, quả","Thịt, cá, trứng","Muối, đường"],explain:"Lương thực nhiều nhất, muối và đường ít nhất."},{id:"kh4-an-uong-can-bang-30",type:"match",q:"Nối việc làm với lợi ích.",pairs:[["Ăn sáng đầy đủ","Có năng lượng học tập"],["Ăn nhiều rau quả","Có vi-ta-min và chất xơ"],["Ăn ít muối","Phòng bệnh huyết áp cao"]],explain:"Thói quen ăn uống tốt mang lại sức khỏe."}]},summary:["Ăn uống cân bằng là ăn đủ các nhóm chất với lượng hợp lí.","Ăn đa dạng, thay đổi món; hạn chế muối, đường, đồ chiên rán.","Ăn đủ ba bữa, không bỏ bữa sáng, uống đủ nước."]},{id:"kh4-benh-dinh-duong",title:"Bài 25: Một số bệnh liên quan đến dinh dưỡng",weeks:[28,28],learn:[{title:"Suy dinh dưỡng",text:"Ăn không đủ chất có thể bị suy dinh dưỡng: cơ thể gầy yếu, thấp còi, hay ốm.",example:"📏"},{title:"Thiếu một số chất",text:"Thiếu sắt dễ bị thiếu máu. Thiếu i-ốt dễ bị bướu cổ. Thiếu vi-ta-min D và can-xi dễ bị còi xương. Thiếu vi-ta-min A dễ bị khô mắt, quáng gà.",example:"🥩 🧂 🥛 🥕"},{title:"Thừa cân, béo phì",text:"Ăn quá nhiều chất béo, đồ ngọt mà ít vận động dễ bị thừa cân, béo phì.",example:"🍩 🛋️"},{title:"Phòng bệnh",text:"Ăn uống cân bằng, đa dạng; dùng muối i-ốt; vận động hợp lí; theo dõi cân nặng, chiều cao.",example:"⚖️ 🏃"}],practice:[{questions:[{id:"kh4-benh-dinh-duong-01",type:"mc",q:"Thiếu i-ốt dễ mắc bệnh gì?",options:["Còi xương","Bướu cổ","Quáng gà","Sâu răng"],answer:1,explain:"I-ốt cần cho tuyến giáp; thiếu i-ốt dễ bị bướu cổ."},{id:"kh4-benh-dinh-duong-02",type:"mc",q:"Thiếu sắt dễ mắc bệnh gì?",options:["Bướu cổ","Béo phì","Còi xương","Thiếu máu"],answer:3,explain:"Sắt cần để tạo máu."},{id:"kh4-benh-dinh-duong-03",type:"mc",q:"Thiếu vi-ta-min A dễ bị bệnh gì?",options:["Bướu cổ to","Khô mắt, quáng gà","Thừa cân, béo phì","Đau răng, sâu răng"],answer:1,explain:"Vi-ta-min A cần cho mắt."},{id:"kh4-benh-dinh-duong-04",type:"tf",q:"Thiếu vi-ta-min D và can-xi dễ bị còi xương.",answer:!0,explain:"Vi-ta-min D và can-xi giúp xương chắc khỏe."},{id:"kh4-benh-dinh-duong-05",type:"fill",q:"Để phòng bệnh bướu cổ, nên dùng muối … khi nấu ăn.",answer:["i-ốt","iốt","i ốt","iot"],explain:"Muối i-ốt giúp bổ sung i-ốt cho cơ thể."},{id:"kh4-benh-dinh-duong-06",type:"tf",q:"Béo phì là bệnh do ăn quá ít.",answer:!1,explain:"Béo phì thường do ăn quá nhiều, ít vận động."},{id:"kh4-benh-dinh-duong-07",type:"multi",q:"Dấu hiệu nào của suy dinh dưỡng?",options:["Thấp còi","Ăn ngon, ngủ khỏe","Hay ốm","Gầy yếu"],answers:[0,2,3],explain:"Suy dinh dưỡng làm cơ thể gầy yếu, thấp còi, hay ốm."},{id:"kh4-benh-dinh-duong-08",type:"tf",q:"Suy dinh dưỡng chỉ gặp ở người lớn tuổi.",answer:!1,explain:"Trẻ em cũng có thể bị suy dinh dưỡng nếu ăn không đủ chất."}]},{questions:[{id:"kh4-benh-dinh-duong-09",type:"match",q:"Nối bệnh với nguyên nhân.",pairs:[["Bướu cổ","Thiếu i-ốt"],["Thiếu máu","Thiếu sắt"],["Còi xương","Thiếu vi-ta-min D và can-xi"],["Quáng gà","Thiếu vi-ta-min A"]],explain:"Mỗi bệnh do thiếu một chất nhất định."},{id:"kh4-benh-dinh-duong-10",type:"mc",q:"Thực phẩm nào giàu vi-ta-min A?",emoji:"🥕",options:["Muối ăn, đường","Cà rốt, gấc","Gạo trắng, bún","Dầu ăn, mỡ"],answer:1,explain:"Cà rốt, gấc có nhiều chất tạo vi-ta-min A."},{id:"kh4-benh-dinh-duong-11",type:"mc",q:"Vì sao ăn nhiều đồ ngọt, đồ béo mà ít vận động dễ béo phì?",options:["Vì đồ ngọt không có chút năng lượng nào","Vì vận động ít làm cơ thể thiếu chất béo","Vì đồ béo giúp cơ thể gầy đi rất nhanh","Vì năng lượng ăn vào nhiều hơn năng lượng dùng"],answer:3,explain:"Năng lượng thừa tích lại thành mỡ."},{id:"kh4-benh-dinh-duong-12",type:"tf",q:"Tắm nắng giữa trưa thật lâu là cách tốt nhất để có vi-ta-min D.",emoji:"🌅",answer:!1,explain:"Chỉ nên tắm nắng sáng sớm vừa phải; nắng trưa gắt có hại cho da."},{id:"kh4-benh-dinh-duong-13",type:"multi",q:"Thực phẩm nào giàu sắt?",options:["Thịt bò","Gan","Muối","Đường"],answers:[0,1],explain:"Thịt bò, gan là nguồn sắt tốt."},{id:"kh4-benh-dinh-duong-14",type:"tf",q:"Người béo phì thì không bao giờ bị thiếu chất.",answer:!1,explain:"Người béo phì vẫn có thể thiếu vi-ta-min, chất khoáng nếu ăn không cân đối."},{id:"kh4-benh-dinh-duong-15",type:"mc",q:"Vì sao cần cân, đo chiều cao trẻ em định kì?",options:["Để biết bạn nào chạy nhanh nhất trong lớp","Để sớm phát hiện suy dinh dưỡng hoặc thừa cân","Để chọn quần áo có màu sắc đẹp hơn","Để biết hôm nay trời nóng hay trời lạnh"],answer:1,explain:"Theo dõi cân nặng, chiều cao giúp phát hiện sớm vấn đề dinh dưỡng."},{id:"kh4-benh-dinh-duong-16",type:"tf",q:"Thiếu i-ốt có thể ảnh hưởng đến sự phát triển trí tuệ của trẻ.",answer:!0,explain:"I-ốt rất cần cho sự phát triển của trẻ."}]},{questions:[{id:"kh4-benh-dinh-duong-17",type:"mc",q:"Bình ít ăn thịt, cá, trứng, người gầy và thấp hơn các bạn. Bình có thể bị gì?",options:["Béo phì","Suy dinh dưỡng","Bướu cổ","Sâu răng"],answer:1,explain:"Thiếu chất đạm và năng lượng dễ dẫn tới suy dinh dưỡng."},{id:"kh4-benh-dinh-duong-18",type:"multi",q:"Những việc nào giúp phòng béo phì?",options:["Ăn vặt nhiều trước khi ngủ","Hạn chế đồ ngọt, nước ngọt","Vận động, chơi thể thao","Ngồi xem ti vi cả ngày"],answers:[1,2],explain:"Ăn hợp lí và vận động giúp phòng béo phì."},{id:"kh4-benh-dinh-duong-19",type:"mc",q:"Nhà Lan ở vùng núi xa biển. Để phòng bướu cổ, gia đình nên làm gì?",options:["Ăn thật nhiều đường mỗi ngày","Chỉ uống nước ngọt có ga","Dùng muối i-ốt khi nấu ăn","Không ăn rau xanh nữa"],answer:2,explain:"Muối i-ốt bổ sung i-ốt cho cơ thể."},{id:"kh4-benh-dinh-duong-20",type:"tf",q:"Khi trẻ có dấu hiệu suy dinh dưỡng, cần đưa đi khám để được tư vấn chế độ ăn.",answer:!0,explain:"Bác sĩ sẽ hướng dẫn cách ăn uống phù hợp."},{id:"kh4-benh-dinh-duong-21",type:"order",q:"Sắp xếp việc gia đình làm khi thấy con chậm tăng cân.",items:["Theo dõi cân nặng, chiều cao","Đưa con đi khám","Thay đổi bữa ăn theo lời khuyên","Tiếp tục theo dõi sự thay đổi"],explain:"Theo dõi, đi khám, điều chỉnh bữa ăn rồi theo dõi tiếp."},{id:"kh4-benh-dinh-duong-22",type:"mc",q:"Phúc nặng cân hơn nhiều so với tuổi. Lời khuyên nào đúng?",options:["Nhịn ăn hoàn toàn để giảm cân thật nhanh","Ăn nhiều đồ chiên, ít vận động hơn","Ăn cân đối, giảm đồ ngọt, tăng vận động","Chỉ ăn bánh kẹo, không ăn cơm"],answer:2,explain:"Cần ăn cân đối và vận động, không được nhịn ăn."},{id:"kh4-benh-dinh-duong-23",type:"match",q:"Nối thực phẩm với chất giúp phòng bệnh.",pairs:[["Muối i-ốt","I-ốt"],["Cà rốt, gấc","Vi-ta-min A"],["Thịt bò, gan","Sắt"]],explain:"Ăn đa dạng giúp có đủ các chất."},{id:"kh4-benh-dinh-duong-24",type:"tf",q:"Chỉ cần uống thuốc bổ là đủ, không cần ăn uống đủ chất.",answer:!1,explain:"Ăn uống đủ chất mới là cách chính để khỏe mạnh."}]}],challenge:{questions:[{id:"kh4-benh-dinh-duong-25",type:"mc",q:"Một bạn hay chóng mặt, da xanh xao. Có thể bạn đang thiếu chất gì?",options:["Muối","Sắt","Đường","Chất béo"],answer:1,explain:"Thiếu sắt dễ bị thiếu máu, da xanh, hay chóng mặt."},{id:"kh4-benh-dinh-duong-26",type:"multi",q:"Những bệnh nào do thiếu chất dinh dưỡng?",options:["Quáng gà","Béo phì","Còi xương","Bướu cổ"],answers:[0,2,3],explain:"Béo phì do thừa năng lượng, không phải do thiếu chất."},{id:"kh4-benh-dinh-duong-27",type:"tf",q:"Ăn uống quá nhiều hay quá ít đều có thể gây bệnh.",answer:!0,explain:"Thiếu chất gây suy dinh dưỡng, thừa chất gây béo phì."},{id:"kh4-benh-dinh-duong-28",type:"mc",q:"Bữa trưa ở trường có cơm, cá, rau nhưng Vy chỉ ăn cơm. Lâu ngày Vy có thể bị gì?",options:["Thừa cân rất nhanh","Thiếu chất, suy dinh dưỡng","Bị bướu cổ ngay","Mắt sáng hơn trước"],answer:1,explain:"Chỉ ăn cơm thì thiếu chất đạm, vi-ta-min, chất khoáng."},{id:"kh4-benh-dinh-duong-29",type:"match",q:"Nối dấu hiệu với bệnh.",pairs:[["Cổ to bất thường","Bướu cổ"],["Nhìn kém lúc chập tối","Quáng gà"],["Cân nặng quá cao so với tuổi","Béo phì"]],explain:"Nhận biết dấu hiệu giúp phát hiện bệnh sớm."},{id:"kh4-benh-dinh-duong-30",type:"number",q:"Tháng trước Nam nặng 30 kg, tháng này nặng 31 kg. Nam đã tăng bao nhiêu ki-lô-gam?",answer:1,unit:"kg",explain:"Nam tăng 31 − 30 = 1 kg."}]},summary:["Thiếu chất có thể gây suy dinh dưỡng, thiếu máu, bướu cổ, còi xương, quáng gà.","Ăn quá nhiều, ít vận động dễ thừa cân, béo phì.","Phòng bệnh bằng ăn uống cân bằng, dùng muối i-ốt, vận động và theo dõi cân nặng."]},{id:"kh4-an-toan-thuc-pham",title:"Bài 26: An toàn thực phẩm",weeks:[29,29],learn:[{title:"Thực phẩm an toàn",text:"Thực phẩm an toàn là thực phẩm sạch, tươi, rõ nguồn gốc, còn hạn sử dụng, không ôi thiu, không nấm mốc.",example:"🥬 🐟"},{title:"Chế biến an toàn",text:"Rửa tay trước khi nấu và ăn; rửa sạch thực phẩm; nấu chín; dùng dụng cụ sạch; để riêng đồ sống và đồ chín.",example:"🧼 🔪 🍲"},{title:"Ngộ độc thực phẩm",text:"Ăn thức ăn bẩn, ôi thiu có thể bị đau bụng, nôn, tiêu chảy. Khi đó cần báo người lớn và đi khám.",example:"🤢 🏥"}],practice:[{questions:[{id:"kh4-an-toan-thuc-pham-01",type:"multi",q:"Dấu hiệu nào của thực phẩm an toàn?",options:["Tươi, sạch","Có mùi ôi thiu","Rõ nguồn gốc","Còn hạn sử dụng"],answers:[0,2,3],explain:"Thực phẩm an toàn tươi, sạch, rõ nguồn gốc, còn hạn."},{id:"kh4-an-toan-thuc-pham-02",type:"tf",q:"Trước khi ăn cần rửa tay bằng xà phòng.",emoji:"🧼",answer:!0,explain:"Rửa tay giúp loại bỏ vi khuẩn."},{id:"kh4-an-toan-thuc-pham-03",type:"mc",q:"Rau sống cần làm gì trước khi ăn?",options:["Để nguyên cả đất","Phơi ngoài nắng gắt","Rửa sạch nhiều lần","Ngâm vào nước ao"],answer:2,explain:"Rửa sạch giúp loại bỏ đất cát, vi khuẩn."},{id:"kh4-an-toan-thuc-pham-04",type:"tf",q:"Thức ăn có mùi ôi thiu vẫn ăn được nếu đun lại.",answer:!1,explain:"Thức ăn ôi thiu phải bỏ đi, đun lại cũng không an toàn."},{id:"kh4-an-toan-thuc-pham-05",type:"fill",q:"Trước khi mua đồ hộp, cần xem hạn sử … .",answer:["dụng"],explain:"Hạn sử dụng cho biết thực phẩm còn dùng được đến khi nào."},{id:"kh4-an-toan-thuc-pham-06",type:"mc",q:"Thịt, cá nên ăn thế nào?",options:["Ăn sống","Để ôi rồi ăn","Ăn khi còn đông đá","Nấu chín"],answer:3,explain:"Nấu chín diệt vi khuẩn, giun sán."},{id:"kh4-an-toan-thuc-pham-07",type:"tf",q:"Có thể mua thực phẩm không rõ nguồn gốc nếu giá rẻ.",answer:!1,explain:"Thực phẩm không rõ nguồn gốc có thể không an toàn."},{id:"kh4-an-toan-thuc-pham-08",type:"mc",q:"Dấu hiệu nào cho thấy có thể bị ngộ độc thực phẩm?",options:["Ăn ngon, ngủ ngon","Đau bụng, nôn, tiêu chảy","Da hồng hào, khỏe mạnh","Chạy nhảy vui vẻ cả ngày"],answer:1,explain:"Đau bụng, nôn, tiêu chảy là dấu hiệu ngộ độc thường gặp."}]},{questions:[{id:"kh4-an-toan-thuc-pham-09",type:"match",q:"Nối việc làm với lí do.",pairs:[["Nấu chín thức ăn","Diệt vi khuẩn"],["Đậy kín thức ăn","Tránh ruồi, bụi"],["Rửa tay trước khi ăn","Không đưa vi khuẩn vào miệng"]],explain:"Mỗi việc làm giúp thức ăn an toàn hơn."},{id:"kh4-an-toan-thuc-pham-10",type:"mc",q:"Vì sao nên để riêng thớt thái thịt sống và thớt thái đồ chín?",options:["Để thớt thái đồ chín được dùng lâu hơn","Để đồ sống chín nhanh hơn khi đem nấu","Để vi khuẩn từ đồ sống không lây sang đồ chín","Để mỗi chiếc thớt có màu sắc khác nhau"],answer:2,explain:"Đồ sống có thể có vi khuẩn, dễ lây sang đồ chín."},{id:"kh4-an-toan-thuc-pham-11",type:"multi",q:"Thực phẩm nào không nên mua?",options:["Cá tươi, mắt trong","Rau bị dập nát, có mùi lạ","Hộp sữa đã quá hạn sử dụng","Trứng còn nguyên vỏ, sạch"],answers:[1,2],explain:"Thực phẩm quá hạn, dập nát, có mùi lạ là không an toàn."},{id:"kh4-an-toan-thuc-pham-12",type:"tf",q:"Thức ăn chín để qua đêm ngoài trời nóng vẫn an toàn như mới nấu.",answer:!1,explain:"Để lâu ngoài trời nóng, vi khuẩn phát triển nhanh làm thức ăn hỏng."},{id:"kh4-an-toan-thuc-pham-13",type:"mc",q:"Vì sao cần đậy kín thức ăn?",options:["Để thức ăn có thêm chất dinh dưỡng","Để thức ăn nguội đi thật nhanh","Để thức ăn có thêm vị mặn hơn","Để ruồi, gián, bụi không bám vào"],answer:3,explain:"Ruồi, gián, bụi mang vi khuẩn vào thức ăn."},{id:"kh4-an-toan-thuc-pham-14",type:"tf",q:"Ruồi đậu vào thức ăn không gây hại gì.",answer:!1,explain:"Ruồi đậu nơi bẩn rồi mang vi khuẩn vào thức ăn."},{id:"kh4-an-toan-thuc-pham-15",type:"mc",q:"Khi mua đồ hộp, điều gì quan trọng cần kiểm tra?",options:["Hạn sử dụng, hộp không phồng, méo","Màu sắc vỏ hộp có đẹp hay không","Hộp có hình con vật dễ thương","Hộp to hay nhỏ hơn hộp bên cạnh"],answer:0,explain:"Hộp quá hạn, phồng, méo có thể đã hỏng."},{id:"kh4-an-toan-thuc-pham-16",type:"mc",q:"Khi bị ngộ độc thực phẩm, việc đầu tiên em cần làm là gì?",options:["Tự uống thuốc tùy ý","Báo ngay cho người lớn","Ăn thêm cho đỡ mệt","Đi ngủ và không nói"],answer:1,explain:"Người lớn sẽ đưa em đi khám kịp thời."}]},{questions:[{id:"kh4-an-toan-thuc-pham-17",type:"order",q:"Sắp xếp các việc khi chuẩn bị một bữa ăn an toàn.",items:["Rửa tay bằng xà phòng","Rửa sạch thực phẩm","Nấu chín thức ăn","Đậy kín thức ăn khi chưa ăn"],explain:"Rửa tay, rửa thực phẩm, nấu chín và đậy kín."},{id:"kh4-an-toan-thuc-pham-18",type:"mc",q:"Chi định mua bánh ở cổng trường thì thấy bánh để hở, có ruồi đậu. Chi nên làm gì?",options:["Mua về rồi thổi bụi đi","Không mua bánh đó","Mua và ăn ngay cho nóng","Mua nhiều để chia cho bạn"],answer:1,explain:"Bánh để hở, có ruồi đậu là không an toàn."},{id:"kh4-an-toan-thuc-pham-19",type:"multi",q:"Hộp sữa nào không nên uống?",options:["Hộp đã quá hạn","Hộp bị phồng","Hộp còn hạn, nguyên vẹn"],answers:[0,1],explain:"Hộp phồng hoặc quá hạn có thể đã hỏng."},{id:"kh4-an-toan-thuc-pham-20",type:"tf",q:"Thức ăn thừa nên được cất vào tủ lạnh và đun lại kĩ trước khi ăn.",answer:!0,explain:"Làm lạnh giúp thức ăn lâu hỏng, đun kĩ giúp diệt vi khuẩn."},{id:"kh4-an-toan-thuc-pham-21",type:"mc",q:"Sau khi ăn món gỏi cá sống, Nam bị đau bụng, nôn. Nguyên nhân có thể là gì?",options:["Nam uống quá nhiều nước lọc","Nam ngủ quá nhiều buổi trưa","Nam ăn quá nhiều rau luộc","Thức ăn chưa được nấu chín"],answer:3,explain:"Thức ăn sống có thể có vi khuẩn, giun sán."},{id:"kh4-an-toan-thuc-pham-22",type:"match",q:"Nối dấu hiệu với thực phẩm không an toàn.",pairs:[["Thịt có mùi hôi, nhớt","Thịt đã ôi"],["Bánh mì có đốm xanh","Bánh mì bị mốc"],["Hộp cá bị phồng","Đồ hộp đã hỏng"]],explain:"Nhận biết dấu hiệu giúp tránh ăn phải thực phẩm hỏng."},{id:"kh4-an-toan-thuc-pham-23",type:"mc",q:"Trước khi ăn trái cây mua ở chợ, cần làm gì?",options:["Ăn ngay cả vỏ chưa rửa","Lau qua bằng áo rồi ăn","Rửa sạch, gọt vỏ nếu cần","Ngâm vào nước ao cho mát"],answer:2,explain:"Rửa sạch giúp loại bỏ bụi bẩn và vi khuẩn."},{id:"kh4-an-toan-thuc-pham-24",type:"tf",q:"Chỉ cần thức ăn trông đẹp mắt là an toàn.",answer:!1,explain:"Thức ăn đẹp mắt vẫn có thể bẩn hoặc có chất độc hại."}]}],challenge:{questions:[{id:"kh4-an-toan-thuc-pham-25",type:"mc",q:"Vì sao không nên dùng chung dao thớt vừa thái thịt sống để thái ngay hoa quả?",options:["Vì hoa quả sẽ bị chín quá nhanh","Vi khuẩn từ thịt sống lây sang quả","Vì dao sẽ bị cùn đi rất nhanh","Vì thịt sống sẽ bị mất vị ngọt"],answer:1,explain:"Hoa quả ăn sống nên dễ nhiễm vi khuẩn từ thịt sống."},{id:"kh4-an-toan-thuc-pham-26",type:"multi",q:"Những việc nào giúp phòng ngộ độc thực phẩm?",options:["Rửa tay trước khi ăn","Bảo quản thức ăn đúng cách","Ăn chín, uống sôi","Ăn thức ăn để qua đêm ngoài trời"],answers:[0,1,2],explain:"Ăn chín, uống sôi, rửa tay, bảo quản đúng cách."},{id:"kh4-an-toan-thuc-pham-27",type:"tf",q:"Ngộ độc thực phẩm chỉ xảy ra khi ăn ở ngoài, không bao giờ xảy ra ở nhà.",answer:!1,explain:"Ở nhà cũng có thể bị ngộ độc nếu thức ăn không an toàn."},{id:"kh4-an-toan-thuc-pham-28",type:"mc",q:"Cá tươi thường có dấu hiệu nào?",emoji:"🐟",options:["Mắt đục, mang thâm, có mùi hôi","Mắt trong, mang đỏ, thịt chắc","Thịt mềm nhũn, ấn vào để lại vết","Vảy bong tróc, bụng phình to ra"],answer:1,explain:"Cá tươi có mắt trong, mang đỏ, thịt chắc."},{id:"kh4-an-toan-thuc-pham-29",type:"number",q:"Hộp sữa ghi hạn sử dụng đến ngày 20. Hôm nay là ngày 14 cùng tháng. Còn bao nhiêu ngày nữa thì đến hạn?",answer:6,unit:"ngày",explain:"Số ngày còn lại là 20 − 14 = 6 ngày."},{id:"kh4-an-toan-thuc-pham-30",type:"match",q:"Nối việc làm với nguy cơ.",pairs:[["Ăn rau sống chưa rửa","Nhiễm giun sán, vi khuẩn"],["Uống nước lã chưa đun","Đau bụng, tiêu chảy"],["Ăn thức ăn ôi thiu","Ngộ độc thực phẩm"]],explain:"Thói quen không an toàn dễ gây bệnh."}]},summary:["Thực phẩm an toàn: sạch, tươi, rõ nguồn gốc, còn hạn sử dụng.","Rửa tay, rửa sạch thực phẩm, nấu chín, để riêng đồ sống và đồ chín.","Khi có dấu hiệu ngộ độc thực phẩm, báo người lớn và đi khám."]},{id:"kh4-phong-tranh-duoi-nuoc",title:"Bài 27: Phòng tránh đuối nước",weeks:[30,31],learn:[{title:"Đuối nước nguy hiểm",text:"Đuối nước rất nguy hiểm. Đuối nước có thể xảy ra ở ao, hồ, sông, suối, biển, bể bơi, kể cả chậu, xô nước với trẻ nhỏ.",example:"🌊 ⚠️"},{title:"Phòng tránh",text:"Không chơi gần ao hồ, sông suối; không tự ý đi bơi; chỉ bơi khi có người lớn trông chừng; học bơi và kĩ năng an toàn.",example:"🏊 👀"},{title:"Khi đi bơi",text:"Khởi động trước khi bơi; không bơi khi vừa ăn no, đang đói hoặc mệt; làm theo quy định của bể bơi.",example:"🤸"},{title:"Khi thấy người đuối nước",text:"Gọi to người lớn đến giúp; ném phao, can nhựa, đưa sào hoặc dây cho người bị nạn; không tự nhảy xuống cứu.",example:"📢 🛟"}],practice:[{questions:[{id:"kh4-phong-tranh-duoi-nuoc-01",type:"tf",q:"Trẻ em có thể tự đi bơi ở sông khi không có người lớn.",answer:!1,explain:"Trẻ em chỉ bơi khi có người lớn biết bơi trông chừng."},{id:"kh4-phong-tranh-duoi-nuoc-02",type:"mc",q:"Khi thấy bạn bị đuối nước, em nên làm gì?",emoji:"🛟",options:["Gọi to người lớn và ném phao cho bạn","Tự nhảy xuống nước kéo bạn lên","Bỏ chạy về nhà, không nói với ai","Đứng xem rồi chờ bạn tự bơi vào"],answer:0,explain:"Gọi người lớn và dùng vật nổi để cứu, không tự nhảy xuống."},{id:"kh4-phong-tranh-duoi-nuoc-03",type:"multi",q:"Nơi nào có thể xảy ra đuối nước?",options:["Sân bóng khô ráo","Bể bơi","Ao, hồ","Sông, suối"],answers:[1,2,3],explain:"Đuối nước xảy ra ở những nơi có nước."},{id:"kh4-phong-tranh-duoi-nuoc-04",type:"tf",q:"Có thể bơi ngay khi vừa ăn no.",answer:!1,explain:"Không nên bơi khi vừa ăn no, đang đói hoặc mệt."},{id:"kh4-phong-tranh-duoi-nuoc-05",type:"fill",q:"Trước khi xuống nước bơi, em cần … động kĩ.",answer:["khởi"],explain:"Khởi động kĩ giúp tránh bị chuột rút."},{id:"kh4-phong-tranh-duoi-nuoc-06",type:"mc",q:"Em chỉ nên đi bơi khi nào?",options:["Có người lớn biết bơi trông chừng","Đi một mình vào buổi trưa nắng","Rủ các bạn nhỏ cùng ra sông","Lúc trời mưa to có sấm sét"],answer:0,explain:"Có người lớn trông chừng thì an toàn hơn."},{id:"kh4-phong-tranh-duoi-nuoc-07",type:"tf",q:"Chơi đùa sát mép ao, hồ là an toàn nếu không bước xuống nước.",answer:!1,explain:"Mép ao, hồ trơn trượt, có thể ngã xuống nước."},{id:"kh4-phong-tranh-duoi-nuoc-08",type:"mc",q:"Vật nào có thể ném cho người đuối nước bám vào?",options:["Hòn đá to và nặng","Cục sắt hoặc cục gạch","Bao xi măng còn đầy","Phao bơi, can nhựa rỗng"],answer:3,explain:"Phao, can nhựa rỗng nổi trên nước giúp người bị nạn bám vào."}]},{questions:[{id:"kh4-phong-tranh-duoi-nuoc-09",type:"match",q:"Nối việc làm với lí do.",pairs:[["Khởi động trước khi bơi","Tránh bị chuột rút"],["Học bơi","Biết cách tự bảo vệ dưới nước"],["Không bơi khi đói, mệt","Tránh kiệt sức dưới nước"]],explain:"Mỗi việc làm giúp bơi an toàn hơn."},{id:"kh4-phong-tranh-duoi-nuoc-10",type:"mc",q:"Vì sao không nên tự nhảy xuống nước cứu bạn khi mình chưa giỏi bơi?",options:["Vì nước sẽ làm quần áo bị ướt hết","Vì bạn sẽ tự bơi vào bờ được ngay","Vì người lớn không cho xuống nước chơi","Vì cả hai có thể cùng bị đuối nước"],answer:3,explain:"Người bị đuối nước có thể kéo cả người cứu chìm theo."},{id:"kh4-phong-tranh-duoi-nuoc-11",type:"tf",q:"Đậy nắp bể, chum, giếng nước giúp phòng đuối nước cho trẻ nhỏ.",answer:!0,explain:"Trẻ nhỏ có thể ngã vào bể, chum, giếng không có nắp."},{id:"kh4-phong-tranh-duoi-nuoc-12",type:"multi",q:"Hành động nào nguy hiểm?",options:["Tắm sông một mình","Mặc áo phao khi đi thuyền","Bơi ở bể có người cứu hộ","Chơi ở bờ ao trơn trượt"],answers:[0,3],explain:"Tắm sông một mình, chơi ở bờ ao trơn dễ bị đuối nước."},{id:"kh4-phong-tranh-duoi-nuoc-13",type:"mc",q:"Khi đi thuyền, đò, em cần làm gì?",options:["Đứng dậy chạy quanh thuyền","Thò tay nghịch nước thật mạnh","Mặc áo phao, ngồi yên","Ngồi lên mép thuyền cho mát"],answer:2,explain:"Áo phao giúp nổi nếu ngã xuống nước; ngồi yên để thuyền không chòng chành."},{id:"kh4-phong-tranh-duoi-nuoc-14",type:"tf",q:"Chỉ người không biết bơi mới có thể bị đuối nước.",answer:!1,explain:"Người biết bơi vẫn có thể bị đuối nước khi chuột rút, kiệt sức, nước xiết."},{id:"kh4-phong-tranh-duoi-nuoc-15",type:"mc",q:"Vì sao không nên bơi ở nơi có biển cấm hoặc nước chảy xiết?",options:["Vì rất dễ bị cuốn trôi, đuối nước","Vì nước ở đó quá trong và quá mát","Vì nơi đó có nhiều cá nhỏ dễ thương","Vì nơi đó có quá nhiều người đang bơi"],answer:0,explain:"Nước xiết có thể cuốn trôi cả người biết bơi."},{id:"kh4-phong-tranh-duoi-nuoc-16",type:"tf",q:"Trẻ nhỏ có thể bị đuối nước ngay trong chậu hoặc xô nước.",answer:!0,explain:"Trẻ nhỏ ngã úp mặt vào chậu, xô nước cũng rất nguy hiểm."}]},{questions:[{id:"kh4-phong-tranh-duoi-nuoc-17",type:"order",q:"Sắp xếp việc cần làm khi thấy người bị đuối nước.",items:["Gọi to để người lớn đến giúp","Tìm phao, sào hoặc dây ở gần","Ném phao hoặc đưa sào cho người bị nạn","Khi người bị nạn lên bờ, gọi cấp cứu 115"],explain:"Gọi người giúp, dùng vật nổi để cứu từ trên bờ, rồi gọi cấp cứu."},{id:"kh4-phong-tranh-duoi-nuoc-18",type:"mc",q:"Hè này Dũng về quê, các bạn rủ ra sông tắm. Dũng nên làm gì?",options:["Từ chối, rủ các bạn chơi trò khác","Đi theo các bạn nhưng chỉ đứng xem","Đi tắm cùng các bạn cho vui","Lén đi một mình vào buổi trưa"],answer:0,explain:"Không tắm sông khi không có người lớn trông chừng."},{id:"kh4-phong-tranh-duoi-nuoc-19",type:"multi",q:"Những việc nào giúp phòng tránh đuối nước?",options:["Không chơi gần ao hồ","Thi lặn lâu dưới sông","Học bơi có người hướng dẫn","Mặc áo phao khi đi thuyền"],answers:[0,2,3],explain:"Học bơi, mặc áo phao và tránh xa nơi nguy hiểm."},{id:"kh4-phong-tranh-duoi-nuoc-20",type:"tf",q:"Bị chuột rút khi đang bơi, cần bình tĩnh, gọi người giúp và bám vào vật nổi.",answer:!0,explain:"Bình tĩnh giúp không bị sặc nước và dễ được cứu."},{id:"kh4-phong-tranh-duoi-nuoc-21",type:"mc",q:"Đang bơi ở bể ngoài trời thì có sấm sét. Em nên làm gì?",options:["Lặn xuống sâu để tránh","Lên bờ ngay","Bơi tiếp cho xong buổi","Đứng giữa bể chờ hết mưa"],answer:1,explain:"Bơi khi có sấm sét rất nguy hiểm."},{id:"kh4-phong-tranh-duoi-nuoc-22",type:"number",q:"Lớp 4A có 35 học sinh, 21 bạn đã biết bơi. Còn bao nhiêu bạn chưa biết bơi?",answer:14,unit:"bạn",explain:"Số bạn chưa biết bơi là 35 − 21 = 14 bạn."},{id:"kh4-phong-tranh-duoi-nuoc-23",type:"match",q:"Nối tình huống với cách xử lí.",pairs:[["Đi đò qua sông","Mặc áo phao"],["Thấy bạn chới với dưới ao","Gọi người lớn, ném phao"],["Bể nước trong nhà không có nắp","Nhờ người lớn đậy kín"]],explain:"Mỗi tình huống cần xử lí an toàn."},{id:"kh4-phong-tranh-duoi-nuoc-24",type:"tf",q:"Có thể thi xem ai lặn lâu nhất ở sông khi không có người lớn.",answer:!1,explain:"Thi lặn ở sông rất dễ gây đuối nước."}]}],challenge:{questions:[{id:"kh4-phong-tranh-duoi-nuoc-25",type:"mc",q:"Vì sao nên đưa sào, dây cho người đuối nước thay vì tự nhảy xuống?",options:["Để người đuối nước tự bơi nhanh hơn","Để cứu bạn mà mình vẫn an toàn trên bờ","Để mình không bị ướt quần áo đi học","Để người lớn không phải đến giúp nữa"],answer:1,explain:"Cứu từ trên bờ giúp cả hai người an toàn."},{id:"kh4-phong-tranh-duoi-nuoc-26",type:"multi",q:"Khi đi tắm biển cùng gia đình, những việc nào đúng?",options:["Không xuống nước khi có biển báo nguy hiểm","Tắm biển khi trời tối","Bơi ở khu vực có cứu hộ","Bơi ra thật xa bờ"],answers:[0,2],explain:"Tắm ở nơi có cứu hộ và làm theo biển báo."},{id:"kh4-phong-tranh-duoi-nuoc-27",type:"tf",q:"Biết bơi rồi thì có thể bơi ở bất cứ đâu mà không cần cẩn thận.",answer:!1,explain:"Người biết bơi vẫn cần bơi ở nơi an toàn, có người trông chừng."},{id:"kh4-phong-tranh-duoi-nuoc-28",type:"mc",q:"Em bé hàng xóm hay chơi gần cái giếng không có nắp. Em nên làm gì?",options:["Báo người lớn để đậy nắp giếng","Mặc kệ vì đó không phải nhà mình","Rủ em bé cùng nhìn xuống giếng","Ném đồ chơi xuống giếng cho em"],answer:0,explain:"Giếng không nắp rất nguy hiểm cho trẻ nhỏ."},{id:"kh4-phong-tranh-duoi-nuoc-29",type:"order",q:"Sắp xếp việc chuẩn bị trước khi xuống bể bơi.",items:["Thay đồ bơi","Tắm tráng qua nước sạch","Khởi động kĩ","Xuống bể khi có người lớn trông"],explain:"Chuẩn bị đủ, khởi động rồi mới xuống nước."},{id:"kh4-phong-tranh-duoi-nuoc-30",type:"match",q:"Nối vật dụng với tác dụng.",pairs:[["Áo phao","Giúp nổi trên mặt nước"],["Sào tre dài","Đưa cho người bị nạn bám"],["Kính bơi","Bảo vệ mắt khi bơi"]],explain:"Mỗi vật dụng giúp bơi và cứu người an toàn hơn."}]},summary:["Đuối nước rất nguy hiểm, có thể xảy ra ở mọi nơi có nước.","Không tự ý đi bơi; học bơi, khởi động kĩ, bơi khi có người lớn trông chừng.","Thấy người đuối nước: gọi người lớn, ném vật nổi, không tự nhảy xuống cứu."]}]},{id:"sinh-vat-moi-truong",title:"Sinh vật và môi trường",lessons:[{id:"kh4-chuoi-thuc-an",title:"Bài 28: Chuỗi thức ăn",weeks:[32,33],learn:[{title:"Chuỗi thức ăn",text:"Chuỗi thức ăn cho biết sinh vật này là thức ăn của sinh vật kia. Ví dụ: cỏ là thức ăn của thỏ, thỏ là thức ăn của cáo.",example:"🌿 🐇 🦊"},{title:"Bắt đầu từ thực vật",text:"Chuỗi thức ăn thường bắt đầu bằng thực vật. Thực vật tự chế tạo chất dinh dưỡng; động vật ăn thực vật; động vật khác lại ăn chúng.",example:"🌾 🐭 🐍 🦅"},{title:"Cách vẽ sơ đồ",text:"Trong sơ đồ chuỗi thức ăn, mũi tên chỉ từ sinh vật bị ăn tới sinh vật ăn nó.",example:"Cỏ → Thỏ → Cáo"}],practice:[{questions:[{id:"kh4-chuoi-thuc-an-01",type:"order",q:"Sắp xếp thành chuỗi thức ăn bắt đầu từ cỏ.",items:["Cỏ","Thỏ","Cáo"],explain:"Cỏ là thức ăn của thỏ, thỏ là thức ăn của cáo."},{id:"kh4-chuoi-thuc-an-02",type:"mc",q:"Trong chuỗi thức ăn gồm cỏ, thỏ, cáo, sinh vật nào là thức ăn của thỏ?",emoji:"🐇",options:["Cáo","Đất","Nước","Cỏ"],answer:3,explain:"Thỏ ăn cỏ."},{id:"kh4-chuoi-thuc-an-03",type:"tf",q:"Chuỗi thức ăn thường bắt đầu bằng động vật ăn thịt.",answer:!1,explain:"Chuỗi thức ăn thường bắt đầu bằng thực vật."},{id:"kh4-chuoi-thuc-an-04",type:"mc",q:"Trong chuỗi thức ăn gồm rau cải, sâu, chim sâu, con nào ăn sâu?",options:["Rau cải","Con thỏ","Con trâu","Chim sâu"],answer:3,explain:"Chim sâu ăn sâu."},{id:"kh4-chuoi-thuc-an-05",type:"fill",q:"Cỏ, thỏ, cáo tạo thành một chuỗi … ăn.",answer:["thức"],explain:"Đó là một chuỗi thức ăn."},{id:"kh4-chuoi-thuc-an-06",type:"tf",q:"Trong chuỗi thức ăn gồm cỏ, thỏ, cáo, cáo là thức ăn của thỏ.",answer:!1,explain:"Ngược lại, thỏ là thức ăn của cáo."},{id:"kh4-chuoi-thuc-an-07",type:"order",q:"Sắp xếp chuỗi thức ăn bắt đầu từ cây lúa.",items:["Lúa","Chuột","Rắn"],explain:"Chuột ăn lúa, rắn ăn chuột."},{id:"kh4-chuoi-thuc-an-08",type:"multi",q:"Những con vật nào ăn thực vật?",options:["Châu chấu","Đại bàng","Sâu","Cáo","Thỏ"],answers:[0,2,4],explain:"Thỏ, châu chấu, sâu ăn thực vật; cáo, đại bàng ăn thịt."}]},{questions:[{id:"kh4-chuoi-thuc-an-09",type:"match",q:"Nối sinh vật với thức ăn của nó.",pairs:[["Thỏ","Cỏ"],["Chim sâu","Sâu"],["Rắn","Chuột"]],explain:"Mỗi sinh vật ăn một loại thức ăn trong chuỗi."},{id:"kh4-chuoi-thuc-an-10",type:"mc",q:"Vì sao chuỗi thức ăn thường bắt đầu bằng thực vật?",options:["Vì thực vật ăn được tất cả động vật","Vì thực vật đứng ở cuối mọi chuỗi","Vì thực vật không cần ánh sáng","Vì thực vật tự tạo được chất dinh dưỡng"],answer:3,explain:"Thực vật tự chế tạo chất dinh dưỡng nhờ ánh sáng."},{id:"kh4-chuoi-thuc-an-11",type:"tf",q:"Trong sơ đồ chuỗi thức ăn, mũi tên chỉ từ sinh vật ăn tới sinh vật bị ăn.",answer:!1,explain:"Mũi tên chỉ từ sinh vật bị ăn tới sinh vật ăn nó."},{id:"kh4-chuoi-thuc-an-12",type:"mc",q:"Trong chuỗi thức ăn gồm lúa, chuột, rắn, đại bàng, con nào ăn rắn?",emoji:"🦅",options:["Chuột","Cây lúa","Châu chấu","Đại bàng"],answer:3,explain:"Đại bàng đứng sau rắn trong chuỗi."},{id:"kh4-chuoi-thuc-an-13",type:"mc",q:"Câu nào đúng?",emoji:"🐸",options:["Ếch là thức ăn của châu chấu","Châu chấu là thức ăn của ếch","Cỏ là thức ăn của ếch","Rắn là thức ăn của châu chấu"],answer:1,explain:"Ếch ăn châu chấu."},{id:"kh4-chuoi-thuc-an-14",type:"tf",q:"Một chuỗi thức ăn chỉ có thể có hai sinh vật.",answer:!1,explain:"Chuỗi thức ăn có thể có ba, bốn sinh vật hoặc hơn."},{id:"kh4-chuoi-thuc-an-15",type:"mc",q:"Nếu chuột trên cánh đồng bị bắt hết, rắn sẽ thế nào?",options:["Có nhiều thức ăn hơn","Chuyển sang ăn cỏ","Không bị ảnh hưởng","Thiếu thức ăn"],answer:3,explain:"Chuột là thức ăn của rắn."},{id:"kh4-chuoi-thuc-an-16",type:"tf",q:"Động vật ăn thịt cũng phụ thuộc vào thực vật qua chuỗi thức ăn.",answer:!0,explain:"Con mồi của chúng ăn thực vật."}]},{questions:[{id:"kh4-chuoi-thuc-an-17",type:"order",q:"Sắp xếp chuỗi thức ăn gồm châu chấu, cỏ, ếch, rắn.",items:["Cỏ","Châu chấu","Ếch","Rắn"],explain:"Châu chấu ăn cỏ, ếch ăn châu chấu, rắn ăn ếch."},{id:"kh4-chuoi-thuc-an-18",type:"mc",q:"Ruộng lúa có nhiều chuột phá hại. Nên bảo vệ loài nào để giúp bắt chuột?",emoji:"🦉",options:["Châu chấu","Sâu cuốn lá","Ốc bươu vàng","Mèo, cú mèo"],answer:3,explain:"Mèo, cú mèo ăn chuột."},{id:"kh4-chuoi-thuc-an-19",type:"multi",q:"Trong ao có tảo, cá nhỏ, cá lớn. Những câu nào đúng?",options:["Tảo là thức ăn của cá nhỏ","Cá nhỏ là thức ăn của cá lớn","Cá lớn là thức ăn của tảo"],answers:[0,1],explain:"Chuỗi thức ăn: tảo, cá nhỏ, cá lớn."},{id:"kh4-chuoi-thuc-an-20",type:"mc",q:"Nếu chim sâu trong vườn bị bắt hết, điều gì có thể xảy ra?",options:["Sâu giảm đi, rau tốt hơn","Sâu nhiều lên, rau bị hại","Rau không còn cần ánh sáng","Chim sâu sẽ mọc lại ngay"],answer:1,explain:"Không còn chim sâu ăn sâu nên sâu tăng lên."},{id:"kh4-chuoi-thuc-an-21",type:"tf",q:"Săn bắt quá nhiều một loài có thể ảnh hưởng đến cả chuỗi thức ăn.",answer:!0,explain:"Các sinh vật trong chuỗi liên quan chặt chẽ với nhau."},{id:"kh4-chuoi-thuc-an-22",type:"order",q:"Sắp xếp chuỗi thức ăn trong vườn rau.",items:["Rau cải","Sâu","Chim sâu"],explain:"Sâu ăn rau, chim sâu ăn sâu."},{id:"kh4-chuoi-thuc-an-23",type:"match",q:"Nối chuỗi thức ăn còn thiếu với sinh vật phù hợp.",pairs:[["Cỏ, …, cáo","Thỏ"],["Lúa, …, rắn","Chuột"],["Rau cải, …, chim sâu","Sâu"]],explain:"Sinh vật ở giữa ăn sinh vật trước và là thức ăn của sinh vật sau."},{id:"kh4-chuoi-thuc-an-24",type:"fill",q:"Sinh vật đứng đầu chuỗi thức ăn thường là thực … .",answer:["vật"],explain:"Thực vật thường đứng đầu chuỗi thức ăn."}]}],challenge:{questions:[{id:"kh4-chuoi-thuc-an-25",type:"mc",q:"Vì sao không nên phun thuốc trừ sâu quá nhiều làm chết cả chim sâu, ếch nhái?",options:["Vì chúng giúp ăn bớt sâu hại","Vì chim sâu là thức ăn của lúa","Vì sâu hại không ăn được rau","Vì chim sâu làm rau mọc chậm"],answer:0,explain:"Chim sâu, ếch nhái ăn sâu bọ, giúp bảo vệ cây trồng."},{id:"kh4-chuoi-thuc-an-26",type:"order",q:"Sắp xếp chuỗi thức ăn gồm bốn sinh vật trên cánh đồng.",items:["Lúa","Chuột","Rắn","Đại bàng"],explain:"Chuột ăn lúa, rắn ăn chuột, đại bàng ăn rắn."},{id:"kh4-chuoi-thuc-an-27",type:"multi",q:"Những sinh vật nào thường đứng đầu chuỗi thức ăn?",options:["Đại bàng","Cây lúa","Tảo","Hổ","Cỏ"],answers:[1,2,4],explain:"Thực vật như cỏ, lúa, tảo đứng đầu chuỗi."},{id:"kh4-chuoi-thuc-an-28",type:"tf",q:"Trong chuỗi thức ăn gồm cỏ, thỏ, cáo, nếu cỏ bị cháy hết thì cả thỏ và cáo đều bị ảnh hưởng.",answer:!0,explain:"Thỏ thiếu thức ăn, rồi cáo cũng thiếu thức ăn."},{id:"kh4-chuoi-thuc-an-29",type:"mc",q:"Theo thứ tự từ sinh vật bị ăn đến sinh vật ăn nó, chuỗi nào đúng?",options:["Chim sâu, sâu, lá cây","Lá cây, sâu, chim sâu","Sâu, lá cây, chim sâu","Lá cây, chim sâu, sâu"],answer:1,explain:"Sâu ăn lá, chim sâu ăn sâu."},{id:"kh4-chuoi-thuc-an-30",type:"mc",q:"Ở một vùng, người ta bắt hết cáo. Lúc đầu số thỏ sẽ thế nào?",options:["Giảm đi","Không đổi","Tăng lên","Hết ngay"],answer:2,explain:"Không còn cáo ăn thỏ nên thỏ tăng lên."}]},summary:["Chuỗi thức ăn cho biết sinh vật này là thức ăn của sinh vật kia.","Chuỗi thức ăn thường bắt đầu bằng thực vật.","Mũi tên trong sơ đồ chỉ từ sinh vật bị ăn tới sinh vật ăn nó."]},{id:"kh4-vai-tro-thuc-vat",title:"Bài 29: Vai trò của thực vật đối với sự sống",weeks:[34,35],learn:[{title:"Thực vật cung cấp thức ăn",text:"Thực vật là thức ăn của con người và nhiều loài động vật; nhờ đó chất dinh dưỡng đi qua cả chuỗi thức ăn.",example:"🌾 🐄 🧍"},{title:"Thực vật với không khí",text:"Cây xanh lấy khí các-bô-níc và thải ra khí ô-xi, giúp không khí trong lành.",example:"🌳 🌬️"},{title:"Nơi ở và giữ đất",text:"Cây cối, rừng là nơi ở của nhiều loài động vật; rễ cây giữ đất, giảm xói mòn.",example:"🌲 🐒 🐦"},{title:"Bảo vệ thực vật",text:"Trồng cây, bảo vệ rừng, không chặt phá cây bừa bãi là bảo vệ thức ăn và nơi ở của nhiều sinh vật.",example:"🌱 💚"}],practice:[{questions:[{id:"kh4-vai-tro-thuc-vat-01",type:"tf",q:"Thực vật cung cấp thức ăn cho con người và nhiều loài động vật.",answer:!0,explain:"Gạo, rau, quả, cỏ đều là thực vật."},{id:"kh4-vai-tro-thuc-vat-02",type:"mc",q:"Cây xanh thải ra khí nào giúp không khí trong lành?",emoji:"🌳",options:["Khí ô-xi","Khí các-bô-níc","Khói bụi","Khí độc"],answer:0,explain:"Cây xanh thải ra khí ô-xi."},{id:"kh4-vai-tro-thuc-vat-03",type:"multi",q:"Thực phẩm nào có nguồn gốc từ thực vật?",options:["Rau muống","Gạo","Quả chuối","Trứng vịt","Thịt gà"],answers:[0,1,2],explain:"Gạo, rau, quả lấy từ cây."},{id:"kh4-vai-tro-thuc-vat-04",type:"tf",q:"Nếu không có thực vật, động vật ăn thịt vẫn sống bình thường.",answer:!1,explain:"Không có thực vật thì con mồi chết, động vật ăn thịt cũng không có thức ăn."},{id:"kh4-vai-tro-thuc-vat-05",type:"fill",q:"Rừng là nơi … của nhiều loài động vật.",answer:["ở","sống"],explain:"Nhiều loài động vật sống trong rừng."},{id:"kh4-vai-tro-thuc-vat-06",type:"mc",q:"Việc nào giúp bảo vệ thực vật?",options:["Chặt phá rừng","Đốt nương rẫy bừa bãi","Trồng cây và bảo vệ rừng","Bẻ cành cây ở công viên"],answer:2,explain:"Trồng cây, giữ rừng là bảo vệ thực vật."},{id:"kh4-vai-tro-thuc-vat-07",type:"tf",q:"Chặt phá rừng chỉ làm mất cây, không ảnh hưởng gì đến động vật.",answer:!1,explain:"Mất rừng, động vật mất nơi ở và thức ăn."},{id:"kh4-vai-tro-thuc-vat-08",type:"mc",q:"Con vật nào ăn thực vật?",emoji:"🐘",options:["Con hổ","Con cá mập","Con đại bàng","Con voi"],answer:3,explain:"Voi ăn cỏ, lá, cành cây."}]},{questions:[{id:"kh4-vai-tro-thuc-vat-09",type:"match",q:"Nối vai trò của thực vật với ví dụ.",pairs:[["Cung cấp thức ăn","Thỏ ăn cỏ"],["Cung cấp nơi ở","Chim làm tổ trên cây"],["Làm không khí trong lành","Cây thải ra khí ô-xi"]],explain:"Thực vật có nhiều vai trò với sự sống."},{id:"kh4-vai-tro-thuc-vat-10",type:"mc",q:"Hổ chỉ ăn thịt. Vì sao hổ vẫn cần có thực vật?",emoji:"🐅",options:["Vì hổ thỉnh thoảng ăn cỏ thay thịt","Vì con mồi của hổ ăn thực vật","Vì hổ uống nước từ lá cây","Vì hổ ngủ dưới gốc cây"],answer:1,explain:"Hươu, nai ăn thực vật, rồi hổ ăn hươu, nai."},{id:"kh4-vai-tro-thuc-vat-11",type:"multi",q:"Rừng có vai trò gì?",options:["Làm không khí trong lành","Làm tăng khói bụi","Là nơi ở của nhiều loài động vật","Giữ đất, giảm lũ lụt"],answers:[0,2,3],explain:"Rừng là nơi ở của động vật, giữ đất và làm không khí trong lành."},{id:"kh4-vai-tro-thuc-vat-12",type:"tf",q:"Cây xanh lấy khí ô-xi và thải ra khí các-bô-níc khi chế tạo chất dinh dưỡng.",answer:!1,explain:"Khi chế tạo chất dinh dưỡng, cây lấy khí các-bô-níc và thải ra khí ô-xi."},{id:"kh4-vai-tro-thuc-vat-13",type:"mc",q:"Khi một khu rừng bị cháy, động vật sống ở đó gặp khó khăn gì?",options:["Mất nơi ở và nguồn thức ăn","Có thêm nhiều thức ăn ngon hơn","Có thêm nhiều nơi ở rộng rãi","Không gặp bất kì khó khăn nào"],answer:0,explain:"Cháy rừng làm mất cây, mất nơi ở và thức ăn."},{id:"kh4-vai-tro-thuc-vat-14",type:"tf",q:"Chỉ có cây ăn quả mới có ích cho con người.",answer:!1,explain:"Mọi loại cây đều có vai trò như cho bóng mát, ô-xi, giữ đất."},{id:"kh4-vai-tro-thuc-vat-15",type:"mc",q:"Trong chuỗi thức ăn gồm cây, sâu, chim sâu, diều hâu, sinh vật nào tự chế tạo chất dinh dưỡng?",options:["Sâu","Chim sâu","Diều hâu","Cây"],answer:3,explain:"Chỉ cây xanh tự chế tạo chất dinh dưỡng nhờ ánh sáng."},{id:"kh4-vai-tro-thuc-vat-16",type:"mc",q:"Vì sao trồng cây xanh ở thành phố rất quan trọng?",options:["Cây xanh làm khói bụi tăng lên nhiều","Cây xanh làm đường phố nóng lên","Cây xanh làm tiếng ồn to hơn","Cây cho bóng mát, làm không khí trong lành"],answer:3,explain:"Cây xanh cho bóng mát, giữ bụi, thải ra khí ô-xi."}]},{questions:[{id:"kh4-vai-tro-thuc-vat-17",type:"order",q:"Sắp xếp để thấy chất dinh dưỡng từ thực vật đi tới con cáo.",items:["Cỏ chế tạo chất dinh dưỡng nhờ ánh sáng","Thỏ ăn cỏ","Cáo ăn thỏ"],explain:"Chất dinh dưỡng đi từ cỏ sang thỏ rồi sang cáo."},{id:"kh4-vai-tro-thuc-vat-18",type:"mc",q:"Một quả đồi bị chặt hết cây. Khi mưa to, điều gì dễ xảy ra?",options:["Đất được giữ chặt hơn trước","Có thêm nhiều động vật đến ở","Đất bị xói mòn, sạt lở","Không khí trong lành hơn trước"],answer:2,explain:"Không còn rễ cây giữ đất nên đất dễ bị nước cuốn trôi."},{id:"kh4-vai-tro-thuc-vat-19",type:"multi",q:"Lớp em có thể làm gì để bảo vệ thực vật?",options:["Trồng và chăm sóc cây ở trường","Không bẻ cành, hái hoa nơi công cộng","Giẫm lên thảm cỏ","Khắc tên lên thân cây"],answers:[0,1],explain:"Chăm sóc và không làm hại cây là bảo vệ thực vật."},{id:"kh4-vai-tro-thuc-vat-20",type:"tf",q:"Bảo vệ thực vật cũng là bảo vệ các loài động vật.",answer:!0,explain:"Thực vật là thức ăn và nơi ở của động vật."},{id:"kh4-vai-tro-thuc-vat-21",type:"mc",q:"Nếu cỏ trên đồng chết hết vì hạn hán, loài nào bị ảnh hưởng trước tiên?",options:["Các loài cá ở dưới biển sâu","Các loài chim ăn thịt trên núi","Không có loài nào bị ảnh hưởng","Các loài ăn cỏ như bò, thỏ"],answer:3,explain:"Loài ăn cỏ mất thức ăn trước tiên."},{id:"kh4-vai-tro-thuc-vat-22",type:"number",q:"Lớp 4B trồng 4 hàng cây, mỗi hàng 9 cây. Lớp trồng được bao nhiêu cây?",answer:36,unit:"cây",explain:"Số cây là 9 × 4 = 36 cây."},{id:"kh4-vai-tro-thuc-vat-23",type:"match",q:"Nối việc làm với kết quả.",pairs:[["Trồng rừng","Thêm nơi ở cho động vật"],["Chặt phá rừng","Động vật mất nơi ở"],["Trồng cây ven đường","Không khí trong lành hơn"]],explain:"Việc làm của con người ảnh hưởng tới thực vật và động vật."},{id:"kh4-vai-tro-thuc-vat-24",type:"tf",q:"Đốt rừng làm nương rẫy là cách bảo vệ thực vật.",answer:!1,explain:"Đốt rừng phá hủy thực vật và nơi ở của động vật."}]}],challenge:{questions:[{id:"kh4-vai-tro-thuc-vat-25",type:"mc",q:"Vì sao nói không có thực vật thì động vật không thể sống?",options:["Vì thực vật đứng đầu chuỗi thức ăn","Vì động vật đều ăn đất và đá","Vì thực vật ăn thịt động vật","Vì động vật không cần thức ăn"],answer:0,explain:"Mọi chuỗi thức ăn đều cần thực vật cung cấp chất dinh dưỡng."},{id:"kh4-vai-tro-thuc-vat-26",type:"multi",q:"Thực vật giúp ích gì cho sự sống?",options:["Cung cấp thức ăn","Làm tăng khói bụi","Làm nơi ở cho động vật","Cung cấp khí ô-xi"],answers:[0,2,3],explain:"Thực vật cho thức ăn, ô-xi và nơi ở."},{id:"kh4-vai-tro-thuc-vat-27",type:"tf",q:"Cây xanh vừa là thức ăn, vừa là nơi ở của nhiều loài động vật.",answer:!0,explain:"Ví dụ: sâu ăn lá cây, chim làm tổ trên cây."},{id:"kh4-vai-tro-thuc-vat-28",type:"mc",q:"Một vùng đồi trọc được trồng lại rừng sau nhiều năm. Điều gì có thể xảy ra?",options:["Các loài động vật ở đó bỏ đi nơi khác hết","Nhiều loài động vật quay về sinh sống","Đất ở vùng đó bị xói mòn nhiều hơn trước","Không khí ở vùng đó ô nhiễm nặng hơn"],answer:1,explain:"Rừng có thức ăn và nơi ở nên động vật quay về."},{id:"kh4-vai-tro-thuc-vat-29",type:"order",q:"Sắp xếp chuỗi thức ăn dưới ao.",items:["Tảo","Cá nhỏ","Cá lớn"],explain:"Cá nhỏ ăn tảo, cá lớn ăn cá nhỏ."},{id:"kh4-vai-tro-thuc-vat-30",type:"match",q:"Nối sinh vật với vai trò trong chuỗi thức ăn.",pairs:[["Cây ngô","Tự chế tạo chất dinh dưỡng"],["Châu chấu","Ăn thực vật"],["Con ếch","Ăn động vật nhỏ"]],explain:"Mỗi sinh vật giữ một vị trí trong chuỗi thức ăn."}]},summary:["Thực vật là thức ăn của con người và động vật, đứng đầu chuỗi thức ăn.","Cây xanh thải ra khí ô-xi, là nơi ở của động vật, giữ đất.","Em trồng cây, bảo vệ rừng để bảo vệ sự sống."]}]}],g={grade:4,subject:n,title:h,review:t,topics:i};export{g as default,c as grade,t as review,n as subject,h as title,i as topics};
